/// One identity per process lifetime for placement fencing. PID is retained in
/// worker names for diagnostics, but is not authority: containers commonly
/// share PID 1 and operating systems reuse PIDs after restart.
static STATELESS_PROCESS_INSTANCE_ID: OnceLock<String> = OnceLock::new();

fn stateless_process_instance_id() -> &'static str {
    STATELESS_PROCESS_INSTANCE_ID
        .get_or_init(|| Uuid::new_v4().simple().to_string())
        .as_str()
}

fn stateless_worker_id_for_instance(
    process_id: u32,
    process_instance_id: &str,
    execution_id: &str,
) -> super::run_loop::state::WorkerId {
    super::run_loop::state::WorkerId::new(format!(
        "inproc-{process_id}-{process_instance_id}-{execution_id}"
    ))
}

pub(crate) fn stateless_worker_id_for_exact_segment(
    exact_segment: &str,
) -> super::run_loop::state::WorkerId {
    stateless_worker_id_for_instance(
        std::process::id(),
        stateless_process_instance_id(),
        exact_segment,
    )
}

const STATELESS_EFFECT_RESOLUTION_PARAMETER: &str = "stateless_effect_resolution";
const STATELESS_EFFECT_ADOPT_SUCCEEDED: &str = "adopt_succeeded";
const STATELESS_EFFECT_AUTHORIZE_REFIRE: &str = "authorize_refire";

/// Stable, bounded UI key for one indeterminate effect.
///
/// Effect ids contain provider/tool lineage and can be long. The pause needs a
/// deterministic join key, not that content on every generic pending-input
/// index, so it carries a digest and keeps the full id only in the trusted
/// pause question when disclosure policy allows it.
fn stateless_effect_resolution_input_id(
    source_segment: &str,
    effect_id: &super::run_loop::effects::EffectId,
) -> String {
    // The effect id is stable only inside one loop-state segment. Sibling
    // resume/refinement/pipeline segments can legitimately repeat the same
    // provider/tool-call ids, so an operator answer must bind both coordinates.
    let mut binding = Sha256::new();
    binding.update(b"magician.stateless-effect-resolution.v2\0");
    binding.update((source_segment.len() as u64).to_le_bytes());
    binding.update(source_segment.as_bytes());
    binding.update((effect_id.as_str().len() as u64).to_le_bytes());
    binding.update(effect_id.as_str().as_bytes());
    format!("stateless-effect-resolution-{:x}", binding.finalize())
}

fn stateless_effect_resolution_from_value(
    value: Option<&Value>,
) -> Option<super::run_loop::driver_worker::EffectResolution> {
    use super::run_loop::driver_worker::EffectResolution;

    match value.and_then(Value::as_str) {
        Some(STATELESS_EFFECT_ADOPT_SUCCEEDED) => Some(EffectResolution::AdoptSucceeded),
        Some(STATELESS_EFFECT_AUTHORIZE_REFIRE) => Some(EffectResolution::AuthorizeRefire),
        _ => None,
    }
}

