/// Fire-and-forget registration of durable artifact after a successful file
/// write. Checks if the file action target is inside the durable store base
/// path.
fn try_register_durable_file_action(
    file_action: &crate::magician_v2::execution::actions::FileAction,
    executors: &ActionExecutors,
) {
    let store = match executors
        .durable_store
        .lock()
        .ok()
        .and_then(|guard| guard.clone())
    {
        Some(store) => store,
        None => return,
    };
    let target_path = match file_action {
        crate::magician_v2::execution::actions::FileAction::Write { path, .. }
        | crate::magician_v2::execution::actions::FileAction::Append { path, .. } => path.clone(),
        crate::magician_v2::execution::actions::FileAction::Copy { destination, .. } => {
            destination.clone()
        },
        _ => return,
    };
    let abs_target = std::fs::canonicalize(&target_path).unwrap_or_else(|_| target_path.clone());
    let abs_base =
        std::fs::canonicalize(&store.base_path).unwrap_or_else(|_| store.base_path.clone());
    if !abs_target.starts_with(&abs_base) {
        return;
    }
    let rel = match abs_target.strip_prefix(&abs_base) {
        Ok(r) => r,
        Err(_) => return,
    };
    let components: Vec<&str> = rel
        .components()
        .filter_map(|c| c.as_os_str().to_str())
        .collect();
    if components.len() < 2 {
        return;
    }
    let namespace = components[0];
    let name = components[1..].join("/");
    // Stamp source_task_id into frontmatter for provenance tracking.
    // Uses fs2 file lock on the same fd for read-modify-write to avoid races
    // with concurrent DurableArtifactStore operations.
    // C4 fix: Run in spawn_blocking to avoid blocking the tokio runtime thread.
    let identity = executors.run_identity.get();
    let task_id = identity.task_id.clone();
    let execution_id = identity.execution_id.clone();
    let agent_id_val = identity.agent_id.clone();
    // Stamp provenance if ANY of task/execution/agent are available (not gated on
    // task_id alone).
    let has_provenance = task_id.is_some() || execution_id.is_some() || agent_id_val.is_some();
    if has_provenance {
        let abs_target_clone = abs_target.clone();
        // I6 fix: Spawn and log errors instead of silently dropping the JoinHandle.
        // Crash-safe: write to temp file, then atomic rename under exclusive lock.
        let stamp_handle = tokio::task::spawn_blocking(move || {
            use std::io::{Read as _, Write as _};

            use fs2::FileExt;
            if let Ok(mut file) = std::fs::OpenOptions::new()
                .read(true)
                .write(true)
                .open(&abs_target_clone)
            {
                if file.lock_exclusive().is_ok() {
                    let mut content = String::new();
                    if file.read_to_string(&mut content).is_ok() && content.starts_with("---\n") {
                        if let Some((fm_str, body)) =
                            crate::magician_v2::artifacts::durable_store::split_frontmatter(
                                &content,
                            )
                        {
                            if let Ok(mut fm) = serde_yaml::from_str::<
                                crate::magician_v2::artifacts::durable_store::DurableFrontmatter,
                            >(&fm_str)
                            {
                                if let Some(ref tid) = task_id {
                                    fm.source_task_id = Some(tid.clone());
                                }
                                if let Some(ref exec_id) = execution_id {
                                    fm.source_execution_id = Some(exec_id.clone());
                                }
                                if let Some(ref aid) = agent_id_val {
                                    fm.source_agent_id = Some(aid.clone());
                                }
                                if let Ok(yaml) = serde_yaml::to_string(&fm) {
                                    let updated = format!("---\n{}---\n{}", yaml, body);
                                    // Atomic write: temp file + rename (crash-safe).
                                    if let Some(parent) = abs_target_clone.parent() {
                                        let tmp_path = parent
                                            .join(format!(".tmp-stamp-{}", uuid::Uuid::new_v4()));
                                        match std::fs::File::create(&tmp_path)
                                            .and_then(|mut f| {
                                                f.write_all(updated.as_bytes())?;
                                                f.sync_all()?;
                                                Ok(())
                                            })
                                            .and_then(|_| {
                                                std::fs::rename(&tmp_path, &abs_target_clone)
                                            }) {
                                            Ok(()) => {},
                                            Err(e) => {
                                                // Clean up temp file on failure
                                                let _ = std::fs::remove_file(&tmp_path);
                                                tracing::warn!(
                                                    "[DURABLE-HOOK] Failed to stamp \
                                                     source_task_id on {}: {}",
                                                    abs_target_clone.display(),
                                                    e
                                                );
                                            },
                                        }
                                    }
                                }
                            }
                        }
                    }
                    // Lock released when `file` is dropped
                }
            }
        });
        // Fire-and-forget but log panics — don't block the executor.
        // Clone store/namespace/name for the async block to call reindex_artifact after
        // stamp.
        let store_for_reindex = store.clone();
        let namespace_for_reindex = namespace.to_owned();
        let name_for_reindex = name.clone();
        tokio::spawn(async move {
            if let Err(e) = stamp_handle.await {
                tracing::warn!("[DURABLE-HOOK] source_task_id stamp task panicked: {}", e);
            } else {
                // Update tag index after frontmatter provenance stamp
                let _ = tokio::task::spawn_blocking(move || {
                    store_for_reindex.reindex_artifact(&namespace_for_reindex, &name_for_reindex);
                })
                .await;
            }
        });
    }

    // Track the durable artifact path for completion_artifact_names.
    if let Ok(mut outputs) = executors.run_outputs.lock() {
        outputs
            .durable_artifacts_written
            .push(format!("{}/{}", namespace, name));
    }

    tracing::debug!("[DURABLE-HOOK] Registered: {}/{}", namespace, name);
}

fn sanitize_path_component(raw: &str) -> String {
    let sanitized: String = raw
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || ch == '-' || ch == '_' {
                ch
            } else {
                '_'
            }
        })
        .collect();
    let trimmed = sanitized.trim_matches('_');
    if trimmed.is_empty() {
        "unknown".to_string()
    } else {
        trimmed.to_string()
    }
}

fn sanitize_bounded_path_component(raw: &str, max_chars: usize) -> String {
    let sanitized = sanitize_path_component(raw);
    if sanitized.chars().count() <= max_chars {
        return sanitized;
    }
    let bounded = sanitized.chars().take(max_chars).collect::<String>();
    let trimmed = bounded.trim_matches('_');
    if trimmed.is_empty() {
        "unknown".to_string()
    } else {
        trimmed.to_string()
    }
}

#[derive(Debug, Clone)]
struct PersistedExecutionArtifactTarget {
    scope: ScopeRef,
    task_id: String,
    execution_id: String,
}

fn persisted_execution_target_for_context(
    ctx: &AgenticContext,
) -> Option<PersistedExecutionArtifactTarget> {
    Some(PersistedExecutionArtifactTarget {
        scope: ScopeRef::system_internal_unauthenticated(
            &ctx.principal.clone()?,
            &ctx.workspace.clone()?,
        ),
        task_id: ctx.task_id.clone()?,
        execution_id: ctx.execution_id.clone()?,
    })
}

// `pub(super)` so `run_loop::phases` can call it. The phase extraction moves
// callers out of this file before it moves the helpers, so these widen first.
/// Index terminal decision artifacts after the runtime has materialized their
/// bytes. The file path alone is not sufficient provenance: Artifact V2 reads
/// the scoped execution index when deciding whether an answer can be projected
/// without another synthesis call. Keeping the record execution-scoped also
/// prevents a parent from treating an unrelated file as its child's accepted
/// deliverable.
pub(super) async fn persist_terminal_decision_artifact_records(
    ctx: &AgenticContext,
    executors: &ActionExecutors,
    artifacts: &[Artifact],
) {
    let Some(target) = persisted_execution_target_for_context(ctx) else {
        return;
    };
    let store = FilesystemExecutionArtifactIndexStore::new(executors.artifact_v2_workspace.clone());
    let produced_at = Utc::now().to_rfc3339();

    for (index, artifact) in artifacts.iter().enumerate() {
        let Some(path) = artifact
            .materialized_path
            .as_deref()
            .map(str::trim)
            .filter(|path| !path.is_empty())
        else {
            continue;
        };
        let artifact_type = artifact
            .artifact_type
            .as_deref()
            .map(str::trim)
            .filter(|kind| !kind.is_empty())
            .unwrap_or("terminal_decision");
        let mut digest = Sha256::new();
        digest.update(target.execution_id.as_bytes());
        digest.update(artifact_type.as_bytes());
        digest.update(artifact.name.as_bytes());
        digest.update(&artifact.data);
        let fingerprint = format!("{:x}", digest.finalize());
        let content_sha256 = format!("{:x}", Sha256::digest(&artifact.data));
        let artifact_id = format!("terminal_decision:{index}:{}", &fingerprint[..16]);
        let record = PersistedExecutionArtifactRecord {
            artifact_id: artifact_id.clone(),
            artifact_type: artifact_type.to_string(),
            content_type: artifact.content_type.clone(),
            payload: json!({
                "artifact_kind": artifact_type,
                "artifact_id": artifact_id,
                "display_name": artifact.name,
                "content_type": artifact.content_type,
                "execution_id": target.execution_id,
                "execution_absolute_path": path,
                "size_bytes": artifact.data.len(),
                "content_sha256": content_sha256,
            }),
            produced_at: produced_at.clone(),
            source_execution_id: Some(target.execution_id.clone()),
            source_artifact_id: None,
        };
        if let Err(error) = store
            .upsert_artifact(&target.scope, &target.task_id, &target.execution_id, record)
            .await
        {
            warn!(
                execution_id = %target.execution_id,
                artifact = %artifact.name,
                %error,
                "failed to index materialized terminal decision artifact"
            );
        }
    }
}

fn persisted_execution_target_from_prepared(
    prepared: &PreparedDownloadArtifact,
) -> Option<PersistedExecutionArtifactTarget> {
    Some(PersistedExecutionArtifactTarget {
        scope: ScopeRef::system_internal_unauthenticated(
            &prepared.principal.clone()?,
            &prepared.workspace.clone()?,
        ),
        task_id: prepared.task_id.clone()?,
        execution_id: prepared.execution_id.clone()?,
    })
}

fn current_scope_ref(executors: &ActionExecutors) -> Option<ScopeRef> {
    // MERGE RESOLUTION 2026-08-28, taking one half from each side.
    //
    // `loop-boundary` replaced the two mutex-guarded `current_principal` /
    // `current_workspace` slots with the copy-on-write `run_identity` cell, and
    // `meetable_bot` replaced the `ScopeRef { .. }` literal with the
    // `system_internal_unauthenticated` constructor. The two changes are
    // independent and both survive: the SOURCE is `run_identity`, the
    // CONSTRUCTION is the constructor.
    //
    // Neither side's version would have been right alone. Keeping HEAD's would
    // have gone on building a `ScopeRef` by literal, which is what the auth work
    // moved away from; keeping meetable_bot's would have read the mutex slots
    // this branch deleted.
    let identity = executors.run_identity.get();
    Some(ScopeRef::system_internal_unauthenticated(
        &identity.principal.clone()?,
        &identity.workspace.clone()?,
    ))
}

fn refresh_scoped_durable_store(executors: &ActionExecutors) {
    let scoped_store = current_scope_ref(executors).and_then(|scope| {
        crate::magician_v2::artifacts::durable_store::open_local_durable_artifacts(
            &executors.artifact_v2_workspace,
            &scope.principal(),
            &scope.workspace(),
        )
        .map(std::sync::Arc::new)
        .map_err(|error| {
            tracing::warn!(
                principal = %scope.principal(),
                workspace = %scope.workspace(),
                error = %error,
                "[DURABLE-ARTIFACTS] Failed to resolve scoped durable artifact store"
            );
        })
        .ok()
    });

    if let Ok(mut guard) = executors.durable_store.lock() {
        *guard = scoped_store;
    }
}

async fn runtime_execution_download_root(
    executors: &ActionExecutors,
    principal: &str,
    workspace: &str,
    task_id: Option<&str>,
    execution_id: &str,
) -> Result<std::path::PathBuf> {
    executors
        .artifact_v2_workspace
        .ensure_runtime_execution_workspace(principal, workspace, task_id, execution_id)
        .await
        .map_err(|err| anyhow!("Failed to prepare V3 runtime execution workspace: {}", err))?;

    let root = executors
        .artifact_v2_workspace
        .runtime_execution_downloads_dir(principal, workspace, task_id, execution_id);
    tokio::fs::create_dir_all(&root).await?;
    Ok(root)
}

async fn runtime_execution_download_root_from_prepared(
    prepared: &PreparedDownloadArtifact,
    executors: &ActionExecutors,
) -> Result<std::path::PathBuf> {
    let principal = prepared
        .principal
        .as_deref()
        .ok_or_else(|| anyhow!("Prepared download missing principal"))?;
    let workspace = prepared
        .workspace
        .as_deref()
        .ok_or_else(|| anyhow!("Prepared download missing workspace"))?;
    let task_id = prepared
        .task_id
        .as_deref()
        .ok_or_else(|| anyhow!("Prepared download missing task_id"))?;
    let execution_id = prepared
        .execution_id
        .as_deref()
        .ok_or_else(|| anyhow!("Prepared download missing execution_id"))?;
    runtime_execution_download_root(executors, principal, workspace, Some(task_id), execution_id)
        .await
}

fn purpose_for_download(ctx: &AgenticContext) -> String {
    match ctx.step_id.as_deref() {
        Some(step_id) => format!("goal={} step={}", ctx.goal, step_id),
        None => ctx.goal.clone(),
    }
}

async fn prepare_download_artifact_action(
    action: &ExecutableAction,
    executors: &ActionExecutors,
    ctx: &AgenticContext,
    iteration: usize,
) -> Result<(ExecutableAction, Option<PreparedDownloadArtifact>)> {
    let _ = (executors, ctx, iteration);
    Ok((
        action
            .try_clone_for_retention()
            .map_err(|error| anyhow!("action retention admission failed: {error}"))?,
        None,
    ))
}

fn resolve_local_path(path: &str) -> Result<std::path::PathBuf> {
    let candidate = std::path::PathBuf::from(path);
    if candidate.is_absolute() {
        Ok(candidate)
    } else {
        let cwd = std::env::current_dir()
            .map_err(|e| anyhow!("Failed to resolve current directory for '{}': {}", path, e))?;
        Ok(cwd.join(candidate))
    }
}

fn is_allowed_tool_output_capture_path(path: &std::path::Path) -> bool {
    let Ok(canonical_path) = std::fs::canonicalize(path) else {
        return false;
    };
    let Ok(cwd) = std::env::current_dir() else {
        return false;
    };
    let cwd = cwd.canonicalize().unwrap_or(cwd);
    let temp_dir = std::env::temp_dir();
    let temp_dir = temp_dir.canonicalize().unwrap_or(temp_dir);

    if canonical_path.starts_with(&cwd) || canonical_path.starts_with(&temp_dir) {
        return true;
    }

    // Also accept the conventional temp roots `/tmp` and `/private/tmp` (which
    // alias on macOS). Some tools — notably media generators — default their
    // output here rather than into `std::env::temp_dir()`; without this their
    // produced files are silently dropped from capture and never become task
    // outputs the user can see.
    ["/tmp", "/private/tmp"]
        .iter()
        .filter_map(|root| std::fs::canonicalize(root).ok())
        .any(|root| canonical_path.starts_with(&root))
}

fn registered_artifact_paths(
    records: &[PersistedExecutionArtifactRecord],
) -> std::collections::HashSet<String> {
    let mut registered = HashSet::new();
    for record in records {
        for key in [
            "absolute_path",
            "export_path",
            "execution_absolute_path",
            "task_absolute_path",
        ] {
            if let Some(path) = record.payload.get(key).and_then(Value::as_str) {
                if let Ok(canonical) = std::fs::canonicalize(path) {
                    registered.insert(canonical.to_string_lossy().into_owned());
                }
            }
        }
    }
    registered
}

fn preferred_download_file_name(raw_name: Option<&str>, fallback_path: &std::path::Path) -> String {
    raw_name
        .map(std::path::Path::new)
        .and_then(|path| path.file_name())
        .map(|value| value.to_string_lossy().into_owned())
        .or_else(|| {
            fallback_path
                .file_name()
                .map(|value| value.to_string_lossy().into_owned())
        })
        .filter(|name| !name.trim().is_empty())
        .unwrap_or_else(|| "download.bin".to_string())
}

async fn ensure_download_in_managed_dir(
    source_path: &std::path::Path,
    managed_dir: &std::path::Path,
    preferred_name: Option<&str>,
    workspace: &crate::magician_v2::artifact_v2::workspace::ArtifactV2Workspace,
) -> Result<std::path::PathBuf> {
    tokio::fs::create_dir_all(managed_dir).await?;

    let file_name = preferred_download_file_name(preferred_name, source_path);
    let canonical_path = managed_dir.join(file_name);

    if source_path == canonical_path {
        route_managed_download(workspace, &canonical_path).await?;
        return Ok(canonical_path);
    }

    if let Some(parent) = canonical_path
        .parent()
        .filter(|p| !p.as_os_str().is_empty())
    {
        tokio::fs::create_dir_all(parent).await?;
    }

    if tokio::fs::try_exists(&canonical_path)
        .await
        .unwrap_or(false)
    {
        route_managed_download(workspace, &canonical_path).await?;
        return Ok(canonical_path);
    }

    if let Some((store, rel)) = crate::magician_v2::object_owners::store_for_existing_path(
        workspace,
        &canonical_path,
        crate::magician_v2::object_owners::ObjectOwner::ExecutionDownloads,
    ) {
        let bytes = tokio::fs::read(source_path).await?;
        store.put(&rel, &bytes).await?;
        return Ok(canonical_path);
    }

    tokio::fs::copy(source_path, &canonical_path).await?;
    Ok(canonical_path)
}

async fn route_managed_download(
    workspace: &crate::magician_v2::artifact_v2::workspace::ArtifactV2Workspace,
    path: &std::path::Path,
) -> Result<()> {
    let Some((store, rel)) = crate::magician_v2::object_owners::store_for_existing_path(
        workspace,
        path,
        crate::magician_v2::object_owners::ObjectOwner::ExecutionDownloads,
    ) else {
        return Ok(());
    };
    let bytes = tokio::fs::read(path).await?;
    store.put(&rel, &bytes).await?;
    Ok(())
}

async fn export_download_copy(
    source_path: &std::path::Path,
    target_path: &str,
) -> Result<std::path::PathBuf> {
    let target = resolve_local_path(target_path)?;
    if let Some(parent) = target.parent().filter(|p| !p.as_os_str().is_empty()) {
        tokio::fs::create_dir_all(parent).await?;
    }
    if target.exists() {
        return Err(anyhow!(
            "Download export target already exists: {}",
            target.display()
        ));
    }
    tokio::fs::copy(source_path, &target).await?;
    Ok(target)
}

async fn sha256_for_file(path: &std::path::Path) -> Result<String> {
    let mut file = tokio::fs::File::open(path).await?;
    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 8192];

    loop {
        let read = file.read(&mut buffer).await?;
        if read == 0 {
            break;
        }
        hasher.update(&buffer[..read]);
    }

    Ok(format!("{:x}", hasher.finalize()))
}

async fn persist_download_artifact_content(
    content: &DownloadedFileArtifactContent,
    target: Option<&PersistedExecutionArtifactTarget>,
    executors: &ActionExecutors,
) -> Result<Artifact> {
    let artifact = Artifact::json(content.artifact_id.clone(), content)?;

    if let Some(target) = target {
        let store =
            FilesystemExecutionArtifactIndexStore::new(executors.artifact_v2_workspace.clone());
        if let Err(err) = store
            .upsert_artifact(
                &target.scope,
                &target.task_id,
                &target.execution_id,
                PersistedExecutionArtifactRecord {
                    artifact_id: content.artifact_id.clone(),
                    artifact_type: DOWNLOADED_FILE_ARTIFACT_TYPE.to_string(),
                    content_type: "application/json".to_string(),
                    payload: serde_json::to_value(content)?,
                    produced_at: content.downloaded_at.to_rfc3339(),
                    source_execution_id: None,
                    source_artifact_id: None,
                },
            )
            .await
        {
            warn!(
                "[DOWNLOAD-ARTIFACT] Failed to persist V3 execution artifact '{}' for execution \
                 '{}': {}",
                content.artifact_id, target.execution_id, err
            );
        }
    }

    Ok(artifact)
}

async fn complete_download_artifact(
    prepared: PreparedDownloadArtifact,
    action_result: &ActionResult,
    artifact_root: &std::path::Path,
    workspace: &crate::magician_v2::artifact_v2::workspace::ArtifactV2Workspace,
) -> Result<Option<DownloadedFileArtifactContent>> {
    let ActionResult::Browser { data, .. } = action_result else {
        return Ok(None);
    };

    let Some(download) = data.get("download") else {
        return Ok(None);
    };

    let absolute_path = download
        .get("path")
        .and_then(Value::as_str)
        .ok_or_else(|| anyhow!("Download result missing path"))?;
    let absolute_path = std::path::PathBuf::from(absolute_path);
    let file_name = download
        .get("fileName")
        .and_then(Value::as_str)
        .map(ToString::to_string)
        .or_else(|| prepared.expected_filename.clone())
        .unwrap_or_else(|| preferred_download_file_name(None, &absolute_path));
    let managed_absolute_path = ensure_download_in_managed_dir(
        &absolute_path,
        std::path::Path::new(&prepared.managed_download_dir),
        Some(&file_name),
        workspace,
    )
    .await?;
    let export_path = match prepared
        .requested_target_path
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        Some(target_path) => Some(
            export_download_copy(&managed_absolute_path, target_path)
                .await?
                .to_string_lossy()
                .into_owned(),
        ),
        None => None,
    };
    let metadata = tokio::fs::metadata(&managed_absolute_path).await?;
    let relative_path = managed_absolute_path
        .strip_prefix(artifact_root)
        .ok()
        .map(|path| path.to_string_lossy().into_owned());
    let sha256 = sha256_for_file(&managed_absolute_path).await?;

    Ok(Some(DownloadedFileArtifactContent {
        artifact_kind: DOWNLOADED_FILE_ARTIFACT_TYPE.to_string(),
        artifact_id: prepared.artifact_id,
        chain_id: prepared.chain_id,
        goal: prepared.goal.clone(),
        purpose: purpose_for_download(&AgenticContext {
            goal: prepared.goal,
            step_id: prepared.step_id.clone(),
            ..Default::default()
        }),
        selector: prepared.selector,
        file_name: preferred_download_file_name(Some(&file_name), &managed_absolute_path),
        expected_filename: prepared.expected_filename,
        absolute_path: managed_absolute_path.to_string_lossy().into_owned(),
        relative_path,
        export_path,
        requested_download_dir: prepared.requested_download_dir,
        requested_target_path: prepared.requested_target_path,
        mime_type: download
            .get("mime")
            .and_then(Value::as_str)
            .map(ToString::to_string),
        size_bytes: metadata.len(),
        sha256,
        request_url: download
            .get("url")
            .and_then(Value::as_str)
            .map(ToString::to_string),
        final_url: download
            .get("finalUrl")
            .and_then(Value::as_str)
            .map(ToString::to_string),
        execution_id: prepared.execution_id,
        plan_id: prepared.plan_id,
        step_id: prepared.step_id,
        cycle_id: prepared.cycle_id,
        agent_id: prepared.agent_id,
        iteration: prepared.iteration,
        downloaded_at: chrono::Utc::now(),
        source_artifact_id: None,
        source_chain_id: None,
    }))
}

async fn materialize_download_artifact(
    prepared: PreparedDownloadArtifact,
    action_result: &ActionResult,
    executors: &ActionExecutors,
) -> Result<Option<Artifact>> {
    let target = persisted_execution_target_from_prepared(&prepared);
    let artifact_root = runtime_execution_download_root_from_prepared(&prepared, executors).await?;
    let Some(content) = complete_download_artifact(
        prepared,
        action_result,
        artifact_root.as_path(),
        &executors.artifact_v2_workspace,
    )
    .await?
    else {
        return Ok(None);
    };

    Ok(Some(
        persist_download_artifact_content(&content, target.as_ref(), executors).await?,
    ))
}

async fn load_persisted_prompt_artifacts(
    ctx: &AgenticContext,
    executors: &ActionExecutors,
) -> Vec<Artifact> {
    let Some(target) = persisted_execution_target_for_context(ctx) else {
        return Vec::new();
    };

    let store = FilesystemExecutionArtifactIndexStore::new(executors.artifact_v2_workspace.clone());
    let (execution_ids, execution_root_ids, tool_output_seed_root_execution_ids) =
        if let Some(service) = executors.artifact_v2_service.as_ref() {
            match service
                .get_execution_tree(&target.scope, &target.task_id)
                .await
            {
                Ok(tree) if !tree.nodes.is_empty() => {
                    let mut execution_root_ids = HashMap::new();
                    let execution_ids = tree
                        .nodes
                        .iter()
                        .map(|node| {
                            let root_execution_id = node
                                .root_execution_id
                                .clone()
                                .unwrap_or_else(|| node.execution_id.clone());
                            execution_root_ids.insert(node.execution_id.clone(), root_execution_id);
                            node.execution_id.clone()
                        })
                        .collect::<Vec<_>>();
                    let tool_output_seed_root_execution_ids = tool_output_seed_root_execution_ids(
                        &tree,
                        &target.execution_id,
                        &execution_root_ids,
                    );
                    (
                        execution_ids,
                        execution_root_ids,
                        tool_output_seed_root_execution_ids,
                    )
                },
                _ => (
                    vec![target.execution_id.clone()],
                    HashMap::new(),
                    HashSet::from([target.execution_id.clone()]),
                ),
            }
        } else {
            (
                vec![target.execution_id.clone()],
                HashMap::new(),
                HashSet::from([target.execution_id.clone()]),
            )
        };

    let mut combined = Vec::<(String, PersistedExecutionArtifactRecord)>::new();
    for execution_id in execution_ids {
        let Ok(records) = store
            .list_artifacts(&target.scope, &target.task_id, &execution_id)
            .await
        else {
            continue;
        };
        let root_execution_id = execution_root_ids
            .get(&execution_id)
            .map(String::as_str)
            .unwrap_or(execution_id.as_str());
        for record in records {
            let should_include = match record.artifact_type.as_str() {
                DOWNLOADED_FILE_ARTIFACT_TYPE => true,
                TOOL_OUTPUT_FILE_ARTIFACT_TYPE => {
                    tool_output_seed_root_execution_ids.contains(root_execution_id)
                },
                _ => false,
            };
            if should_include {
                combined.push((artifact_prompt_display_name(&record), record));
            }
        }
    }

    let mut seen = HashSet::new();
    let mut artifacts = Vec::new();
    for (display_name, record) in combined.into_iter().rev() {
        if !seen.insert(display_name.clone()) {
            continue;
        }
        if !persisted_prompt_artifact_exists(&record) {
            continue;
        }
        if let Ok(artifact) = Artifact::json(display_name, &record.payload) {
            artifacts.push(artifact);
        }
        if artifacts.len() >= 10 {
            break;
        }
    }
    artifacts.reverse();
    artifacts
}

fn tool_output_seed_root_execution_ids(
    tree: &crate::magician_v2::artifact_v2::models::ExecutionTreeRecord,
    target_execution_id: &str,
    execution_root_ids: &HashMap<String, String>,
) -> HashSet<String> {
    let target_root_execution_id = execution_root_ids
        .get(target_execution_id)
        .cloned()
        .unwrap_or_else(|| target_execution_id.to_string());
    let mut ordered_root_execution_ids = Vec::new();
    let mut seen_root_execution_ids = HashSet::new();
    for node in &tree.nodes {
        let root_execution_id = node
            .root_execution_id
            .clone()
            .unwrap_or_else(|| node.execution_id.clone());
        if seen_root_execution_ids.insert(root_execution_id.clone()) {
            ordered_root_execution_ids.push(root_execution_id);
        }
    }

    if ordered_root_execution_ids.is_empty() {
        ordered_root_execution_ids.push(target_root_execution_id.clone());
    } else if !seen_root_execution_ids.contains(&target_root_execution_id) {
        ordered_root_execution_ids.push(target_root_execution_id.clone());
    }

    let mut seed_root_execution_ids = HashSet::new();
    for root_execution_id in ordered_root_execution_ids {
        seed_root_execution_ids.insert(root_execution_id.clone());
        if root_execution_id == target_root_execution_id {
            break;
        }
    }

    seed_root_execution_ids
}

fn artifact_prompt_display_name(record: &PersistedExecutionArtifactRecord) -> String {
    record
        .payload
        .get("display_name")
        .and_then(Value::as_str)
        .or_else(|| record.payload.get("file_name").and_then(Value::as_str))
        .or_else(|| {
            record
                .payload
                .get("task_relative_path")
                .and_then(Value::as_str)
                .and_then(|path| std::path::Path::new(path).file_name())
                .and_then(|value| value.to_str())
        })
        .or_else(|| {
            record
                .payload
                .get("absolute_path")
                .and_then(Value::as_str)
                .and_then(|path| std::path::Path::new(path).file_name())
                .and_then(|value| value.to_str())
        })
        .map(ToOwned::to_owned)
        .unwrap_or_else(|| record.artifact_id.clone())
}

fn persisted_prompt_artifact_exists(record: &PersistedExecutionArtifactRecord) -> bool {
    let mut saw_persisted_path = false;
    for key in [
        "task_absolute_path",
        "absolute_path",
        "execution_absolute_path",
        "export_path",
    ] {
        if let Some(path) = record.payload.get(key).and_then(Value::as_str) {
            saw_persisted_path = true;
            if std::path::Path::new(path).exists() {
                return true;
            }
        }
    }
    !saw_persisted_path
}

// ============================================================================
// Full Pause Data (for storing everything needed to resume)
// ============================================================================

use dashmap::DashMap;

#[derive(Debug, Clone, serde::Serialize, serde::Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum ExecutionPauseKind {
    UserInput,
    /// User-input pause emitted by a `primitive`-type pack (browser, gmail,
    /// etc.) rather than the outer agentic loop. Flat-loop Phase 7 retired
    /// the nested runner; resume now continues through the standard outer
    /// path (the former pause-store fast-path is gone).
    PrimitiveUserInput,
    Confirmation,
    MaxIterations,
    /// Cumulative token/cost budget exhausted mid-run. Mirrors `MaxIterations`:
    /// a recoverable pause offering "Continue execution?" (resume with a fresh
    /// budget) rather than a terminal `ExecutionFailed`.
    // The orchestrator persists this as `ExecutionPausedForInput` with a
    // `Budget` pause kind; the ordinary confirmation resume path restores the
    // same checkpoint with a fresh budget.
    Budget,
    Escalation,
    Manual,
    /// Durable source continuation retained while an exact manual resume is
    /// executing. This is internal lifecycle state: public pause APIs must not
    /// offer or consume it, while startup recovery may re-enter it only with
    /// the matching sealed control generation.
    ManualResumeInflight,
    /// Internal continuation checkpoint while a parent waits for delegated
    /// child executions. It is not a user-facing HITL pause.
    Delegation,
    /// Internal exact-segment checkpoint while placement is owned by another
    /// live process. The due time and exact source live inside the sealed pause
    /// body and are admission authority, not reconnect/UI state.
    PlacementRetry,
}

/// Complete data needed to resume agentic execution after user input.
///
/// This includes the pause state (context, environment, iteration) plus
/// the action executors needed to continue execution.
#[derive(Clone)]
pub struct FullPauseData {
    /// The preserved execution state
    pub pause_state: AgenticPauseState,
    /// The type of input requested from the user
    pub input_type: UserInputType,
    /// The action executors needed for resume
    pub executors: ActionExecutors,
    /// Optional question/prompt shown to user
    pub question: Option<String>,
    /// Optional hint for the next action
    pub hint: Option<String>,
    /// Serialized action payload when paused on a confirmation gate.
    ///
    /// Used to ensure a positive confirmation bypasses re-gating of the same
    /// action exactly once after resume.
    pub confirmation_action_json: Option<String>,
    /// Optional secret-store approval challenge that must be granted on
    /// confirm.
    pub secret_approval_challenge_id: Option<String>,
    /// Secret approval context used to reconstruct approval after restart.
    pub secret_approval_request: Option<SecretApprovalRequest>,

    // === Input Tracking (Elicitation Unification) ===
    /// Pending inputs that need to be resolved (carries over across pauses)
    pub pending_inputs: Vec<PendingInput>,
    /// Resolved input values provided by the user (persists across
    /// pause/resume)
    pub resolved_inputs: HashMap<String, Value>,
    /// The parameter ID currently being asked (to associate response with
    /// input)
    pub asking_for_parameter: Option<String>,

    // === Retry Tracking ===
    /// Number of times we've re-asked for this specific input
    pub retry_count: usize,
    /// The previous answer (for showing in UI during re-ask)
    pub previous_answer: Option<String>,
    /// Reason for re-asking (e.g., "Invalid email format")
    pub retry_reason: Option<String>,

    // === Escalation Tracking ===
    /// Set when this pause was triggered by failure escalation (on_failure:
    /// ask_user). Values: "cannot_proceed", "loop_detected", or None for
    /// normal user input pauses.
    pub escalation_trigger: Option<String>,
    /// Human-readable summary for confirmation pauses.
    pub confirmation_action_summary: Option<String>,
    /// Why a confirmation pause requires approval.
    pub confirmation_reason: Option<String>,
    /// Action type emitted on the realtime confirmation event.
    pub confirmation_action_type: Option<String>,
    /// Structured pause classification for resume and reconnect behavior.
    pub pause_kind: Option<ExecutionPauseKind>,
    /// Harness continuation for a plane Task 8 approval pause: the gated
    /// action resume must execute itself (not replay), plus the native
    /// session and turn-budget remainder the resumed harness turn inherits.
    pub harness_pause:
        Option<crate::magician_v2::execution::plane::turn_engine::HarnessPauseContinuation>,
}

impl FullPauseData {
    /// Create new full pause data.
    pub fn new(
        pause_state: AgenticPauseState,
        input_type: UserInputType,
        executors: ActionExecutors,
        question: Option<String>,
        hint: Option<String>,
    ) -> Self {
        Self {
            pause_state,
            input_type,
            executors,
            question,
            hint,
            confirmation_action_json: None,
            secret_approval_challenge_id: None,
            secret_approval_request: None,
            pending_inputs: Vec::new(),
            resolved_inputs: HashMap::new(),
            asking_for_parameter: None,
            retry_count: 0,
            previous_answer: None,
            retry_reason: None,
            escalation_trigger: None,
            confirmation_action_summary: None,
            confirmation_reason: None,
            confirmation_action_type: None,
            pause_kind: None,
            harness_pause: None,
        }
    }

    /// Create full pause data with input tracking context
    pub fn with_input_tracking(
        pause_state: AgenticPauseState,
        input_type: UserInputType,
        executors: ActionExecutors,
        question: Option<String>,
        hint: Option<String>,
        pending_inputs: Vec<PendingInput>,
        resolved_inputs: HashMap<String, Value>,
        asking_for_parameter: Option<String>,
    ) -> Self {
        Self {
            pause_state,
            input_type,
            executors,
            question,
            hint,
            confirmation_action_json: None,
            secret_approval_challenge_id: None,
            secret_approval_request: None,
            pending_inputs,
            resolved_inputs,
            asking_for_parameter,
            retry_count: 0,
            previous_answer: None,
            retry_reason: None,
            escalation_trigger: None,
            confirmation_action_summary: None,
            confirmation_reason: None,
            confirmation_action_type: None,
            pause_kind: None,
            harness_pause: None,
        }
    }

    /// Create full pause data for a re-ask scenario (validation failed)
    pub fn for_reask(
        pause_state: AgenticPauseState,
        input_type: UserInputType,
        executors: ActionExecutors,
        question: Option<String>,
        hint: Option<String>,
        pending_inputs: Vec<PendingInput>,
        resolved_inputs: HashMap<String, Value>,
        asking_for_parameter: Option<String>,
        retry_count: usize,
        previous_answer: Option<String>,
        retry_reason: Option<String>,
    ) -> Self {
        let previous_answer = sanitize_retry_previous_answer(
            &input_type,
            asking_for_parameter.as_deref(),
            &pending_inputs,
            question.as_deref(),
            hint.as_deref(),
            pause_state.pending_sensitive.as_ref(),
            previous_answer.as_deref(),
        );
        Self {
            pause_state,
            input_type,
            executors,
            question,
            hint,
            confirmation_action_json: None,
            secret_approval_challenge_id: None,
            secret_approval_request: None,
            pending_inputs,
            resolved_inputs,
            asking_for_parameter,
            retry_count,
            previous_answer,
            retry_reason,
            escalation_trigger: None,
            confirmation_action_summary: None,
            confirmation_reason: None,
            confirmation_action_type: None,
            pause_kind: None,
            harness_pause: None,
        }
    }

    /// Check if this is a retry scenario
    pub fn is_retry(&self) -> bool {
        self.retry_count > 0
    }

    /// Attach confirmation action JSON payload for one-time approved resume
    /// bypass.
    pub fn with_confirmation_action_json(mut self, action_json: Option<String>) -> Self {
        self.confirmation_action_json = action_json;
        self
    }

    /// Attach the harness continuation of a plane Task 8 approval pause.
    pub fn with_harness_pause(
        mut self,
        harness_pause: Option<
            crate::magician_v2::execution::plane::turn_engine::HarnessPauseContinuation,
        >,
    ) -> Self {
        self.harness_pause = harness_pause;
        self
    }

    /// Set the escalation trigger (e.g., "cannot_proceed", "loop_detected").
    pub fn with_escalation_trigger(mut self, trigger: Option<String>) -> Self {
        self.escalation_trigger = trigger;
        self
    }

    /// Attach structured confirmation event details for reconnect/replay
    /// fidelity.
    pub fn with_confirmation_event_details(
        mut self,
        action_summary: impl Into<String>,
        reason: impl Into<String>,
        action_type: impl Into<String>,
    ) -> Self {
        self.confirmation_action_summary = Some(action_summary.into());
        self.confirmation_reason = Some(reason.into());
        self.confirmation_action_type = Some(action_type.into());
        self
    }

    pub fn with_pause_kind(mut self, pause_kind: ExecutionPauseKind) -> Self {
        self.pause_kind = Some(pause_kind);
        self
    }

    /// Attach a secret-store approval challenge for resume-time granting.
    pub fn with_secret_approval_challenge_id(mut self, challenge_id: Option<String>) -> Self {
        self.secret_approval_challenge_id = challenge_id;
        self
    }

    /// Attach secret approval context for restart-safe resume.
    pub fn with_secret_approval_request(mut self, request: Option<SecretApprovalRequest>) -> Self {
        self.secret_approval_request = request;
        self
    }
}

/// Summary info about a pending pause (for reconnect/re-emit).
///
/// This is a lightweight version of FullPauseData that contains just
/// the information needed to re-emit WaitingForUser events.
#[derive(Clone, serde::Serialize, serde::Deserialize, PartialEq, Eq)]
pub struct PendingPauseInfo {
    /// Opaque revision binding an MCP answer to this exact question/capture.
    #[serde(default)]
    pub input_revision: String,
    /// Storage key for this pause state
    pub key: String,
    /// The canonical `hitl.requested` correlation id of this pause
    /// (`AgenticPauseState::hitl_correlation_id`): the key plus the ask's
    /// identity, so a resolution names this ask and not an earlier one the
    /// same key held. Equal to `key` for records written before asks had
    /// identities.
    #[serde(default)]
    pub hitl_correlation_id: String,
    /// Execution ID for the paused execution
    pub execution_id: String,
    /// Exact loop-state segment that produced an internal delegation
    /// checkpoint. Internal lifecycle consumers use it to retire that segment
    /// before dispatching the checkpoint; user-facing pause projection ignores
    /// it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(crate) stateless_parked_segment: Option<String>,
    /// Loop-state segment the same checkpoint will execute as after handoff.
    /// Kept beside the source address so the lifecycle bridge can require the
    /// parked state's `ResumeAddress` to name this exact checkpoint.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(crate) stateless_resume_segment: Option<String>,
    /// Immutable timer generation paired with `stateless_parked_segment`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(crate) stateless_retry_due_at: Option<chrono::DateTime<Utc>>,
    /// Principal scope for reconnect-time event re-emission.
    pub principal: Option<String>,
    /// Workspace scope for reconnect-time event re-emission.
    pub workspace: Option<String>,
    /// Legacy carrier for old thread-shaped reconnect payloads.
    /// Live pause re-emit uses `execution_id`; this remains only to absorb
    /// older callers.
    pub legacy_execution_id: String,
    /// Task ID (if available). Carried from the pause_state so orphan
    /// reconciliation can emit a self-describing `HitlResolved` (task_id is
    /// the real events.jsonl directory segment for durable persist).
    pub task_id: Option<String>,
    /// Plan ID (if available)
    pub plan_id: Option<String>,
    /// Step ID (if available)
    pub step_id: Option<String>,
    /// Question/prompt for the user
    pub question: Option<String>,
    /// Type of input expected
    pub input_type: UserInputType,
    /// The value-free sensitivity spec the pause decided (P3): the listing
    /// carries it so every consumer — the plane's `wait`, a client reading
    /// pending pauses — masks or refuses by the same verdict the
    /// announcement published. `None` is an ordinary ask.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pending_sensitive: Option<crate::magician_v2::user_requests::SensitiveInputSpec>,
    /// Optional hint
    pub hint: Option<String>,
    /// Iteration when paused
    pub iteration: usize,
    /// Options for choice/multi_choice types (JSON array)
    pub options: Option<String>,
    /// Whether this is a retry (re-ask) scenario
    pub is_retry: bool,
    /// Number of retry attempts
    pub retry_count: usize,
    /// Previous answer (for showing in UI during re-ask)
    pub previous_answer: Option<String>,
    /// Reason for re-asking
    pub retry_reason: Option<String>,
    // --- Agent routing fields (TRUE_AGENTS Phase 0) ---
    /// Agent ID (if this pause belongs to an agent cycle)
    pub agent_id: Option<String>,
    /// Goal ID (if this pause belongs to an agent cycle)
    pub goal_id: Option<String>,
    /// Cycle ID (if this pause belongs to an agent cycle)
    pub cycle_id: Option<String>,
    /// Set when this pause was triggered by failure escalation (on_failure:
    /// ask_user). Values: "cannot_proceed", "loop_detected", or None for
    /// normal user input pauses.
    pub escalation_trigger: Option<String>,
    /// Human-readable summary for confirmation pauses.
    pub confirmation_action_summary: Option<String>,
    /// Why a confirmation pause requires approval.
    pub confirmation_reason: Option<String>,
    /// Action type emitted on the realtime confirmation event.
    pub confirmation_action_type: Option<String>,
    /// Structured pause classification for replay/resume routing.
    pub pause_kind: Option<ExecutionPauseKind>,
}

impl std::fmt::Debug for PendingPauseInfo {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("PendingPauseInfo")
            .field("key", &self.key)
            .field("execution_id", &self.execution_id)
            .field("task_id", &self.task_id)
            .field("input_type", &format_input_type_for_event(&self.input_type))
            .field("iteration", &self.iteration)
            .field("is_retry", &self.is_retry)
            .field("pause_kind", &self.pause_kind)
            .finish_non_exhaustive()
    }
}

impl PendingPauseInfo {
    /// Construct user-facing pause metadata for downstream crate fixtures
    /// without exposing internal stateless continuation addresses.
    #[cfg(any(test, feature = "test-fixtures"))]
    pub fn for_test(key: &str, execution_id: &str, input_type: UserInputType) -> Self {
        let options = input_type.options_json();
        Self {
            input_revision: String::new(),
            key: key.to_owned(),
            // A real pause's correlation is its key PLUS its ask's identity, so
            // a fixture that made the two equal would let a comparison against
            // the bare key pass — which is exactly the defect that expired every
            // critical agentic alert.
            hitl_correlation_id: format!("{key}~0123456789ab"),
            execution_id: execution_id.to_owned(),
            stateless_parked_segment: None,
            stateless_resume_segment: None,
            stateless_retry_due_at: None,
            principal: None,
            workspace: None,
            legacy_execution_id: execution_id.to_owned(),
            task_id: None,
            plan_id: None,
            step_id: None,
            question: None,
            input_type,
            pending_sensitive: None,
            hint: None,
            iteration: 0,
            options,
            is_retry: false,
            retry_count: 0,
            previous_answer: None,
            retry_reason: None,
            agent_id: None,
            goal_id: None,
            cycle_id: None,
            escalation_trigger: None,
            confirmation_action_summary: None,
            confirmation_reason: None,
            confirmation_action_type: None,
            pause_kind: None,
        }
    }

    /// Remove lifecycle-only loop-state addresses before a pending pause leaves
    /// the runtime boundary. The persisted/internal projection keeps them so a
    /// restart can finish a terminal-first delegation handoff.
    fn into_user_facing(mut self) -> Self {
        self.stateless_parked_segment = None;
        self.stateless_resume_segment = None;
        self.stateless_retry_due_at = None;
        self
    }
}

/// Thread-safe store for full pause data (pause state + executors).
///
/// This allows the resume API to look up everything needed to continue
/// execution after the user provides input. Supports optional file-based
/// persistence for crash recovery.
#[derive(Default)]
/// Minimal metadata to emit a canonical `HitlResolved` for a pending pause when
/// its execution is torn down (cancelled) with the HITL still pending.
/// `correlation_id == AgenticPauseState::hitl_correlation_id()` == the
/// originating `HitlRequested` correlation_id, so emitting it decrements the
/// `pendingHitlStore` badge instead of stranding a phantom pending request.
#[derive(Debug, Clone)]
pub struct PendingHitlResolution {
    pub correlation_id: String,
    pub source: String,
    pub task_id: Option<String>,
    pub execution_id: Option<String>,
    pub agent_id: Option<String>,
    pub principal: Option<String>,
    pub workspace: Option<String>,
}

/// Bounded metadata result used by public control endpoints before they
/// interpret a missing in-process pause as true absence. `staged_count` names
/// durable generations that are intentionally hidden until terminal receipt
/// settlement completes; `public_count` names active generations discovered
/// from a rolling peer and refreshed into the local bounded index.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct StatelessTerminalPauseAdmission {
    pub staged_count: usize,
    pub public_count: usize,
}

/// Bounded durable pause metadata owned by one authenticated agent scope.
/// Execution ids are deduplicated and sorted so public lifecycle callers can
/// acquire composite execution fences deterministically after taking the
/// agent-wide exclusion.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct StatelessTerminalAgentPauseAdmission {
    pub admission: StatelessTerminalPauseAdmission,
    pub staged_execution_ids: Vec<String>,
    pub public_execution_ids: Vec<String>,
}

/// Owned process + cross-process exclusion for agent-wide lifecycle changes.
/// The guard is intentionally opaque: authority lasts until drop and cannot be
/// serialized, cloned, or reconstructed from a public identifier.
pub struct StatelessTerminalAgentLifecycleExclusion {
    _process_guard: tokio::sync::OwnedMutexGuard<()>,
    _durable_guard: Option<std::fs::File>,
}

/// Canonically acquired process + cross-process exclusions for a bounded set
/// of agents participating in one authorization relationship.
pub struct StatelessTerminalAgentSetLifecycleExclusion {
    _process_guards: Vec<tokio::sync::OwnedMutexGuard<()>>,
    _durable_guards: Vec<std::fs::File>,
}

/// Owned exact-execution lifecycle fence. Public execution controls and the
/// receipt publisher share this guard so a cancellation cannot land between
/// the publisher's durable-state recheck and exact pause activation.
pub struct StatelessTerminalExecutionLifecycleExclusion {
    _process_guard: tokio::sync::OwnedMutexGuard<()>,
    _durable_guard: Option<std::fs::File>,
}

/// Composite terminal pause transaction guard. Agent-wide mutations acquire
/// the first authority; exact execution controls acquire the second.
pub struct StatelessTerminalLifecycleExclusion {
    _agent: StatelessTerminalAgentLifecycleExclusion,
    _execution: StatelessTerminalExecutionLifecycleExclusion,
}

const STATELESS_AGENT_LIFECYCLE_LOCK_STRIPES: usize = 256;
static STATELESS_AGENT_LIFECYCLE_LOCKS: OnceLock<Box<[Arc<tokio::sync::Mutex<()>>]>> =
    OnceLock::new();

fn stateless_agent_lifecycle_locks() -> &'static [Arc<tokio::sync::Mutex<()>>] {
    STATELESS_AGENT_LIFECYCLE_LOCKS.get_or_init(|| {
        (0..STATELESS_AGENT_LIFECYCLE_LOCK_STRIPES)
            .map(|_| Arc::new(tokio::sync::Mutex::new(())))
            .collect::<Vec<_>>()
            .into_boxed_slice()
    })
}

fn stateless_agent_lifecycle_digest(principal: &str, workspace: &str, agent_id: &str) -> [u8; 32] {
    let mut digest = Sha256::new();
    digest.update(b"magician.stateless-agent-lifecycle.v1\0");
    for value in [principal, workspace, agent_id] {
        digest.update((value.len() as u64).to_le_bytes());
        digest.update(value.as_bytes());
    }
    digest.finalize().into()
}

const STATELESS_EXECUTION_LIFECYCLE_LOCK_STRIPES: usize = 256;
static STATELESS_EXECUTION_LIFECYCLE_LOCKS: OnceLock<Box<[Arc<tokio::sync::Mutex<()>>]>> =
    OnceLock::new();

fn stateless_execution_lifecycle_locks() -> &'static [Arc<tokio::sync::Mutex<()>>] {
    STATELESS_EXECUTION_LIFECYCLE_LOCKS.get_or_init(|| {
        (0..STATELESS_EXECUTION_LIFECYCLE_LOCK_STRIPES)
            .map(|_| Arc::new(tokio::sync::Mutex::new(())))
            .collect::<Vec<_>>()
            .into_boxed_slice()
    })
}

/// Longest a lifecycle caller waits for an in-process stripe before failing.
///
/// Legitimate holders keep a stripe for the length of one admission or one
/// terminal receipt — well under a second. A holder that never returns is a
/// task that re-acquired a fence it already held (the tokio mutex is not
/// reentrant) or that is itself parked behind another stripe; waiting forever
/// on it turns a bug into a silent wedge with nothing in the log. The durable
/// flock beneath each stripe already gives up after 5 s for the same reason.
const STATELESS_LIFECYCLE_PROCESS_LOCK_WAIT: Duration = Duration::from_secs(30);

/// Take one in-process lifecycle stripe within `wait`.
async fn lock_lifecycle_stripe(
    lock: Arc<tokio::sync::Mutex<()>>,
    wait: Duration,
    fence: &'static str,
) -> Result<tokio::sync::OwnedMutexGuard<()>> {
    tokio::time::timeout(wait, lock.lock_owned())
        .await
        .map_err(|_| {
            anyhow!(
                "timed out after {}s waiting for the in-process {fence} lifecycle exclusion; \
                 its holder in this process never released it (a task re-acquiring a fence it \
                 already holds, or parked behind another stripe)",
                wait.as_secs()
            )
        })
}

fn stateless_execution_lifecycle_digest(
    principal: &str,
    workspace: &str,
    execution_id: &str,
) -> [u8; 32] {
    let mut digest = Sha256::new();
    digest.update(b"magician.stateless-execution-lifecycle.v1\0");
    for value in [principal, workspace, execution_id] {
        digest.update((value.len() as u64).to_le_bytes());
        digest.update(value.as_bytes());
    }
    digest.finalize().into()
}

pub struct FullPauseStore {
    /// Map of storage_key -> FullPauseData
    data: DashMap<String, FullPauseData>,
    /// Exact durable revision represented by an in-memory body. Cross-process
    /// claim/replacement writers update the canonical envelope independently;
    /// public take paths compare this fence before returning cached content.
    memory_pause_authority: DashMap<String, PersistedPauseAuthority>,
    /// Fast in-process mirror of the durable pre-receipt activation marker.
    /// The envelope remains authoritative after restart.
    stateless_terminal_pending_activation: DashMap<String, String>,
    /// Bounded execution -> exact-key index for hidden generations. A set is
    /// required because activating one pause must not make a sibling staged
    /// generation disappear from public admission checks.
    stateless_terminal_pending_executions: DashMap<String, HashSet<String>>,
    /// Exact generation retained after projector activation until the live
    /// outer reducer adopts it. This closes the cursor-save failure window in
    /// which the immutable receipt still names A but a second pause write
    /// would otherwise replace it with B.
    stateless_terminal_prepared_authority: DashMap<String, PersistedPauseAuthority>,
    /// Crash-recovery metadata indexed once at startup, avoiding a full scoped
    /// pause-directory scan for every execution capability read.
    persisted_pending_by_execution: DashMap<String, HashMap<String, PendingPauseInfo>>,
    persisted_index_hydrated: AtomicBool,
    /// Pre-V2 monoliths whose irreversible `k2_` filenames cannot be mapped
    /// back to a storage key by bounded metadata discovery. Startup only queues
    /// their paths; a dedicated execution-runtime job hydrates at most one
    /// bounded batch and repairs the in-memory index.
    legacy_pending_repair_paths: DashMap<std::path::PathBuf, ()>,
    /// Successfully repaired legacy paths for this boot. Repeated bounded
    /// discovery remains idempotent without reopening the large monolith.
    legacy_repaired_paths: DashMap<std::path::PathBuf, LegacyPauseFileRevision>,
    /// Deterministically malformed legacy records are retained on disk for
    /// operator recovery, but are not reopened on every discovery pass.
    legacy_quarantined_paths: DashMap<std::path::PathBuf, LegacyPauseFileRevision>,
    legacy_repair_attempts: DashMap<std::path::PathBuf, u8>,
    legacy_repair_background_started: AtomicBool,
    /// Startup keeps repaired legacy metadata non-authoritative until the
    /// execution-record orphan policy has examined the complete repaired set.
    legacy_repair_reconciliation_pending: AtomicBool,
    /// A repair path is removed from the pending map while it is being read.
    /// Track that window explicitly so request paths never mistake an in-flight
    /// migration for a proven absence.
    legacy_repair_inflight: AtomicU32,
    #[cfg(any(test, feature = "test-fixtures"))]
    legacy_repair_injected_runtime_failures: AtomicU32,
    /// Bounded per-key mutation serialization. A pause commit spans multiple
    /// filesystem operations (body publish, envelope publish, old-body
    /// reclamation) and must not interleave with another commit or revocation
    /// for the same key. Stripes bound the permanent lock footprint while
    /// preserving that authority boundary.
    mutation_locks: Box<[StdMutex<()>]>,
    /// Optional persistence target for crash recovery.
    persistence_target: Option<PausePersistenceTarget>,
    /// Canonical monotonic authority for protected app pause generations.
    /// Present only for scoped V3 persistence; flat/ephemeral stores cannot
    /// admit protected app continuations.
    app_registry: Option<crate::magician_v2::apps::registry::AppRegistryService>,
    app_pause_claims: DashMap<String, AppPauseControlClaim>,
    /// Exact process-local bridge between committed source revocation and a
    /// concurrently polling member heartbeat. Durable transaction state plus
    /// source absence handles restart; this map disambiguates only the live
    /// in-process retirement race.
    manual_resume_retirement_receipts: DashMap<String, ManualResumeRetirementReceipt>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct PersistedPauseAuthority {
    revision: String,
    body_sha256: String,
    /// The authorization hash sealed into the envelope — taken over the body
    /// as read back from disk, which is the form the resume hashes. The
    /// in-process authority record is stamped with this same value, so a
    /// field that does not survive its serde round trip cannot split the
    /// stage side from the resume side.
    authorization_hash: String,
}

struct StoredPauseCommit {
    key: String,
    authority: Option<PersistedPauseAuthority>,
}

enum PauseStorePrecondition {
    ReliablyAbsent,
    StatelessTerminalPreparation,
    ManualResumeExact {
        control_generation: String,
        claim_binding: ManualResumeClaimBinding,
        source_revision: String,
    },
}

/// Exact durable identity returned to a caller that may need to revoke a
/// just-published checkpoint after losing a separate runtime-status CAS.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct DurablePauseCommit {
    pub(crate) key: String,
    pub(crate) revision: String,
    pub(crate) body_sha256: String,
}

#[derive(Clone)]
struct AppPauseControlClaim {
    scope: crate::magician_v2::apps::records::AppScope,
    generation: u64,
    content_digest: crate::magician_v2::apps::models::AppDigest,
    claim_ref: crate::magician_v2::apps::models::AppReference,
    liveness: ProtectedPauseClaimLiveness,
}

impl std::fmt::Debug for AppPauseControlClaim {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("AppPauseControlClaim")
            .field("scope", &self.scope)
            .field("generation", &self.generation)
            .field("content_digest", &self.content_digest)
            .field("claim_ref", &self.claim_ref)
            .field("live", &self.liveness.live.load(Ordering::Acquire))
            .finish()
    }
}

