struct DigestingWriter<W> {
    inner: W,
    digest: Sha256,
    bytes: u64,
}

struct CappedPauseEnvelopeWriter {
    bytes: Vec<u8>,
}

impl CappedPauseEnvelopeWriter {
    fn new() -> Self {
        Self {
            bytes: Vec::with_capacity(8 * 1024),
        }
    }
}

impl std::io::Write for CappedPauseEnvelopeWriter {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        if (self.bytes.len() as u64).saturating_add(buf.len() as u64) > MAX_PAUSE_ENVELOPE_BYTES {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                "durable pause envelope exceeds the configured byte limit",
            ));
        }
        self.bytes.extend_from_slice(buf);
        Ok(buf.len())
    }

    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

impl<W> DigestingWriter<W> {
    fn new(inner: W) -> Self {
        Self {
            inner,
            digest: Sha256::new(),
            bytes: 0,
        }
    }
}

impl<W: std::io::Write> std::io::Write for DigestingWriter<W> {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        if self.bytes.saturating_add(buf.len() as u64) > MAX_PAUSE_BODY_BYTES {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                "durable pause body exceeds the configured byte limit",
            ));
        }
        let written = self.inner.write(buf)?;
        self.digest.update(&buf[..written]);
        self.bytes = self.bytes.saturating_add(written as u64);
        Ok(written)
    }

    fn flush(&mut self) -> std::io::Result<()> {
        self.inner.flush()
    }
}

struct DigestingReader<R> {
    inner: R,
    digest: Sha256,
    bytes: u64,
}

/// Bounded JSON reading, shared with the loop state store.
///
/// `pub(super)` rather than private since 2026-08-26: `run_loop::store::fs`
/// publishes and reads its own durable records and must apply the **same**
/// byte, node and nesting guards this reader applies to pause records. Copying
/// it there would have produced a second implementation of a subtle scanner —
/// string escapes, container depth, node counting — where a divergence would
/// only ever be found by the malformed file it failed to refuse.
pub(super) struct JsonDepthGuardReader<R> {
    inner: R,
    containers: Vec<u8>,
    expects_value: bool,
    nodes: usize,
    max_nodes: usize,
    in_string: bool,
    escaped: bool,
    bytes: u64,
    max_bytes: u64,
}

impl<R> JsonDepthGuardReader<R> {
    pub(super) fn new(inner: R, max_bytes: u64, max_nodes: usize) -> Self {
        Self {
            inner,
            containers: Vec::with_capacity(
                crate::magician_v2::json_traversal::MAX_RETAINED_JSON_DEPTH,
            ),
            expects_value: true,
            nodes: 0,
            max_nodes,
            in_string: false,
            escaped: false,
            bytes: 0,
            max_bytes,
        }
    }
}

impl<R: std::io::Read> std::io::Read for JsonDepthGuardReader<R> {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        let read = self.inner.read(buf)?;
        self.bytes = self.bytes.saturating_add(read as u64);
        if self.bytes > self.max_bytes {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                "durable pause JSON exceeds the configured byte limit",
            ));
        }
        for byte in &buf[..read] {
            if self.in_string {
                if self.escaped {
                    self.escaped = false;
                } else if *byte == b'\\' {
                    self.escaped = true;
                } else if *byte == b'"' {
                    self.in_string = false;
                }
                continue;
            }
            match *byte {
                b' ' | b'\n' | b'\r' | b'\t' => {},
                b'"' => {
                    if self.expects_value {
                        if self.nodes >= self.max_nodes {
                            return Err(std::io::Error::new(
                                std::io::ErrorKind::InvalidData,
                                "durable pause JSON exceeds the configured node limit",
                            ));
                        }
                        self.nodes = self.nodes.saturating_add(1);
                    }
                    self.expects_value = false;
                    self.in_string = true;
                },
                b'{' | b'[' => {
                    if self.expects_value {
                        if self.nodes >= self.max_nodes {
                            return Err(std::io::Error::new(
                                std::io::ErrorKind::InvalidData,
                                "durable pause JSON exceeds the configured node limit",
                            ));
                        }
                        self.nodes = self.nodes.saturating_add(1);
                    }
                    if self.containers.len()
                        >= crate::magician_v2::json_traversal::MAX_RETAINED_JSON_DEPTH
                    {
                        return Err(std::io::Error::new(
                            std::io::ErrorKind::InvalidData,
                            "durable pause JSON exceeds the configured nesting limit",
                        ));
                    }
                    self.containers.push(*byte);
                    self.expects_value = *byte == b'[';
                },
                b'}' => {
                    if self.containers.pop() != Some(b'{') {
                        return Err(std::io::Error::new(
                            std::io::ErrorKind::InvalidData,
                            "durable pause JSON has an unmatched closing delimiter",
                        ));
                    }
                    self.expects_value = false;
                },
                b']' => {
                    if self.containers.pop() != Some(b'[') {
                        return Err(std::io::Error::new(
                            std::io::ErrorKind::InvalidData,
                            "durable pause JSON has an unmatched closing delimiter",
                        ));
                    }
                    self.expects_value = false;
                },
                b':' => self.expects_value = true,
                b',' => self.expects_value = self.containers.last().copied() == Some(b'['),
                _ => {
                    if self.expects_value {
                        if self.nodes >= self.max_nodes {
                            return Err(std::io::Error::new(
                                std::io::ErrorKind::InvalidData,
                                "durable pause JSON exceeds the configured node limit",
                            ));
                        }
                        self.nodes = self.nodes.saturating_add(1);
                        self.expects_value = false;
                    }
                },
            }
        }
        if read == 0 && (!self.containers.is_empty() || self.in_string || self.escaped) {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                "durable pause JSON ended before its structure was complete",
            ));
        }
        Ok(read)
    }
}

impl<R> DigestingReader<R> {
    fn new(inner: R) -> Self {
        Self {
            inner,
            digest: Sha256::new(),
            bytes: 0,
        }
    }
}

impl<R: std::io::Read> std::io::Read for DigestingReader<R> {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        let read = self.inner.read(buf)?;
        self.digest.update(&buf[..read]);
        self.bytes = self.bytes.saturating_add(read as u64);
        if self.bytes > MAX_PAUSE_BODY_BYTES {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                "durable pause body exceeds the configured byte limit",
            ));
        }
        Ok(read)
    }
}

