    fn current_internal_pending_authority(
        &self,
        pending: &PendingPauseInfo,
    ) -> Option<PendingPauseInfo> {
        if self.persistence_target.is_none() {
            return Some(pending.clone());
        }
        let _mutation_guard = self.lock_mutation_key(&pending.key);
        let canonical_path = self
            .canonical_pause_path_for_scope(
                &pending.key,
                pending.principal.as_deref(),
                pending.workspace.as_deref(),
            )
            .ok()?;
        let _file_guard = Self::try_acquire_pause_file_lock_sync(&canonical_path).ok()?;
        let Ok(mut paths) = self.exact_pause_file_paths(
            &pending.key,
            pending
                .principal
                .as_deref()
                .zip(pending.workspace.as_deref()),
        ) else {
            return None;
        };
        if paths.len() != 1 {
            return None;
        }
        let path = paths.pop()?;
        match Self::pause_record_format(&path) {
            Ok(PauseRecordFormat::LegacyMonolith) => (!matches!(
                pending.pause_kind,
                Some(ExecutionPauseKind::ManualResumeInflight)
            ))
            .then(|| pending.clone()),
            Ok(PauseRecordFormat::VersionedEnvelope) => {
                let envelope = Self::read_pause_envelope(&path).ok()?;
                if envelope.key != pending.key
                    || envelope.pending.key != pending.key
                    || envelope.pending.execution_id != pending.execution_id
                    || envelope.pending.principal != pending.principal
                    || envelope.pending.workspace != pending.workspace
                {
                    return None;
                }
                if envelope.stateless_terminal_pending_activation {
                    return None;
                }
                if envelope.pending.pause_kind == Some(ExecutionPauseKind::ManualResumeInflight) {
                    let seal = envelope.manual_resume_inflight.as_ref()?;
                    verify_manual_resume_inflight(
                        &envelope,
                        envelope.pending.principal.as_deref()?,
                        envelope.pending.workspace.as_deref()?,
                        &envelope.pending.execution_id,
                        &seal.control_generation,
                    )
                    .ok()?;
                } else if envelope.manual_resume_inflight.is_some() {
                    return None;
                }
                // A rolling peer may have published a legitimate replacement
                // for this same key. Refresh the bounded local projection so
                // public reads converge without hydrating the continuation.
                self.index_persisted_pending(envelope.pending.clone());
                Some(envelope.pending)
            },
            Err(_) => None,
        }
    }

    fn current_public_pending_authority(
        &self,
        pending: &PendingPauseInfo,
    ) -> Option<PendingPauseInfo> {
        self.current_internal_pending_authority(pending)
            .filter(|current| {
                !matches!(
                    current.pause_kind,
                    Some(
                        ExecutionPauseKind::Delegation
                            | ExecutionPauseKind::PlacementRetry
                            | ExecutionPauseKind::ManualResumeInflight
                    )
                )
            })
    }

