    /// The gate must classify a send, and must not classify anything else.
    ///
    /// Classification is what the disclosure write point and the capture
    /// decision both key off, so it is the piece that fails silently: get it
    /// wrong and a send is neither recorded nor captured, and everything still
    /// looks fine.
    #[test]
    fn the_gate_classifies_a_send_and_lets_everything_else_through() {
        use std::collections::HashMap;

        use crate::magician_v2::execution::capability::ImplementationType;

        let pack = |capability: &str, action: Option<&str>| {
            let mut params: HashMap<String, serde_json::Value> = HashMap::new();
            if let Some(action) = action {
                params.insert("action".to_string(), serde_json::json!(action));
            }
            ExecutableAction::Pack {
                capability_name: capability.to_string(),
                implementation: ImplementationType::Compiled {
                    provider_name: "test".to_string(),
                },
                resolved_params: params,
            }
        };

        let (capability, action_token, class) =
            classify_outward_dispatch(&pack("gmail", Some("send"))).expect("a mail send");
        assert_eq!(capability, "gmail");
        assert_eq!(action_token, "send");
        assert_eq!(class, OutwardClass::Mail);
        assert_eq!(disclosure_channel(class), OutwardChannel::Email);

        // A send-only capability is classified with no action token at all —
        // the bare invocation IS the send.
        assert!(classify_outward_dispatch(&pack("imessage_send", None)).is_some());

        // Reading is not outward, so it is neither recorded nor captured.
        assert!(classify_outward_dispatch(&pack("gmail", Some("list_messages"))).is_none());
        assert!(classify_outward_dispatch(&pack("websearch", Some("search"))).is_none());

        // Non-Pack actions are outside this gate entirely.
        assert!(classify_outward_dispatch(&ExecutableAction::SleepUntil {
            wake_at: chrono::Utc::now(),
            reason: None,
        })
        .is_none());

        // And the disposition that classification feeds: capture unless
        // sending was deliberately turned on.
        let no_params: HashMap<String, serde_json::Value> = HashMap::new();
        assert!(matches!(
            outward_actions::outward_disposition("gmail", "send", &no_params, true),
            OutwardDisposition::Capture(_)
        ));
        assert!(matches!(
            outward_actions::outward_disposition("gmail", "send", &no_params, false),
            OutwardDisposition::Live(_)
        ));
    }

    #[test]
    fn accept_in_scope_does_not_skip_out_of_tree_pack_paths() {
        use std::collections::HashMap;

        use crate::magician_v2::execution::capability::ImplementationType;

        let pack = |capability: &str, file_path: &str| {
            let mut params: HashMap<String, serde_json::Value> = HashMap::new();
            params.insert("file_path".to_string(), serde_json::json!(file_path));
            ExecutableAction::Pack {
                capability_name: capability.to_string(),
                implementation: ImplementationType::Compiled {
                    provider_name: "files".to_string(),
                },
                resolved_params: params,
            }
        };

        assert!(
            action_has_out_of_tree_path(&pack("write_file", "/etc/passwd")),
            "absolute paths outside the work tree must still HITL under Accept"
        );
        assert!(
            !action_has_out_of_tree_path(&pack(
                "edit_file",
                "/Users/me/Development/magician/src/lib.rs"
            )),
            "in-tree absolute paths may skip file HITL"
        );
        assert!(
            !action_has_out_of_tree_path(&pack("write_file", "src/lib.rs")),
            "workspace-relative paths are in scope"
        );
        assert!(is_in_scope_fs_tool("write_file"));
        assert!(is_in_scope_fs_action(
            &pack("write_file", "/etc/passwd"),
            "write_file"
        ));

        let apply_patch = |patch: &str| {
            let mut params: HashMap<String, serde_json::Value> = HashMap::new();
            params.insert("patch".to_string(), serde_json::json!(patch));
            ExecutableAction::Pack {
                capability_name: "apply_patch".to_string(),
                implementation: ImplementationType::Compiled {
                    provider_name: "files".to_string(),
                },
                resolved_params: params,
            }
        };
        assert!(
            action_has_out_of_tree_path(&apply_patch(
                "--- a/unused\n+++ /etc/passwd\n@@ -1 +1 @@\n-x\n+y\n"
            )),
            "apply_patch paths live in the diff, not file_path"
        );
        assert!(
            !action_has_out_of_tree_path(&apply_patch(
                "--- a/src/lib.rs\n+++ b/src/lib.rs\n@@ -1 +1 @@\n-x\n+y\n"
            )),
            "in-tree apply_patch hunks may skip permission HITL"
        );
        assert!(
            action_has_out_of_tree_path(&pack("apply_patch", "")),
            "a pack with no extractable path must not skip permission HITL"
        );
        assert!(should_skip_serial_follow_ups(false, false));
        assert!(should_skip_serial_follow_ups(true, true));
        assert!(!should_skip_serial_follow_ups(true, false));

        let in_tree_read =
            ExecutableAction::File(crate::magician_v2::execution::actions::FileAction::Read {
                path: PathBuf::from("src/lib.rs"),
                encoding: None,
            });
        let out_of_tree_read =
            ExecutableAction::File(crate::magician_v2::execution::actions::FileAction::Read {
                path: PathBuf::from("/etc/passwd"),
                encoding: None,
            });
        let write =
            ExecutableAction::File(crate::magician_v2::execution::actions::FileAction::Write {
                path: PathBuf::from("src/lib.rs"),
                content: "x".to_string(),
                create_dirs: true,
            });
        let grep = ExecutableAction::Pack {
            capability_name: "grep".to_string(),
            implementation: ImplementationType::Compiled {
                provider_name: "files".to_string(),
            },
            resolved_params: HashMap::new(),
        };
        assert!(
            in_turn_join_eligible_action(&in_tree_read),
            "relative reads may overlap"
        );
        assert!(
            in_turn_join_eligible_action(&out_of_tree_read),
            "absolute reads stay parallelizable; sandbox roots decide HITL risk"
        );
        assert!(
            in_turn_join_eligible_action(&grep),
            "named reads with no path must still join"
        );
        assert!(
            !in_turn_join_eligible_action(&write),
            "writes stay out of join_all"
        );
        let workspace = "/Users/me/proj".to_string();
        let roots = [workspace.clone()];
        assert!(!extracted_paths_may_sandbox_hitl(
            &extracted_action_fs_paths(&in_tree_read),
            false,
            &roots
        ));
        assert!(extracted_paths_may_sandbox_hitl(
            &extracted_action_fs_paths(&out_of_tree_read),
            false,
            &roots
        ));
        assert!(
            extracted_paths_may_sandbox_hitl(
                &[PathBuf::from("/tmp/workspace-evil/secret")],
                false,
                &roots
            ),
            "substring /workspace is not a sandbox root"
        );
        assert!(!extracted_paths_may_sandbox_hitl(
            &extracted_action_fs_paths(&grep),
            false,
            &roots
        ));
        assert!(!extracted_paths_may_sandbox_hitl(
            &extracted_action_fs_paths(&out_of_tree_read),
            true,
            &[]
        ));
        assert!(!in_turn_slice_failed(&ExecutionHistory::new(), 0));
    }

