    #[test]
    fn decision_snapshot_drops_capture_only_browser_heap() {
        let merkle_tree = PageMerkleTree::from_dom_snapshot(
            "<main><button>Continue</button></main>",
            None,
            Some("https://example.test"),
            crate::magician_v2::execution::types::PageStage::Content,
        );
        let browser_state =
            EnvironmentState::Browser(crate::magician_v2::execution::types::PageState {
                visible_text: Some("visible evidence".to_string()),
                accessibility_tree: Some(serde_json::json!({
                    "role": "main",
                    "content": "accessible".repeat(8_192),
                })),
                dom_snapshot: Some("d".repeat(64 * 1024)),
                screenshot_data: Some("s".repeat(32 * 1024)),
                merkle_tree: Some(merkle_tree),
                ..Default::default()
            });

        let current = clone_environment_for_decision(&browser_state, true);
        let EnvironmentState::Browser(current_page) = current else {
            panic!("current decision state must remain browser-shaped");
        };
        assert!(current_page.dom_snapshot.is_none());
        assert!(current_page.merkle_tree.is_none());
        assert!(current_page.accessibility_tree.is_none());
        assert!(current_page
            .accessibility_snapshot_for_ai
            .as_ref()
            .is_some_and(|snapshot| snapshot.len() <= 3_000));
        assert!(current_page.screenshot_data.is_some());
        assert_eq!(
            current_page.visible_text.as_deref(),
            Some("visible evidence")
        );

        let mut record = stuck_counter_test_iteration_record(1, true);
        record.state_before = browser_state.clone();
        record.state_after = browser_state;
        let history = ExecutionHistory {
            iterations: vec![record],
            ..Default::default()
        };
        let snapshot = clone_history_for_decision(&history);
        for state in [
            &snapshot.iterations[0].state_before,
            &snapshot.iterations[0].state_after,
        ] {
            assert!(matches!(state, EnvironmentState::Uninitialized));
        }
        let EnvironmentState::Browser(original_page) = &history.iterations[0].state_before else {
            panic!("authoritative state must remain browser-shaped");
        };
        assert!(original_page.dom_snapshot.is_some());
        assert!(original_page.screenshot_data.is_some());

        let disk_backed = clone_environment_for_decision(
            &EnvironmentState::Browser(PageState {
                observation_id: Some("obs-1".to_string()),
                screenshot_data: Some("s".repeat(32 * 1024)),
                ..Default::default()
            }),
            false,
        );
        let EnvironmentState::Browser(disk_backed_page) = disk_backed else {
            panic!("disk-backed decision state must remain browser-shaped");
        };
        assert!(disk_backed_page.screenshot_data.is_none());
        assert_eq!(disk_backed_page.observation_id.as_deref(), Some("obs-1"));

        let mut retained_history = history;
        compact_completed_history_for_retention(&mut retained_history);
        for state in [
            &retained_history.iterations[0].state_before,
            &retained_history.iterations[0].state_after,
        ] {
            assert!(matches!(state, EnvironmentState::Uninitialized));
        }
    }

    #[test]
    fn decision_snapshot_rejects_deep_accessibility_json_on_a_small_stack() {
        std::thread::Builder::new()
            .name("decision-accessibility-small-stack".to_string())
            .stack_size(256 * 1024)
            .spawn(|| {
                let mut tree = Value::String("leaf".to_string());
                for _ in 0..10_000 {
                    tree = Value::Array(vec![tree]);
                }
                let mut source = EnvironmentState::Browser(PageState {
                    accessibility_tree: Some(tree),
                    ..PageState::default()
                });

                let snapshot = clone_environment_for_decision(&source, false);
                let EnvironmentState::Browser(snapshot) = snapshot else {
                    panic!("decision state remains browser-shaped");
                };
                assert!(snapshot.accessibility_tree.is_none());
                assert!(snapshot.accessibility_snapshot_for_ai.is_none());

                let EnvironmentState::Browser(page) = &mut source else {
                    unreachable!();
                };
                discard_json_iteratively(
                    page.accessibility_tree
                        .take()
                        .expect("authoritative tree remains owned"),
                );
            })
            .expect("spawn decision accessibility regression")
            .join()
            .expect("decision accessibility regression completes");
    }

    #[test]
    fn decision_snapshot_bounds_non_browser_environment_results() {
        let oversized = "x".repeat(16 * 1024);
        let cases = [
            EnvironmentState::Filesystem(FilesystemState {
                last_result: Some(oversized.clone()),
                error: Some(oversized.clone()),
                ..Default::default()
            }),
            EnvironmentState::Http(HttpState {
                last_response: Some(oversized.clone()),
                error: Some(oversized.clone()),
                ..Default::default()
            }),
            EnvironmentState::Shell(ShellState {
                last_stdout: Some(oversized.clone()),
                last_stderr: Some(oversized),
                ..Default::default()
            }),
        ];

        for state in cases {
            let snapshot = clone_environment_for_decision(&state, false);
            match snapshot {
                EnvironmentState::Filesystem(state) => {
                    assert!(state.last_result.is_some_and(|value| value.len() <= 2_000));
                    assert!(state.error.is_some_and(|value| value.len() <= 1_000));
                },
                EnvironmentState::Http(state) => {
                    assert!(state
                        .last_response
                        .is_some_and(|value| value.len() <= 2_000));
                    assert!(state.error.is_some_and(|value| value.len() <= 1_000));
                },
                EnvironmentState::Shell(state) => {
                    assert!(state.last_stdout.is_some_and(|value| value.len() <= 1_500));
                    assert!(state.last_stderr.is_some_and(|value| value.len() <= 500));
                },
                other => panic!("unexpected decision snapshot: {other:?}"),
            }
        }
    }

