    #[test]
    fn production_iteration_records_never_clone_complete_environment_state() {
        let source = include_str!("executor.rs");
        // Split on the attribute's opening, not on `#[cfg(test)]` exactly: the
        // crate split rewrote this module to
        // `#[cfg(any(test, feature = "test-fixtures"))]`, after which the old
        // literal matched nothing, the whole file counted as production, and
        // this test tripped over its own forbidden-string literals below.
        let production = source
            .find("\n#[cfg(test)]\nmod tests")
            .into_iter()
            .chain(source.find("\n#[cfg(any(test"))
            .min()
            .map(|at| &source[..at])
            .expect("production executor source");
        for forbidden in [
            "state_before: observed_state.clone(),",
            "state_after: observed_state.clone(),",
            "state_after: state_after.clone(),",
            "state_after: new_state.clone(),",
        ] {
            assert!(
                !production.contains(forbidden),
                "production iteration retention must not clone full environment state: {forbidden}"
            );
        }
    }

