    #[test]
    fn a_ceiling_ends_the_run_on_whichever_clock_notices_first() {
        // §4's second trap: the loop's bound is a `std::time::Instant`, which no
        // other process can evaluate, and the only thing that fired it promptly
        // was a spawned `sleep` that dies with its holder. The portable half is
        // now checked at boundary entry beside the monotonic one.
        //
        // Both, not either. They fail in opposite directions — a monotonic clock
        // ignores an NTP step but may not advance across a machine suspend; a
        // wall clock does the reverse — so the ceiling holds only if whichever
        // notices first is allowed to end the run.
        let now = Utc::now();

        assert!(
            !wall_clock_deadline_exceeded(None, now),
            "no ceiling configured is not a ceiling of zero"
        );
        assert!(
            wall_clock_deadline_exceeded(Some(now - chrono::Duration::seconds(1)), now),
            "a deadline in the past must end the run"
        );
        assert!(
            !wall_clock_deadline_exceeded(Some(now + chrono::Duration::seconds(60)), now),
            "a deadline still ahead must not"
        );
        // `>=` rather than `>`, which is what stops a zero-length remainder from
        // resuming into a fresh full budget.
        assert!(
            wall_clock_deadline_exceeded(Some(now), now),
            "a deadline reached exactly is reached"
        );
    }

    #[test]
    fn a_paused_run_carries_its_remainder_and_no_absolute_deadline() {
        // The two fields answer different questions and a pause is where that
        // difference shows. The clock STOPS while a human is deciding, so the
        // remainder is the truth and the segment's wall-clock instant is stale
        // the moment the pause begins — and a reader cannot tell a stale
        // absolute deadline from a live one, so carrying it would read as
        // authoritative and be wrong.
        let ctx = AgenticContext::new("goal", "criteria");
        let protective = LoopProtectiveState {
            remaining_max_duration_ms: Some(90_000),
            deadline_at: Some(Utc::now() + chrono::Duration::seconds(90)),
            ..LoopProtectiveState::default()
        };

        let pause = build_full_pause_state(
            5,
            &ctx,
            &EnvironmentState::Uninitialized,
            &ExecutionHistory::new(),
            &protective,
            &[],
        );

        let carried = pause
            .loop_protective_state
            .expect("a run with a ceiling must carry it into the pause");
        assert_eq!(
            carried.remaining_max_duration_ms,
            Some(90_000),
            "the remainder is what a resumed run continues from"
        );
        assert!(
            carried.deadline_at.is_none(),
            "a paused run's clock is stopped, so it must not record an absolute \
             deadline that keeps ticking while nothing runs"
        );
    }

    #[test]
    fn a_stateless_pause_carries_its_exact_source_segment_and_inprocess_does_not() {
        let mut ctx = AgenticContext::new("goal", "criteria");
        ctx.execution_id = Some("exec-handoff".to_string());
        ctx.stateless_active_segment = Some("exec-handoff-r7-p1-s2-a3".to_string());

        let pause = build_full_pause_state(
            4,
            &ctx,
            &EnvironmentState::Uninitialized,
            &ExecutionHistory::new(),
            &LoopProtectiveState::default(),
            &[],
        );
        assert_eq!(
            pause.stateless_parked_segment.as_deref(),
            Some("exec-handoff-r7-p1-s2-a3"),
            "the source retains every address axis present only on the live context"
        );

        ctx.stateless_active_segment = None;
        let inprocess_pause = build_full_pause_state(
            4,
            &ctx,
            &EnvironmentState::Uninitialized,
            &ExecutionHistory::new(),
            &LoopProtectiveState::default(),
            &[],
        );
        assert!(
            inprocess_pause.stateless_parked_segment.is_none(),
            "the rollback driver has no loop-state source for the lifecycle to retire"
        );
    }

    #[test]
    fn clearing_the_deadline_never_writes_an_empty_bundle() {
        // The `deadline_at`-only bundle. Pristine-ness is judged on what is
        // written rather than on the live bundle, so clearing the one occupant
        // must drop the record entirely — otherwise every pause of a ceilinged
        // run grows by a `"loop_protective_state":{}` that says nothing, on a
        // body that is fsynced on every pause.
        let ctx = AgenticContext::new("goal", "criteria");
        let protective = LoopProtectiveState {
            deadline_at: Some(Utc::now() + chrono::Duration::seconds(90)),
            ..LoopProtectiveState::default()
        };
        assert!(
            !protective.is_pristine(),
            "fixture must be non-pristine before the clear, or this proves nothing"
        );

        let pause = build_full_pause_state(
            1,
            &ctx,
            &EnvironmentState::Uninitialized,
            &ExecutionHistory::new(),
            &protective,
            &[],
        );

        assert!(
            pause.loop_protective_state.is_none(),
            "a bundle emptied by the pause-time clear must not be written at all"
        );
    }

    #[test]
    fn deadline_exceeded_pure() {
        use std::time::Duration;
        let now = Instant::now();
        // No ceiling configured → never exceeded.
        assert!(!deadline_exceeded(None, now));
        // Deadline in the past → exceeded.
        assert!(deadline_exceeded(
            now.checked_sub(Duration::from_secs(1)),
            now
        ));
        // Deadline in the future → not yet.
        assert!(!deadline_exceeded(Some(now + Duration::from_secs(10)), now));
    }

