    #[test]
    fn tool_scope_trimmed_deny_rules_fail_closed() {
        let mut ctx = AgenticContext::new("goal", "criteria");
        ctx.merged_agent_tools = vec![runtime_core::ToolInfo {
            name: " browser ".to_string(),
            description: "Browser".to_string(),
            category: "custom".to_string(),
            categories: Vec::new(),
            parameters: Vec::new(),
            enhanced_description: None,
            keywords: Vec::new(),
            use_cases: Vec::new(),
            composition_category: None,
            providing_agent_id: None,
        }];
        ctx.denied_capability_names = vec![" shell ".to_string(), " core_utility ".to_string()];

        let scope = compute_dispatch_tool_scope(&ctx);
        assert!(scope.iter().any(|name| name == "browser"));
        assert!(!scope.iter().any(|name| name == "shell"));
        assert!(!scope.iter().any(|name| name == "time_math"));

        let action = ExecutableAction::Pack {
            capability_name: "shell".to_string(),
            implementation:
                crate::magician_v2::execution::capability::ImplementationType::Compiled {
                    provider_name: "shell".to_string(),
                },
            resolved_params: HashMap::new(),
        };
        let rejection = validate_action_against_allowlists(&action, &ctx);
        assert!(rejection.is_some_and(|reason| reason.contains("denied")));

        // Production AgentDefinition::resolved_tools canonicalizes the merged
        // ToolInfo name before action validation; the padded name above exists
        // only to exercise dispatch-scope normalization.
        ctx.merged_agent_tools[0].name = "browser".to_string();
        ctx.denied_tool_params = HashMap::from([(
            " browser ".to_string(),
            HashMap::from([(" query ".to_string(), vec!["secret:".to_string()])]),
        )]);
        ctx.prior_user_memory = Some("old owner memory".to_string());
        ctx.prior_procedure_memory = Some("old owner procedure".to_string());
        ctx.mark_task_prompt_context_seeded();
        let parameter_denied = ExecutableAction::Pack {
            capability_name: "browser".to_string(),
            implementation:
                crate::magician_v2::execution::capability::ImplementationType::Compiled {
                    provider_name: "browser".to_string(),
                },
            resolved_params: HashMap::from([(
                "query".to_string(),
                Value::String("  SECRET:value".to_string()),
            )]),
        };
        let rejection = validate_action_against_allowlists(&parameter_denied, &ctx);
        assert!(rejection.is_some_and(|reason| reason.contains("matches denied prefix")));

        let mut invalid_untrusted = AgenticContext::new("goal", "criteria");
        invalid_untrusted.trust_level = Some(" Untrusted ".to_string());
        let scope = compute_dispatch_tool_scope(&invalid_untrusted);
        assert!(scope.is_empty());
        assert!(!scope.iter().any(|name| name == "shell"));
    }

