    #[test]
    fn lifecycle_terminal_confirmation_replay_is_owner_bound_and_one_time() {
        let action = control_decision_action(&Decision::Yield {
            payload: crate::magician_v2::execution::agentic::yield_decision::YieldDecision {
                summary: "done".to_string(),
                ..Default::default()
            },
        })
        .expect("yield action");
        let action_json = stable_confirmation_action_json(&action).expect("serialize action");
        let owner_ctx = AgenticContext::new("goal", "criteria")
            .with_owner_snapshot("owner-a", vec!["root".to_string()]);
        let other_owner_ctx = AgenticContext::new("goal", "criteria")
            .with_owner_snapshot("owner-b", vec!["root".to_string()]);
        let mut approved = vec![ApprovedConfirmationAction {
            action_json: action_json.clone(),
            owner_snapshot: owner_ctx.current_owner_snapshot().expect("owner snapshot"),
        }];

        assert!(!take_matching_approved_confirmation(
            &mut approved,
            &action_json,
            &other_owner_ctx
        ));
        assert!(take_matching_approved_confirmation(
            &mut approved,
            &action_json,
            &owner_ctx
        ));
        assert!(!take_matching_approved_confirmation(
            &mut approved,
            &action_json,
            &owner_ctx
        ));
    }

