        let mut pause = AgenticPauseState::new(
            1,
            "goal",
            "criteria",
            EnvironmentState::Shell(ShellState::default()),
            "history",
            10,
            2,
        );
        enrich_pause_state_from_context(&ctx, &mut pause);
        assert!(pause.preserve_initial_tool_scope);
        assert_eq!(pause.preserved_initial_tools.len(), 1);

        let restored = restore_context_from_pause(&pause, "goal", "criteria", 10);
