    #[test]
    fn app_scope_survives_owner_refresh_without_adding_universal_tools() {
        let tool = |name: &str| runtime_core::ToolInfo {
            name: name.to_owned(),
            description: "Reviewed app tool".to_owned(),
            category: "app_workflow".to_owned(),
            categories: Vec::new(),
            parameters: Vec::new(),
            enhanced_description: None,
            keywords: Vec::new(),
            use_cases: Vec::new(),
            composition_category: None,
            providing_agent_id: None,
        };
        let preserved = vec![
            tool("agent_roster_data"),
            tool("app_store_query"),
            tool("app_commit_mutations"),
        ];
        let current = vec![tool("http")];
        let mut definition = crate::magician_v2::agents::AgentDefinition::from_yaml_str(
            "agent_id: owner\nname: Owner\npersona: Test\ntrust_level: local\ntools: [http]\n",
        )
        .expect("definition");
        let mut ctx = AgenticContext::new("app goal", "criteria");
        ctx.app_disclosure_guard = Some(app_disclosure_test_guard("app-local", 'a'));
        ctx.merged_agent_tools =
            revalidate_preserved_direct_tool_scope(&preserved, &current, &definition, true);
        assert_eq!(
            compute_dispatch_tool_scope(&ctx),
            vec![
                "agent_roster_data",
                "app_store_query",
                "app_commit_mutations"
            ]
        );
        let catalog = super::super::native_integration::build_catalog_context(&ctx);
        assert_eq!(catalog.direct_capabilities.len(), 3);
        assert!(!catalog
            .direct_capabilities
            .iter()
            .any(|tool| tool.0 == "http"));

        definition.denied_tools = vec!["agent_roster_data".to_owned()];
        let narrowed =
            revalidate_preserved_direct_tool_scope(&preserved, &current, &definition, true);
        assert_eq!(narrowed.len(), 2);
        assert!(!narrowed.iter().any(|tool| tool.name == "agent_roster_data"));

        // An empty protected scope must not become the generic native catalog.
        ctx.merged_agent_tools.clear();
        assert!(
            super::super::native_integration::build_catalog_context(&ctx)
                .direct_capabilities
                .is_empty()
        );
    }

    #[test]
    fn narrowed_one_pack_scope_is_revalidated_against_current_direct_owner_grants() {
        let tool = |name: &str, description: &str, provider: Option<&str>| runtime_core::ToolInfo {
            name: name.to_string(),
            description: description.to_string(),
            category: "custom".to_string(),
            categories: Vec::new(),
            parameters: Vec::new(),
            enhanced_description: None,
            keywords: Vec::new(),
            use_cases: Vec::new(),
            composition_category: None,
            providing_agent_id: provider.map(str::to_string),
        };
        let preserved = vec![
            tool("browser", "stale browser metadata", None),
            tool("removed-pack", "removed", None),
            tool("delegate-pack", "formerly direct", None),
            tool("search_memory", "current registry selection", None),
        ];
        let current = vec![
            tool("browser", "current browser metadata", None),
            tool("delegate-pack", "now delegated", Some("worker")),
            tool("new-pack", "not in preserved ceiling", None),
        ];
        let definition = crate::magician_v2::agents::AgentDefinition::from_yaml_str(
            "agent_id: owner\nname: Owner\npersona: Test\ntrust_level: local\ntools:\n  - \
             browser\n",
        )
        .expect("definition");

        let revalidated =
            revalidate_preserved_direct_tool_scope(&preserved, &current, &definition, false);
        assert_eq!(revalidated.len(), 2);
        assert_eq!(revalidated[0].name, "browser");
        assert_eq!(revalidated[0].description, "current browser metadata");
        assert!(revalidated[0].providing_agent_id.is_none());
        assert_eq!(revalidated[1].name, "search_memory");

        let mut delegated_collision = current.clone();
        delegated_collision.push(tool(
            "search_memory",
            "delegate-owned collision",
            Some("memory-worker"),
        ));
        let revalidated = revalidate_preserved_direct_tool_scope(
            &preserved,
            &delegated_collision,
            &definition,
            false,
        );
        assert_eq!(
            revalidated
                .iter()
                .map(|tool| tool.name.as_str())
                .collect::<Vec<_>>(),
            vec!["browser"]
        );

        let mut denied_definition = definition;
        denied_definition.denied_tools = vec!["search_memory".to_string()];
        let revalidated =
            revalidate_preserved_direct_tool_scope(&preserved, &current, &denied_definition, false);
        assert_eq!(
            revalidated
                .iter()
                .map(|tool| tool.name.as_str())
                .collect::<Vec<_>>(),
            vec!["browser"]
        );
    }

