    /// Pins the carry, which is the half of this feature that plumbing can
    /// silently break: the ceiling declared on the AGENT DEFINITION must reach
    /// the execution context, the executors, and the flat `PrimitiveExecCtx`
    /// that browser dispatch actually reads. A ceiling that stopped anywhere in
    /// that chain would look declared and enforce nothing.
    ///
    /// Also pins that the ceiling is REPLACED rather than merged on an owner
    /// transition. A delegated child that inherited its unrestricted parent's
    /// transports is precisely the delegation hole this exists to close.
    #[test]
    fn an_owner_transition_replaces_the_browser_transport_ceiling_end_to_end() {
        let executors =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager());
        let mut ctx = AgenticContext::new("goal", "criteria");
        ctx.active_owner_agent_id = Some("owner-a".to_string());
        assert!(
            ctx.browser_transports.is_empty(),
            "the parent frame declares nothing, so it may use every transport"
        );

        let confined = profile_with_browser_transports(
            "web-researcher",
            "browser_transports:\n  - \
             headless\n  - headed\n",
        );
        apply_owner_execution_profile(&mut ctx, &executors, &confined, vec!["owner-a".to_string()]);

        assert_eq!(ctx.browser_transports, vec!["headless", "headed"]);
        // Agent and ceiling are read from ONE snapshot, because the transition
        // now writes them in one swap. Read separately, this assertion would
        // pass against a runtime where a dispatch landing mid-transition saw the
        // new agent holding the previous owner's wider ceiling.
        let identity = executors.run_identity.get();
        assert_eq!(
            identity.browser_transports.clone(),
            vec!["headless".to_string(), "headed".to_string()],
            "the flat exec ctx builder reads the executors, not the context"
        );
        assert_eq!(
            identity.agent_id.as_deref(),
            Some("web-researcher"),
            "the agent and the ceiling it is confined to must arrive together — a \
             narrow delegate seen with its predecessor's ceiling is the pairing \
             `browser_transports` exists to prevent"
        );
        let exec_ctx = build_primitive_exec_ctx(&executors);
        assert_eq!(exec_ctx.browser_transports, vec!["headless", "headed"]);
        assert!(
            crate::magician_v2::execution::primitive_dispatch::browser::BrowserTransportCeiling::parse(
                &exec_ctx.browser_transports,
            )
            .expect("ceiling parses")
            .resolve(
                crate::magician_v2::execution::primitive_dispatch::browser::ConnectionMode::default(
                ),
            )
            .is_err(),
            "the owner's own signed-in Chrome must be unreachable under this ceiling"
        );

        // Transitioning to an agent that declares nothing must WIDEN back, not
        // keep the previous owner's narrower list: the ceiling is a fact about
        // whoever owns the frame right now.
        let unrestricted = profile_with_browser_transports("personal-assistant", "");
        apply_owner_execution_profile(
            &mut ctx,
            &executors,
            &unrestricted,
            vec!["web-researcher".to_string()],
        );
        assert!(ctx.browser_transports.is_empty());
        assert!(build_primitive_exec_ctx(&executors)
            .browser_transports
            .is_empty());
    }

    #[test]
    fn owner_profile_replacement_clears_prior_whole_tool_and_parameter_policy() {
        let definition = crate::magician_v2::agents::AgentDefinition::from_yaml_str(
            "agent_id: owner-b\nname: Owner B\npersona: Test\ntrust_level: reviewed\ntools:\n  - \
             search_memory\n",
        )
        .expect("definition");
        let direct_tool = runtime_core::ToolInfo {
            name: "search_memory".to_string(),
            description: "Scoped memory search".to_string(),
            category: "custom".to_string(),
            categories: Vec::new(),
            parameters: Vec::new(),
            enhanced_description: None,
            keywords: Vec::new(),
            use_cases: Vec::new(),
            composition_category: None,
            providing_agent_id: None,
        };
        let owner_routes = OperationRoutingOverrides {
            planning: crate::magician_v2::query_analysis::operation_llm_router::OperationRoutingEndpoint::for_profile(
                "owner-terra",
            ),
            memory_consolidation: crate::magician_v2::query_analysis::operation_llm_router::OperationRoutingEndpoint::for_profile(
                "owner-memory",
            ),
            ..Default::default()
        };
        let profile = OwnerExecutionProfile {
            definition,
            agent_id: "owner-b".to_string(),
            trust_level: Some("reviewed".to_string()),
            trust_policies_path: None,
            preloaded_trust_enforcer: None,
            approval_rules: Vec::new(),
            llm_model_override: None,
            llm_routing_overrides: Some(owner_routes),
            prompt_identity: None,
            delegation_targets: Vec::new(),
            merged_agent_tools: vec![direct_tool],
            denied_capability_names: vec!["shell".to_string()],
            denied_tool_params: HashMap::from([(
                "search_memory".to_string(),
                HashMap::from([("query".to_string(), vec!["secret:".to_string()])]),
            )]),
            invocation_policy: crate::magician_v2::agents::AgentInvocationPolicy::default(),
            allowed_action_types: Some(vec!["tool".to_string()]),
            max_delegation_depth: 1,
            delegation_timeout_secs: 30,
            tier_definitions: Vec::new(),
            available_procedure_skills: Vec::new(),
        };
        let mut ctx = AgenticContext::new("goal", "criteria");
        let execution_routes = OperationRoutingOverrides {
            planning: crate::magician_v2::query_analysis::operation_llm_router::OperationRoutingEndpoint::for_profile(
                "eval-luna",
            ),
            operations: std::collections::BTreeMap::from([(
                "evidence_precision_judge".to_string(),
                crate::magician_v2::query_analysis::operation_llm_router::OperationRoutingEndpoint::for_profile(
                    "eval-luna",
                )
                .expect("execution route"),
            )]),
            ..Default::default()
        };
        ctx.execution_llm_routing_overrides = Some(execution_routes.clone());
        ctx.active_owner_agent_id = Some("owner-a".to_string());
        ctx.denied_capability_names = vec!["http".to_string()];
        ctx.denied_tool_params = HashMap::from([(
            "browser".to_string(),
            HashMap::from([("url".to_string(), vec!["private:".to_string()])]),
        )]);
        let task_store = crate::magician_v2::execution::flat_loop::SurfaceWorkingSetStore::new(8);
        let prior_key = crate::magician_v2::execution::flat_loop::SurfaceWorkingSetKey::new(
            "owner",
            "default",
            "owner-a",
            crate::magician_v2::agents::InvocationSurface::Task,
            crate::magician_v2::agents::FeatureMode::None,
            "execution-a",
        );
        task_store.reconcile(&prior_key, "authority-a", &HashSet::new());
        ctx.surface_working_sets = Some(task_store.clone());
        *ctx.scratch
            .autonomous_surface_binding
            .lock()
            .expect("binding lock") = Some(
            crate::magician_v2::execution::agentic::types::AutonomousSurfaceRuntimeBinding {
                key: prior_key,
                authority_revision: "authority-a".to_string(),
                authorized_tool_names: HashSet::new(),
            },
        );
        let executors =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager());

        // Agent-scoped memory is owner-specific and must not survive a swap;
        // the owner's taste profile is owner-LEVEL and must (the design's
        // rule: a child working the owner's task does not shed the owner's
        // standing directives). Seed both and assert they part ways.
        ctx.prior_user_memory = Some("owner-a memory".to_string());
        ctx.taste_profile = Some(crate::magician_v2::taste_profile::TasteProfileSnapshot {
            injectable: "## Voice\nBe terse.".to_string(),
            version: "frozen-v1".to_string(),
            over_ceiling: false,
            loaded_at: chrono::Utc::now(),
        });

        apply_owner_execution_profile(&mut ctx, &executors, &profile, vec!["owner-a".to_string()]);

        assert!(
            ctx.prior_user_memory.is_none(),
            "agent-scoped memory is cleared on an owner swap"
        );
        assert_eq!(
            ctx.taste_profile.as_ref().map(|p| p.version.as_str()),
            Some("frozen-v1"),
            "the owner's taste profile survives the swap, frozen version intact — a delegated \
             child inherits it rather than shedding it"
        );

        assert_eq!(ctx.active_owner_agent_id.as_deref(), Some("owner-b"));
        let effective_routes = ctx
            .llm_routing_overrides
            .as_ref()
            .expect("effective owner and execution routes");
        assert_eq!(
            effective_routes
                .planning
                .as_ref()
                .and_then(|endpoint| endpoint.profile_name()),
            Some("eval-luna")
        );
        assert_eq!(
            effective_routes
                .memory_consolidation
                .as_ref()
                .and_then(|endpoint| endpoint.profile_name()),
            Some("owner-memory")
        );
        assert_eq!(
            ctx.execution_llm_routing_overrides,
            Some(execution_routes),
            "owner hydration must not replace the immutable execution overlay"
        );
        assert_eq!(ctx.owner_stack, vec!["owner-a"]);
        assert_eq!(ctx.denied_capability_names, vec!["shell"]);
        assert!(!ctx.denied_tool_params.contains_key("browser"));
        assert!(ctx.denied_tool_params.contains_key("search_memory"));
        assert_eq!(
            ctx.merged_agent_tools
                .iter()
                .map(|tool| tool.name.as_str())
                .collect::<Vec<_>>(),
            vec!["search_memory"]
        );
        assert_eq!(task_store.status().entry_count, 0);
        assert!(ctx
            .scratch
            .autonomous_surface_binding
            .lock()
            .expect("binding lock")
            .is_none());
        assert!(ctx.prior_user_memory.is_none());
        assert!(ctx.prior_procedure_memory.is_none());
        assert_eq!(ctx.task_prompt_context_generation, 1);
        assert_eq!(ctx.task_prompt_context_hydrated_generation, None);

        // Reloading an unchanged owner profile at a provider boundary must not
        // evict its semantic context or promoted family. That was the source
        // of per-iteration task retrieval before explicit checkpoints.
        ctx.prior_user_memory = Some("current owner memory".to_string());
        ctx.prior_procedure_memory = Some("current owner procedure".to_string());
        ctx.mark_task_prompt_context_seeded();
        ctx.scratch
            .loaded_tools
            .lock()
            .expect("loaded tools")
            .insert("search_memory".to_string());
        let generation = ctx.task_prompt_context_generation;
        apply_owner_execution_profile(&mut ctx, &executors, &profile, vec!["owner-a".to_string()]);
        assert_eq!(
            ctx.prior_user_memory.as_deref(),
            Some("current owner memory")
        );
        assert_eq!(
            ctx.prior_procedure_memory.as_deref(),
            Some("current owner procedure")
        );
        assert_eq!(ctx.task_prompt_context_generation, generation);
        assert!(ctx
            .scratch
            .loaded_tools
            .lock()
            .expect("loaded tools")
            .contains("search_memory"));
    }

    #[tokio::test]
    async fn task_prompt_context_hydrates_once_per_explicit_checkpoint() {
        let executors =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager());
        let mut ctx = AgenticContext::new("goal", "criteria");

        hydrate_prompt_context_after_owner_transition(&mut ctx, &executors).await;
        hydrate_prompt_context_after_owner_transition(&mut ctx, &executors).await;
        assert_eq!(ctx.task_prompt_context_hydration_count, 1);

        ctx.advance_task_prompt_context_checkpoint("operator_steer:focus on latency");
        hydrate_prompt_context_after_owner_transition(&mut ctx, &executors).await;
        hydrate_prompt_context_after_owner_transition(&mut ctx, &executors).await;
        assert_eq!(ctx.task_prompt_context_hydration_count, 2);
        assert_eq!(
            ctx.task_prompt_context_hydrated_generation,
            Some(ctx.task_prompt_context_generation)
        );

        ctx.advance_task_prompt_context_checkpoint("step_completed:research");
        hydrate_prompt_context_after_owner_transition(&mut ctx, &executors).await;
        assert_eq!(ctx.task_prompt_context_hydration_count, 3);
        assert!(owner_prompt_context_relevance_query(&ctx)
            .contains("checkpoint: step_completed:research"));
    }

    #[test]
    fn default_stack_scoped_task_context_hydration_fits_ordinary_worker() {
        // This is intentionally an OS thread with no stack-size override. The
        // production regression exhausted a default 2 MiB Tokio execution
        // worker while moving the raw three-stage retrieval future through
        // JoinSet::spawn, before any provider call was made.
        std::thread::Builder::new()
            .name("task-context-default-stack-test".to_string())
            .spawn(|| {
                let runtime = tokio::runtime::Builder::new_current_thread()
                    .enable_all()
                    .build()
                    .expect("default-stack test runtime");
                runtime.block_on(async {
                    let executors = ActionExecutors::new(
                        Arc::new(MockLlmService::new(vec![])),
                        test_prompt_manager(),
                    );
                    let mut ctx = AgenticContext::new("goal", "criteria");
                    ctx.principal = Some("principal-a".to_string());
                    ctx.workspace = Some("workspace-a".to_string());
                    ctx.agent_id = Some("owner-a".to_string());
                    ctx.active_owner_agent_id = Some("owner-a".to_string());
                    ctx.task_id = Some("task-a".to_string());
                    ctx.execution_id = Some("execution-a".to_string());

                    hydrate_prompt_context_after_owner_transition(&mut ctx, &executors)
                        .heap_boxed()
                        .await;

                    assert_eq!(ctx.task_prompt_context_hydration_count, 1);
                    assert_eq!(ctx.task_prompt_context_hydrated_generation, Some(0));
                });
            })
            .expect("spawn default-stack hydration thread")
            .join()
            .expect("scoped hydration must fit an ordinary worker stack");
    }

    #[test]
    fn default_stack_pack_direct_preflight_and_dispatch_fits_ordinary_worker() {
        // Reproduces the production crash shape: a Pack action traverses
        // secrets, authorization, both sandbox discriminators, and the direct
        // dispatch tail from an ordinary OS worker stack. The provider is
        // intentionally absent, so the test is hermetic while still crossing
        // the exact preflight-to-dispatch boundary that overflowed before the
        // "Executing action" log could be emitted.
        std::thread::Builder::new()
            .name("pack-preflight-default-stack-test".to_string())
            .spawn(|| {
                let runtime = tokio::runtime::Builder::new_current_thread()
                    .enable_all()
                    .build()
                    .expect("default-stack test runtime");
                runtime.block_on(async {
                    let mut executors = ActionExecutors::new(
                        Arc::new(MockLlmService::new(vec![])),
                        test_prompt_manager(),
                    );
                    let (scheduler_root_lane, scheduler_root_worker) =
                        SchedulerRootLane::new();
                    executors.scheduler_root_lane = Some(scheduler_root_lane);
                    let mut scheduler_root_workers = tokio::task::JoinSet::new();
                    let worker: Pin<Box<dyn Future<Output = ()> + Send>> =
                        Box::pin(scheduler_root_worker.run());
                    spawn_with_execution_token_meter_in_set(
                        &mut scheduler_root_workers,
                        worker,
                    );
                    let executors = Arc::new(executors);
                    let ctx = AgenticContext::new("defer blocked research", "task is deferred");
                    let observed_state = EnvironmentState::Shell(ShellState::default());
                    let mut current_state = observed_state.clone();
                    let mut history = ExecutionHistory::new();
                    let candidate = ActionCandidate::new(
                        1,
                        1.0,
                        ExecutableAction::Pack {
                            capability_name: "http".to_string(),
                            implementation: crate::magician_v2::execution::capability::ImplementationType::Compiled {
                                provider_name: "http".to_string(),
                            },
                            resolved_params: HashMap::from([
                                ("method".to_string(), json!("POST")),
                                (
                                    "url".to_string(),
                                    json!("http://localhost:3002/api/magician/v2/tasks/task-test/defer"),
                                ),
                                ("body".to_string(), json!({"retry_after_minutes": 30})),
                            ]),
                        },
                    )
                    .with_reasoning("defer until the policy controller stabilizes");
                    let thinking = candidate.reasoning.clone();
                    let execution_start = Instant::now();
                    let mut loop_protective = LoopProtectiveState::default();
                    let cancellation_token = None;

                    let result = execute_direct_path_core_body(
                        &ctx,
                        &observed_state,
                        &mut history,
                        5,
                        &executors,
                        // This test drives the direct path outside any phase, so
                        // there is no address to journal under and none is
                        // invented. See `PhaseAddress`.
                        None,
                        &candidate,
                        &thinking,
                        &execution_start,
                        "default-stack-pack-session",
                        None,
                        &mut current_state,
                        // No model tool call behind a harness dispatch.
                        None,
                        // …and therefore no gate-minted coding invocation either.
                        None,
                        // …and no driver effect plan, so no session to resume.
                        None,
                        &mut loop_protective,
                        &[],
                        "default-stack-pack-scope",
                        &cancellation_token,
                    )
                    .await;

                    if let Err(error) = result {
                        panic!("direct Pack path failed: {error}");
                    }
                    assert_eq!(history.iterations.len(), 1);
                    assert_eq!(
                        history.iterations[0].result.error.as_deref(),
                        Some("Pack capability 'http' requires a capability registry (not configured on ActionExecutors)")
                    );
                    scheduler_root_workers.abort_all();
                    while scheduler_root_workers.join_next().await.is_some() {}
                });
            })
            .expect("spawn default-stack Pack preflight thread")
            .join()
            .expect("Pack preflight and dispatch must fit an ordinary worker stack");
    }

    #[test]
    fn default_stack_tool_search_reuses_surface_authority_without_catalog_rebuild() {
        // This is the production crash shape from the web-research live eval:
        // the first decision calls `tool_search` against the full embedded index
        // while the direct-path poll chain is resident on a default-sized
        // execution worker. The already-resolved surface binding is the exact
        // discovery ceiling and must avoid rebuilding the full catalog here.
        std::thread::Builder::new()
            .name("tool-search-authority-default-stack-test".to_string())
            .spawn(|| {
                let runtime = tokio::runtime::Builder::new_current_thread()
                    .enable_all()
                    .build()
                    .expect("default-stack test runtime");
                runtime.block_on(async {
                    let mut executors = ActionExecutors::new(
                        Arc::new(MockLlmService::new(vec![])),
                        test_prompt_manager(),
                    );
                    let (scheduler_root_lane, scheduler_root_worker) =
                        SchedulerRootLane::new();
                    executors.scheduler_root_lane = Some(scheduler_root_lane);
                    let mut scheduler_root_workers = tokio::task::JoinSet::new();
                    let worker: Pin<Box<dyn Future<Output = ()> + Send>> =
                        Box::pin(scheduler_root_worker.run());
                    spawn_with_execution_token_meter_in_set(
                        &mut scheduler_root_workers,
                        worker,
                    );
                    let executors = Arc::new(executors);

                    let packs = crate::magician_v2::execution::compiled_providers::embedded_compiled_pack_defs();
                    let index = Arc::new(
                        crate::magician_v2::execution::flat_loop::build_tool_index(&packs),
                    );
                    let authorized_tool_names = std::collections::HashSet::from([
                        "save_preference".to_string(),
                        "search_memory".to_string(),
                        "tool_search".to_string(),
                    ]);
                    let mut ctx = AgenticContext::new(
                        "Compare current model prices",
                        "Official sources are cited",
                    );
                    // Keep the production scope populated. Without these
                    // fields the pre-dispatch active-procedure refresh returns
                    // before entering scoped storage, so the regression does
                    // not reproduce the live execution-worker stack shape.
                    ctx.principal = Some("anonymous".to_string());
                    ctx.workspace = Some("default".to_string());
                    ctx.agent_id = Some("web-researcher".to_string());
                    ctx.tool_index = Some(index);
                    *ctx.scratch.autonomous_surface_binding
                        .lock()
                        .expect("surface binding") =
                        Some(crate::magician_v2::execution::agentic::types::AutonomousSurfaceRuntimeBinding {
                            key: crate::magician_v2::execution::flat_loop::SurfaceWorkingSetKey::new(
                                "anonymous",
                                "default",
                                "web-researcher",
                                crate::magician_v2::agents::types::InvocationSurface::Task,
                                crate::magician_v2::agents::types::FeatureMode::None,
                                "exec-stack-regression",
                            ),
                            authority_revision: "authority-stack-regression".to_string(),
                            authorized_tool_names: authorized_tool_names.clone(),
                        });
                    *ctx.policy_dispatch_tool_names
                        .lock()
                        .expect("dispatch names") = Some(std::collections::BTreeSet::from([
                        "tool_search".to_string(),
                    ]));

                    assert_eq!(
                        tool_search_allowed_names_for_context(
                            &ctx,
                            ctx.tool_index.as_deref(),
                        ),
                        Some(std::collections::HashSet::from([
                            "save_preference".to_string(),
                            "search_memory".to_string(),
                        ])),
                        "the immutable surface authority must be reused exactly",
                    );

                    let observed_state = EnvironmentState::Shell(ShellState::default());
                    let mut current_state = observed_state.clone();
                    let mut history = ExecutionHistory::new();
                    let candidate = ActionCandidate::new(
                        1,
                        1.0,
                        ExecutableAction::Pack {
                            capability_name: "tool_search".to_string(),
                            implementation:
                                crate::magician_v2::execution::capability::ImplementationType::Compiled {
                                    provider_name: "tool_search".to_string(),
                                },
                            resolved_params: HashMap::from([(
                                "query".to_string(),
                                json!("select:save_preference,search_memory"),
                            )]),
                        },
                    )
                    .with_reasoning("load the bounded research tools");
                    let thinking = candidate.reasoning.clone();
                    let execution_start = Instant::now();
                    let mut loop_protective = LoopProtectiveState::default();
                    let cancellation_token = None;

                    let result = execute_direct_path_core_body(
                        &ctx,
                        &observed_state,
                        &mut history,
                        1,
                        &executors,
                        // This test drives the direct path outside any phase, so
                        // there is no address to journal under and none is
                        // invented. See `PhaseAddress`.
                        None,
                        &candidate,
                        &thinking,
                        &execution_start,
                        "tool-search-authority-session",
                        None,
                        &mut current_state,
                        // No model tool call behind a harness dispatch.
                        None,
                        // …and therefore no gate-minted coding invocation either.
                        None,
                        // …and no driver effect plan, so no session to resume.
                        None,
                        &mut loop_protective,
                        &[],
                        "tool-search-authority-scope",
                        &cancellation_token,
                    )
                    .await
                    .expect("tool_search direct path");

                    assert!(matches!(result, ExecutePathControl::Continue));
                    assert_eq!(history.iterations.len(), 1);
                    assert!(
                        history.iterations[0].result.success,
                        "tool_search must complete successfully regardless of prompt projection",
                    );
                    assert_eq!(
                        *ctx.scratch.loaded_tools.lock().expect("loaded tools"),
                        std::collections::HashSet::from([
                            "save_preference".to_string(),
                            "search_memory".to_string(),
                        ]),
                        "the selected tools must become the next turn's working set",
                    );

                    scheduler_root_workers.abort_all();
                    while scheduler_root_workers.join_next().await.is_some() {}
                });
            })
            .expect("spawn default-stack tool_search thread")
            .join()
            .expect("tool_search authority path must fit an ordinary worker stack");
    }

