    #[test]
    fn push_recent_summary_ring_capped_at_three() {
        let mut ring: std::collections::VecDeque<String> =
            std::collections::VecDeque::with_capacity(3);
        for s in ["a", "b", "c", "d", "e"] {
            push_recent_summary(&mut ring, s.to_string(), 3);
        }
        assert_eq!(ring.len(), 3);
        let collected: Vec<String> = ring.iter().cloned().collect();
        assert_eq!(
            collected,
            vec!["c".to_string(), "d".to_string(), "e".to_string()]
        );
        assert_eq!(ring.front().map(String::as_str), Some("c"));
        assert_eq!(ring.back().map(String::as_str), Some("e"));
    }

    /// Replay the forensic pattern from task_c65c697 through the stuck-detector
    /// counter + ring + threshold-emission logic, and assert the set of
    /// iterations on which a warning would have fired matches the hand-computed
    /// expectation.
    ///
    /// Source of truth for the pattern:
    ///   `docs/plans/2026-04-23-iteration-drag-fixes-design.md` (Motivation)
    ///   notes that 7 of 35 iterations in
    ///   `task_c65c697728a048dca11d301276c700b7` (execution
    ///   `exec_9c495a3bdef24c429e4acf8532001472`) produced a `plan.revised`
    ///   with no `agentic.decision_made` / `tool.succeeded`. The forensic
    ///   per-iteration breakdown (from the investigation conversation
    ///   prior to this implementation plan) places those 7 dead iterations
    ///   at 23, 24, 26, 27, 28, 31, 32. Successful (tool.succeeded-present)
    ///   iterations fill every other slot, including 1..=22, 25, 29, 30,
    ///   33, 34, 35.
    ///
    /// Encoding: a `Vec<bool>` of length 35 where `true` = iteration landed
    /// a tool (success), `false` = no-action. With threshold = 3 and a
    /// reset on success:
    ///   - Iter 22 end: counter = 0 (success)
    ///   - Iter 23 end: counter = 1
    ///   - Iter 24 end: counter = 2
    ///   - Iter 25 end: counter = 0 (success resets)
    ///   - Iter 26 end: counter = 1
    ///   - Iter 27 end: counter = 2
    ///   - Iter 28 end: counter = 3  -> WARNING at 28
    ///   - Iter 29 end: counter = 0 (success resets)
    ///   - Iter 30 end: counter = 0
    ///   - Iter 31 end: counter = 1
    ///   - Iter 32 end: counter = 2
    ///   - Iter 33 end: counter = 0 (success resets)
    ///
    /// Expected: the warning fires exactly once, at iteration 28.
    ///
    /// This test verifies the counter/ring/threshold mental model on the
    /// forensic schedule. It does NOT execute the production loop — see
    /// Unit B's tests for the primitive helpers' direct coverage.
    ///
    /// Concretely, the body below re-implements the counter-bump /
    /// reset-on-success / `push_recent_summary` / `counter >= THRESHOLD`
    /// sequence locally and runs it over the encoded schedule. It deliberately
    /// does NOT stand up an `AgenticContext` / `ActionExecutors` / LLM mock,
    /// and it does NOT call into the production executor loop around
    /// `executor.rs:23093-23143`. The intent is to pin down the arithmetic of
    /// the mental model on a known-pathological schedule, not to catch drift
    /// in the production implementation itself.
    #[test]
    fn stuck_detector_matches_task_c65c697_pattern() {
        // 1-indexed pattern: index 0 is unused (fixture starts at iter 1).
        // true = tool.succeeded present; false = no-action iteration.
        let mut schedule: Vec<bool> = Vec::with_capacity(36);
        schedule.push(true); // sentinel for index 0 — iterations are 1-based.
        for _ in 1..=22 {
            schedule.push(true); // iters 1..=22 all landed a tool
        }
        schedule.push(false); // 23 dead
        schedule.push(false); // 24 dead
        schedule.push(true); // 25 landed
        schedule.push(false); // 26 dead
        schedule.push(false); // 27 dead
        schedule.push(false); // 28 dead -> threshold cross
        schedule.push(true); // 29 landed
        schedule.push(true); // 30 landed
        schedule.push(false); // 31 dead
        schedule.push(false); // 32 dead
        schedule.push(true); // 33 landed
        schedule.push(true); // 34 landed
        schedule.push(true); // 35 landed
        assert_eq!(schedule.len(), 36, "schedule mis-encoded");

        // Mirror the STUCK_WARNING_THRESHOLD constant baked into the
        // executor loop (see `executor.rs` line ~16391). It is an internal
        // function-scoped constant and not exported — encoding it here
        // directly keeps the test self-contained and deterministic.
        const THRESHOLD: usize = 3;

        let mut counter: usize = 0;
        let mut ring: std::collections::VecDeque<String> =
            std::collections::VecDeque::with_capacity(THRESHOLD);
        let mut warnings_fired_on: Vec<usize> = Vec::new();

        for iter in 1..=35usize {
            let landed = schedule[iter];
            if landed {
                counter = 0;
                ring.clear();
            } else {
                counter += 1;
                push_recent_summary(
                    &mut ring,
                    format!("iter {iter}: no decision recorded"),
                    THRESHOLD,
                );
                if counter >= THRESHOLD {
                    warnings_fired_on.push(iter);
                }
            }
        }

        // Hand-computed: only iter 28 crosses the threshold in this
        // schedule. No other run of no-action iterations reaches 3 because
        // the successful iter 25 resets 23/24, the successful iter 29
        // resets 26/27/28's successor counter, and the successful iter 33
        // resets 31/32.
        let expected: Vec<usize> = vec![28];
        assert_eq!(
            warnings_fired_on, expected,
            "encoded schedule did not produce the expected warnings: expected the stuck-warning \
             to fire exactly once at iter 28 for the task_c65c697 forensic pattern; got \
             {warnings_fired_on:?} instead. This assertion checks the test's own mirror of the \
             counter/reset mental model — production drift in `executor.rs:23093-23143` is \
             covered by Unit B's primitive-helper tests, not by this replay."
        );

        // After iter 35 (success), the ring should be empty — every dead
        // streak in the pattern was followed by at least one success
        // before the loop ended.
        assert!(
            ring.is_empty(),
            "ring should be drained by successful iterations at the tail of the schedule; got \
             ring={:?}",
            ring
        );
        assert_eq!(
            counter, 0,
            "counter should be reset after the final successful iteration"
        );
    }

    #[test]
    fn stuck_detector_fires_on_every_iteration_at_or_above_threshold() {
        // Invariant #6 from the plan: the warning emits on the iteration when the
        // counter reaches the threshold AND on every subsequent no-action iteration
        // while the counter stays at or above the threshold. This test exercises
        // the "every iteration >= threshold" branch that the c65c697 replay cannot.
        const THRESHOLD: usize = 3;
        let mut counter: usize = 0;
        let mut ring: std::collections::VecDeque<String> =
            std::collections::VecDeque::with_capacity(THRESHOLD);
        let mut warnings_fired_on: Vec<usize> = Vec::new();

        // Schedule: 5 consecutive no-action iterations.
        for iter in 1..=5usize {
            // All false — every iteration is no-action.
            counter += 1;
            push_recent_summary(
                &mut ring,
                format!("iter {iter}: no decision recorded"),
                THRESHOLD,
            );
            if counter >= THRESHOLD {
                warnings_fired_on.push(iter);
            }
        }

        // Expect: warnings at iters 3, 4, 5 — threshold-crossing at 3 and persistence
        // at 4, 5.
        assert_eq!(
            warnings_fired_on,
            vec![3, 4, 5],
            "encoded schedule did not fire the warning on every iteration at or above threshold \
             (invariant #6)"
        );
        // Ring is capped at THRESHOLD; verify the 3 most recent summaries survive.
        assert_eq!(ring.len(), THRESHOLD);
        assert_eq!(
            ring.front().map(|s| s.as_str()),
            Some("iter 3: no decision recorded")
        );
        assert_eq!(
            ring.back().map(|s| s.as_str()),
            Some("iter 5: no decision recorded")
        );
    }

