    /// Mock LLM service for testing
    struct MockLlmService {
        responses: Mutex<Vec<String>>,
        last_response: Mutex<Option<String>>,
    }

    impl MockLlmService {
        fn new(responses: Vec<&str>) -> Self {
            Self {
                responses: Mutex::new(responses.into_iter().map(String::from).collect()),
                last_response: Mutex::new(None),
            }
        }
    }

    #[async_trait]
    impl LlmService for MockLlmService {
        async fn call_function(
            &self,
            _request: LlmFunctionCallRequest,
        ) -> Result<LlmFunctionCallResponse> {
            let mut responses = self.responses.lock().unwrap();
            let response = if responses.is_empty() {
                // When out of canned responses, repeat the last one consumed.
                // This keeps loop-detection tests looping and goal-reached tests stable.
                self.last_response
                    .lock()
                    .unwrap()
                    .clone()
                    .unwrap_or_else(|| {
                        r#"{"decision": "goal_reached", "artifacts": []}"#.to_string()
                    })
            } else {
                let r = responses.remove(0);
                *self.last_response.lock().unwrap() = Some(r.clone());
                r
            };
            Ok(LlmFunctionCallResponse {
                raw_arguments: response,
                telemetry: None,
            })
        }
    }

    fn test_task_state_action() -> serde_json::Value {
        serde_json::json!({
            "action": "none",
            "reason": "No durable task-state change needed for this unit test."
        })
    }

    fn attach_task_state_action(args: &mut serde_json::Map<String, serde_json::Value>) {
        args.entry("task_state_action".to_string())
            .or_insert_with(test_task_state_action);
    }

    fn native_response(
        tool_name: impl Into<String>,
        mut args: serde_json::Map<String, serde_json::Value>,
    ) -> ExecutionNativeResponse {
        attach_task_state_action(&mut args);
        let mut response = ExecutionNativeResponse::unadmitted(vec![ExecutionToolCall {
            id: format!("test-tool-call-{}", Uuid::new_v4()),
            name: tool_name.into(),
            arguments: serde_json::Value::Object(args),
        }]);
        response.finish_reason = Some("tool_calls".to_string());
        // A real provider response always carries its call receipt, and the
        // loop composes an effect id from that call id plus the model's
        // tool-call id. Without one the stateless arm refuses to dispatch
        // before firing -- correctly, since no restart could then prove whether
        // the call already happened. A fixture with no receipt was therefore
        // not a lighter version of a response, it was an undispatchable one.
        // Counts stay zero so nothing reads cost or tokens off a fixture.
        response.telemetry = Some(
            crate::magician_v2::slot_graph::extraction::LlmCallTelemetry {
                trace_receipt: Some(magicllm::LlmTraceReceipt::direct(
                    magicllm::LlmTraceContext::new(
                        magicllm::LlmScope::new(SCOPED_LOOP_PRINCIPAL, SCOPED_LOOP_WORKSPACE),
                        magicllm::LlmWorkloadClass::AutonomousTask,
                    ),
                )),
                ..Default::default()
            },
        );
        response
    }

    fn native_response_from_decision_fixture(raw: impl AsRef<str>) -> ExecutionNativeResponse {
        let value: serde_json::Value =
            serde_json::from_str(raw.as_ref()).expect("decision fixture must be valid JSON");
        let mut args = value
            .as_object()
            .expect("decision fixture must be an object")
            .clone();
        let decision = args
            .remove("decision")
            .and_then(|v| v.as_str().map(str::to_string))
            .expect("decision fixture must include decision");
        let tool_name = match decision.as_str() {
            "goal_reached" => "goal_reached".to_string(),
            "cannot_proceed" => "cannot_proceed".to_string(),
            "need_user_input" => "need_user_input".to_string(),
            "delegate_to_agent" => "delegate_to_agent".to_string(),
            "handover_to_agent" => "handover_to_agent".to_string(),
            "spawn_sub_goal" => "spawn_sub_goal".to_string(),
            "create_task" => "create_task".to_string(),
            "execute" => {
                let action_type = args
                    .remove("action_type")
                    .and_then(|v| v.as_str().map(str::to_string))
                    .expect("execute fixture must include action_type");
                if action_type == "tool" {
                    args.remove("capability_name")
                        .and_then(|v| v.as_str().map(str::to_string))
                        .expect("tool fixture must include capability_name")
                } else {
                    action_type
                }
            },
            other => panic!("unsupported decision fixture: {other}"),
        };
        native_response(tool_name, args)
    }

    fn attach_native_decision_fixtures<I, S>(
        executors: ActionExecutors,
        fixtures: I,
    ) -> ActionExecutors
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        let responses = fixtures
            .into_iter()
            .map(native_response_from_decision_fixture)
            .collect();
        executors.with_native_adapter(Arc::new(
            crate::magician_v2::execution::MultiLlmAgentAdapter::new_with_test_native_responses(
                responses,
            ),
        ))
    }

    fn test_executors_with_decision_fixtures<I, S>(fixtures: I) -> ActionExecutors
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        attach_native_decision_fixtures(
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager()),
            fixtures,
        )
    }

    /// A runtime for the delegation-decision tests below.
    ///
    /// [`build_execution_runtime`] deliberately keeps tokio's default 2MiB
    /// worker stack, because that is production's, and
    /// `production_scoped_tool_search_first_action_fits_default_execution_worker_stack`
    /// and `test_execute_agentically_flat_mode_dispatches_pack_then_succeeds`
    /// exist to assert the loop fits inside it. Those two keep that runtime.
    ///
    /// The tests using *this* one assert which decision a delegation reaches,
    /// not how deep its frames are, and an unoptimised build's frames are
    /// several times a release build's. Naming a larger stack here keeps a
    /// debug-profile stack ceiling from being reported as a delegation
    /// regression, and leaves the stack-fit claim to the two tests that make it
    /// on the real stack.
    fn delegation_decision_runtime() -> tokio::runtime::Runtime {
        tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .thread_name("magician-execution-worker")
            .thread_stack_size(16 * 1024 * 1024)
            .enable_all()
            .build()
            .expect("delegation decision runtime")
    }

    // A scope `build_test_artifact_v2_harness` already seals for the legacy
    // writer cutover, which the stateless driver requires before it will write
    // loop state under it.
    const SCOPED_LOOP_PRINCIPAL: &str = "test-principal";
    const SCOPED_LOOP_WORKSPACE: &str = "test-workspace";
    const SCOPED_LOOP_GENERATION: &str = "scoped-loop-generation";
    const SCOPED_LOOP_OWNER: &str = "scoped-loop-owner";

    /// The minimum durable control state a scoped run needs to start.
    ///
    /// The default `Stateless` arm reads cross-process control state at every
    /// phase boundary, and the trait's own defaults refuse rather than guess.
    /// These answers describe exactly the fixture below: one uninterrupted run,
    /// under one sealed generation, owned by one agent.
    #[derive(Debug)]
    struct ScopedLoopOwnershipRuntime {
        owner_agent_id: String,
        /// `apply_owner_execution_profile` replaces the context's roster
        /// wholesale with the profile's copy, so this has to equal what the
        /// caller put on the context or the run decides against a roster
        /// nobody set.
        delegation_targets:
            Vec<crate::magician_v2::execution::agentic::delegation_dispatch::DelegationTarget>,
        /// Direct tools the owner profile lists; the loop revalidates the
        /// run's tool scope against these, so a probe pack a test registers
        /// must appear here to survive to dispatch.
        direct_tools: Vec<runtime_core::ToolInfo>,
    }

    #[async_trait]
    impl crate::magician_v2::execution::agentic::ownership_runtime::OwnershipRuntime
        for ScopedLoopOwnershipRuntime
    {
        /// No external process shares this fixture's store, so there is no
        /// durable cancellation for a phase boundary to observe.
        async fn execution_is_durably_cancelled(
            &self,
            _execution_id: &str,
        ) -> Result<bool, String> {
            Ok(false)
        }

        async fn active_stateless_control_generation(
            &self,
            _execution_id: &str,
        ) -> Result<Option<String>, String> {
            Ok(Some(SCOPED_LOOP_GENERATION.to_owned()))
        }

        async fn stateless_control_generation(
            &self,
            _execution_id: &str,
        ) -> Result<Option<String>, String> {
            Ok(Some(SCOPED_LOOP_GENERATION.to_owned()))
        }

        /// Answering for any id would let a run that resolved the WRONG owner
        /// look like a run that resolved the right one.
        async fn load_owner_execution_profile(
            &self,
            agent_id: &str,
            principal: Option<&str>,
            workspace: Option<&str>,
        ) -> Result<
            crate::magician_v2::execution::agentic::ownership_runtime::OwnerExecutionProfile,
            String,
        > {
            if agent_id != self.owner_agent_id {
                return Err(format!(
                    "this fixture knows one owner ('{}'), and was asked for '{agent_id}'",
                    self.owner_agent_id
                ));
            }
            if principal != Some(SCOPED_LOOP_PRINCIPAL) || workspace != Some(SCOPED_LOOP_WORKSPACE)
            {
                return Err(format!(
                    "owner '{agent_id}' was resolved outside the fixture's scope: \
                     {principal:?}/{workspace:?}"
                ));
            }
            let definition = crate::magician_v2::agents::AgentDefinition::from_yaml_str(&format!(
                "agent_id: {owner}\n\
                 name: {owner}\n\
                 kind: worker\n\
                 description: Owner of a scoped loop-decision run.\n\
                 persona: Decides, and reports the terminal it reached.\n",
                owner = self.owner_agent_id
            ))
            .map_err(|error| format!("scoped loop owner definition must parse: {error}"))?;
            Ok(
                crate::magician_v2::execution::agentic::ownership_runtime::OwnerExecutionProfile {
                    agent_id: definition.agent_id.clone(),
                    trust_level: None,
                    trust_policies_path: None,
                    preloaded_trust_enforcer: None,
                    approval_rules: Vec::new(),
                    llm_model_override: None,
                    llm_routing_overrides: None,
                    prompt_identity: None,
                    delegation_targets: self.delegation_targets.clone(),
                    merged_agent_tools: self.direct_tools.clone(),
                    denied_capability_names: Vec::new(),
                    denied_tool_params: std::collections::HashMap::new(),
                    invocation_policy: definition.invocation_policy.clone(),
                    allowed_action_types: None,
                    max_delegation_depth: 3,
                    delegation_timeout_secs: 300,
                    tier_definitions: Vec::new(),
                    available_procedure_skills: Vec::new(),
                    definition,
                },
            )
        }

        async fn update_execution_owner_snapshot(
            &self,
            _thread_id: &str,
            _active_owner_agent_id: &str,
            _owner_stack: &[String],
        ) -> Result<(), String> {
            Ok(())
        }

        async fn validate_owner_transition(
            &self,
            _source_agent_id: &str,
            _target_agent_id: &str,
            _surface: crate::magician_v2::agents::InvocationSurface,
            _principal: Option<&str>,
            _workspace: Option<&str>,
        ) -> Result<(), String> {
            Ok(())
        }
    }

    /// One scoped run, composed for the production execution driver.
    ///
    /// `StatelessArm::new` refuses a run it cannot address durably -- it needs
    /// an execution id AND a principal AND a workspace, and returns an error
    /// rather than falling back to the resident loop when any is missing. The
    /// driver additionally refuses a scope whose legacy-writer cutover was
    /// never sealed, and the loop reads durable control state through an
    /// `OwnershipRuntime` at each phase boundary.
    /// `magician/tests/driver_phase_differential.rs` documents the same set as
    /// one constraint rather than four choices.
    ///
    /// The loop-decision tests that use this assert on what a run DECIDES, not
    /// on where its loop state lives, so composing the durable half once here
    /// keeps their bodies about the decision while still running them on the
    /// driver production uses.
    struct ScopedLoopRun {
        _root: tempfile::TempDir,
        executors: ActionExecutors,
        ctx: AgenticContext,
    }

    async fn scoped_loop_run<I, S>(goal: &str, success_criteria: &str, fixtures: I) -> ScopedLoopRun
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        scoped_loop_run_owned_by(
            goal,
            success_criteria,
            fixtures,
            SCOPED_LOOP_OWNER,
            Vec::new(),
        )
        .await
    }

    async fn scoped_loop_run_owned_by<I, S>(
        goal: &str,
        success_criteria: &str,
        fixtures: I,
        owner_agent_id: &str,
        delegation_targets: Vec<
            crate::magician_v2::execution::agentic::delegation_dispatch::DelegationTarget,
        >,
    ) -> ScopedLoopRun
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        scoped_loop_run_owned_by_with_direct_tools(
            goal,
            success_criteria,
            fixtures,
            owner_agent_id,
            delegation_targets,
            Vec::new(),
        )
        .await
    }

    async fn scoped_loop_run_owned_by_with_direct_tools<I, S>(
        goal: &str,
        success_criteria: &str,
        fixtures: I,
        owner_agent_id: &str,
        delegation_targets: Vec<
            crate::magician_v2::execution::agentic::delegation_dispatch::DelegationTarget,
        >,
        direct_tools: Vec<runtime_core::ToolInfo>,
    ) -> ScopedLoopRun
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        let root = tempfile::TempDir::new().expect("scoped loop root");
        let storage = root.path().join("storage");
        // A stateless terminal is projected under the Artifact/runtime owner's
        // lifecycle exclusion, so the run needs a real task and execution to
        // settle against -- not a shortcut past a missing owner.
        let (artifact_service, orchestrator) =
            crate::magician_v2::test_support::build_test_artifact_v2_harness(&storage);
        let (task, artifact_execution) = artifact_service
            .create_task_with_execution_shell(crate::magician_v2::artifact_v2::CreateTaskInput {
                principal: SCOPED_LOOP_PRINCIPAL.to_owned(),
                workspace: SCOPED_LOOP_WORKSPACE.to_owned(),
                title: goal.to_owned(),
                description: success_criteria.to_owned(),
                agent_id: owner_agent_id.to_owned(),
                goal_id: None,
                ui_thread_id: "scoped-loop-run".to_owned(),
                priority: None,
                due_date: None,
                tags: Vec::new(),
                created_by: "test".to_owned(),
                depends_on: Vec::new(),
                approved: true,
                schedule: None,
                output_mode: crate::magician_v2::artifact_v2::models::TaskOutputMode::Accumulate,
                chat_session_id: None,
                lifecycle: crate::magician_v2::artifact_v2::models::TaskLifecycle::default(),
                sync_mode: crate::magician_v2::artifact_v2::models::TaskSyncMode::default(),
            })
            .await
            .expect("create the run's Artifact task and execution shell");
        let task_id = task.manifest.task_id;
        let execution_id = artifact_execution.state.execution_id;
        let scope = crate::magician_v2::artifact_v2::ScopeRef::system_internal_unauthenticated(
            SCOPED_LOOP_PRINCIPAL,
            SCOPED_LOOP_WORKSPACE,
        );
        artifact_service
            .activate_execution(&scope, &task_id, &execution_id)
            .await
            .expect("activate the run's Artifact execution");
        orchestrator
            .create_execution_with_id(
                SCOPED_LOOP_PRINCIPAL,
                SCOPED_LOOP_WORKSPACE,
                Some(goal.to_owned()),
                owner_agent_id,
                &execution_id,
                Some(task_id.clone()),
                Some(execution_id.clone()),
            )
            .await
            .expect("register the run's runtime execution");

        let executors = test_executors_with_decision_fixtures(fixtures)
            .with_taskplan_base_path(storage.clone())
            .with_ownership_runtime(Arc::new(ScopedLoopOwnershipRuntime {
                owner_agent_id: owner_agent_id.to_owned(),
                delegation_targets: delegation_targets.clone(),
                direct_tools: direct_tools.clone(),
            }))
            .with_artifact_v2_service(artifact_service);
        crate::magician_v2::execution::agentic::run_loop::steer_inbox::activate_control_generation(
            &executors.artifact_v2_workspace,
            SCOPED_LOOP_PRINCIPAL,
            SCOPED_LOOP_WORKSPACE,
            &execution_id,
            SCOPED_LOOP_GENERATION,
        )
        .await
        .expect("activate the run's durable control generation");

        let mut ctx = AgenticContext::new(goal, success_criteria);
        ctx.principal = Some(SCOPED_LOOP_PRINCIPAL.to_string());
        ctx.workspace = Some(SCOPED_LOOP_WORKSPACE.to_string());
        // Deliberately NOT `ctx.task_id`. The Artifact task above exists so the
        // terminal has a real owner to settle under; naming it on the context
        // as well makes the run *task-backed*, and a task-backed run's
        // completion yield is refused without material evidence. The tests
        // using this assert which terminal a decision reaches, so they keep the
        // untasked shape they were written for.
        ctx.execution_id = Some(execution_id);
        // The terminal settle refuses an incomplete agent scope, and naming the
        // owner here commits the run to the scoped path: a full owner profile
        // is resolved before the first decision, which is what
        // `ScopedLoopOwnershipRuntime` answers for.
        ctx.agent_id = Some(owner_agent_id.to_string());
        ctx.delegation_targets = delegation_targets;
        ScopedLoopRun {
            _root: root,
            executors,
            ctx,
        }
    }

    fn test_prompt_manager() -> Arc<PromptManager> {
        let storage = JsonPromptStorage::with_default_config().unwrap();
        Arc::new(PromptManager::new(Arc::new(storage)))
    }

    #[test]
    fn action_executors_new_has_empty_sequence_recorder_slot() {
        // API Mining Phase 1: the recorder slot is always present but
        // starts empty. It's lazy-filled on first recorded action so
        // origin_key is captured from the actual workflow.
        let executors =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager());
        let slot = executors.api_mining_run.sequence_recorder.lock().unwrap();
        assert!(slot.is_none());
    }

    /// A runless plane grant's copy must not share the boot executors' scope
    /// slots (a plain clone would), must carry the scope's registry as its
    /// effective registry, must narrow it only when the allowlist is
    /// non-empty, and must seed the identity the flat compiled path reads.
    #[test]
    fn for_runless_scope_installs_the_scope_on_fresh_slots() {
        use crate::magician_v2::execution::capability::CapabilityRegistry;
        use crate::magician_v2::execution::compiled_providers::embedded_compiled_pack_defs;
        use crate::magician_v2::execution::flat_loop::ToolIndex;
        use crate::magician_v2::execution::ScopedCapabilitySnapshot;

        let registry = CapabilityRegistry::new();
        for pack in embedded_compiled_pack_defs()
            .into_iter()
            .filter(|pack| pack.name == "read_file" || pack.name == "update_task")
        {
            let name = pack.name.clone();
            registry.set_pack_definition(&name, pack);
        }
        assert_eq!(registry.all_pack_definitions().len(), 2);
        let snapshot = ScopedCapabilitySnapshot {
            revision: "rev-1".to_string(),
            overlay_revision: "overlay-1".to_string(),
            registry: Arc::new(registry),
            tool_index: Arc::new(ToolIndex::from_entries(Vec::new())),
            surface_tool_index: Arc::new(ToolIndex::from_entries(Vec::new())),
            pack_count: 2,
            built_at_ms: 0,
            app_origin_tool_installations: Arc::new(std::collections::BTreeMap::new()),
            loaded_skills: Arc::new(Default::default()),
            load_failures: Arc::new(Vec::new()),
        };
        let base =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager());
        assert!(base.effective_capability_registry_snapshot().is_none());
        let mut ctx = AgenticContext::default();
        ctx.principal = Some("owner".to_string());
        ctx.workspace = Some("home".to_string());
        ctx.agent_id = Some("personal-assistant".to_string());

        let unnarrowed = base.for_runless_scope(&ctx, &snapshot, &[]);
        assert!(!Arc::ptr_eq(
            &base.scope_capability_registry,
            &unnarrowed.scope_capability_registry
        ));
        assert!(!Arc::ptr_eq(
            &base.scope_app_origin_tool_installations,
            &unnarrowed.scope_app_origin_tool_installations
        ));
        assert!(!Arc::ptr_eq(
            &base.scoped_capability_registry,
            &unnarrowed.scoped_capability_registry
        ));
        assert!(!Arc::ptr_eq(&base.durable_store, &unnarrowed.durable_store));
        assert!(
            !Arc::ptr_eq(
                &base.grants.session_file_sandbox_roots,
                &unnarrowed.grants.session_file_sandbox_roots
            ),
            "a plane grant reads its own sandbox roots, not the boot instance's"
        );
        assert!(
            !Arc::ptr_eq(
                &base.grants.session_tool_allowlist,
                &unnarrowed.grants.session_tool_allowlist
            ),
            "a plane grant reads its own tool allowlist, not the boot instance's"
        );
        let effective = unnarrowed
            .effective_capability_registry_snapshot()
            .expect("the scope's registry is installed");
        assert!(
            Arc::ptr_eq(&effective, &snapshot.registry),
            "an empty allowlist installs the scope's registry unnarrowed"
        );
        assert!(
            base.effective_capability_registry_snapshot().is_none(),
            "the shared executors' slots stay untouched"
        );
        let identity = unnarrowed.run_identity.get();
        assert_eq!(identity.principal.as_deref(), Some("owner"));
        assert_eq!(identity.workspace.as_deref(), Some("home"));
        assert_eq!(identity.agent_id.as_deref(), Some("personal-assistant"));
        assert!(
            base.run_identity.get().principal.is_none(),
            "the grant's identity is not written through to the shared executors"
        );

        let narrowed = base.for_runless_scope(&ctx, &snapshot, &["read_file".to_string()]);
        let effective = narrowed
            .effective_capability_registry_snapshot()
            .expect("the narrowed registry is installed");
        assert!(!Arc::ptr_eq(&effective, &snapshot.registry));
        assert!(effective.get_pack_definition("read_file").is_some());
        assert!(effective.get_pack_definition("update_task").is_none());
        assert_eq!(
            snapshot.registry.all_pack_definitions().len(),
            2,
            "narrowing copies; the scope's registry is not edited in place"
        );
    }

    /// Plane allowlists name flat `<pack>__<action>` leaves. Narrowing by the
    /// leaf alone keeps the parent definition but drops the provider a
    /// provider-backed primitive pack dispatches through, so every such hand
    /// failed from a narrowed grant. The grant's copy must keep the parent
    /// provider of an allowlisted leaf, and only that parent. Dispatch looks
    /// the provider up by the pack's declared `provider_name`, so a pack whose
    /// declared name differs from its own must keep that provider too.
    #[test]
    fn for_runless_scope_keeps_the_parent_provider_of_an_allowlisted_leaf() {
        use crate::magician_v2::execution::capability::{
            CapabilityPackDefinition, CapabilityProvider, CapabilityRegistry,
        };
        use crate::magician_v2::execution::flat_loop::ToolIndex;
        use crate::magician_v2::execution::ScopedCapabilitySnapshot;

        #[derive(Debug)]
        struct NamedProvider(&'static str);

        #[async_trait]
        impl CapabilityProvider for NamedProvider {
            fn tool_name(&self) -> &str {
                self.0
            }

            fn lower(
                &self,
                _step: &crate::magician_v2::strategy::plan::PlanStep,
            ) -> std::result::Result<
                crate::magician_v2::resource_authority::gated_action::MaybeGatedAction,
                crate::magician_v2::execution::error::ExecutionError,
            > {
                Err(crate::magician_v2::execution::error::ExecutionError::Step(
                    "test provider does not lower".to_string(),
                ))
            }

            async fn execute(
                &self,
                _action: &ExecutableAction,
                _session_id: Option<String>,
                _timeout_secs: u64,
            ) -> std::result::Result<
                ActionResult,
                crate::magician_v2::execution::error::ExecutionError,
            > {
                Err(crate::magician_v2::execution::error::ExecutionError::Step(
                    "test provider does not execute".to_string(),
                ))
            }
        }

        let registry = CapabilityRegistry::new();
        for (pack_name, provider_name, action) in [
            ("rows", "rows", "preview"),
            ("sibling", "sibling", "read"),
            ("ledger", "ledger_engine", "tail"),
        ] {
            let definition: CapabilityPackDefinition = serde_yaml::from_str(&format!(
                "name: {pack_name}\n\
                 native_action_schemas:\n  {action}:\n    parameters: []\n\
                 implementation:\n  type: primitive\n  provider_name: {provider_name}\n"
            ))
            .expect("provider-backed primitive pack");
            registry.set_pack_definition(pack_name, definition);
            registry.register(Arc::new(NamedProvider(provider_name)));
        }
        assert!(registry.get("rows").is_some() && registry.get("sibling").is_some());
        assert!(
            registry.get("ledger_engine").is_some() && registry.get("ledger").is_none(),
            "the differing-name pack registers its provider under the declared name only"
        );

        assert_eq!(
            with_parent_packs_of_leaves(
                &[
                    "rows__preview".to_string(),
                    "rows__invented".to_string(),
                    "read_file".to_string(),
                    "rows__preview".to_string(),
                    "ledger__tail".to_string(),
                ],
                &registry,
            ),
            vec![
                "rows__preview".to_string(),
                "rows".to_string(),
                "rows__invented".to_string(),
                "read_file".to_string(),
                "ledger__tail".to_string(),
                "ledger".to_string(),
                "ledger_engine".to_string(),
            ],
            "a parent is added once, in allowlist order, only for an action it declares, \
             and its declared provider follows when the name differs"
        );

        let snapshot = ScopedCapabilitySnapshot {
            revision: "rev-1".to_string(),
            overlay_revision: "overlay-1".to_string(),
            registry: Arc::new(registry),
            tool_index: Arc::new(ToolIndex::from_entries(Vec::new())),
            surface_tool_index: Arc::new(ToolIndex::from_entries(Vec::new())),
            pack_count: 3,
            built_at_ms: 0,
            app_origin_tool_installations: Arc::new(std::collections::BTreeMap::new()),
            loaded_skills: Arc::new(Default::default()),
            load_failures: Arc::new(Vec::new()),
        };
        let base =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager());
        let mut ctx = AgenticContext::default();
        ctx.principal = Some("owner".to_string());
        ctx.workspace = Some("home".to_string());
        ctx.agent_id = Some("personal-assistant".to_string());

        let narrowed = base.for_runless_scope(&ctx, &snapshot, &["rows__preview".to_string()]);
        let effective = narrowed
            .effective_capability_registry_snapshot()
            .expect("the narrowed registry is installed");
        assert!(!Arc::ptr_eq(&effective, &snapshot.registry));
        assert!(
            effective.get("rows").is_some(),
            "the allowlisted leaf's parent provider survives narrowing"
        );
        assert!(effective.get_pack_definition("rows").is_some());
        assert!(
            effective.resolve_tool_definition("rows__preview").is_some(),
            "the leaf itself still resolves through its parent"
        );
        assert!(
            effective.get("sibling").is_none()
                && effective.get_pack_definition("sibling").is_none(),
            "a pack no allowlisted leaf belongs to is absent"
        );
        assert!(
            effective.get("ledger_engine").is_none()
                && effective.get_pack_definition("ledger").is_none(),
            "a differing-name provider is not kept for a grant that allowlists none of its leaves"
        );
        assert!(
            snapshot.registry.get("sibling").is_some(),
            "narrowing copies; the scope's registry is not edited in place"
        );

        let narrowed_to_ledger =
            base.for_runless_scope(&ctx, &snapshot, &["ledger__tail".to_string()]);
        let effective = narrowed_to_ledger
            .effective_capability_registry_snapshot()
            .expect("the narrowed registry is installed");
        assert!(
            effective.get("ledger_engine").is_some(),
            "the allowlisted leaf's declared provider survives narrowing under its own name"
        );
        assert!(effective.get_pack_definition("ledger").is_some());
        assert!(
            effective.resolve_tool_definition("ledger__tail").is_some(),
            "the leaf itself still resolves through its parent"
        );
        assert!(
            effective.get("rows").is_none() && effective.get("sibling").is_none(),
            "only the allowlisted leaf's provider is kept"
        );

        if let Ok(mut roots) = narrowed.grants.session_file_sandbox_roots.lock() {
            roots.insert("widened-for-this-grant".to_string());
        }
        assert!(
            base.grants
                .session_file_sandbox_roots
                .lock()
                .map(|roots| roots.is_empty())
                .unwrap_or(false),
            "a grant's sandbox widening never reaches the shared executors"
        );
    }

    #[test]
    fn drain_steer_is_fifo_one_shot_and_empty_without_queue() {
        // No queue wired → drain is empty. Steer is best-effort: a run with no
        // registered queue simply has nothing to inject.
        let bare =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager());
        assert!(bare.drain_steer().is_empty());

        // With a wired queue, a producer — exactly what `steer_execution` does
        // through the orchestrator's active control bundle, sharing the SAME
        // Arc — pushes messages; the executor drains them FIFO, exactly
        // once, then the queue is empty. This is the end-to-end steer contract
        // minus the thin orchestrator/HTTP wrapper.
        let queue = std::sync::Arc::new(std::sync::Mutex::new(Vec::<String>::new()));
        let executors =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager())
                .with_steer_queue(queue.clone());

        {
            let mut pending = queue.lock().unwrap();
            pending.push("do X not Y".to_string());
            pending.push("also check pricing".to_string());
        }

        assert_eq!(
            executors.drain_steer(),
            vec!["do X not Y".to_string(), "also check pricing".to_string()],
            "drain returns queued steers in FIFO order"
        );
        assert!(
            executors.drain_steer().is_empty(),
            "one-shot: a second drain yields nothing"
        );
    }

    #[test]
    fn completed_primitive_objective_is_recorded_and_retrievable() {
        use crate::magician_v2::execution::capability::ImplementationType;

        let executors =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager());
        executors.run_identity.update(|identity| {
            identity.primitive_goal = Some("execute every test case".to_string());
            identity.primitive_success_criteria = Some("all cases are marked Pass".to_string());
        });
        let seed = current_primitive_seed_goal_block(&executors);
        let objective_id =
            crate::magician_v2::execution::primitive_dispatch::primitive_objective_id(
                "browser", &seed,
            );
        let action = ExecutableAction::Pack {
            capability_name: "browser".to_string(),
            implementation: ImplementationType::Primitive {
                runtime_package: None,
                provider_name: None,
                intent_description: None,
                command: None,
                cwd: None,
                env: HashMap::new(),
                suffix_args: Vec::new(),
                timeout_secs: None,
                operation: None,
                prompt: None,
            },
            resolved_params: HashMap::new(),
        };
        let result = ActionResult::Browser {
            data: json!({
                "success": true,
                "summary": "All tests are Pass.",
                "terminal_decision": "goal_reached",
                "inner_iterations": 4,
                "inner_objective": {
                    "capability": "browser",
                    "id": objective_id,
                    "text": crate::magician_v2::execution::primitive_dispatch::primitive_objective_text(&seed)
                },
                "evidence_ledger": {
                    "terminal_evidence": "summary count shows all passed",
                    "final_url": "http://localhost:5173/tests/sota-tests/18-dual-range-slider.html"
                }
            }),
        };

        record_completed_primitive_objective(&executors, &action, &result, 7);
        let key = current_primitive_objective_for_action(&action, &executors).unwrap();
        let completed = completed_primitive_objective_for_key(&executors, &key).unwrap();
        let message = duplicate_completed_primitive_objective_message(&completed);

        assert_eq!(completed.capability_name, "browser");
        assert_eq!(completed.objective_id, key.objective_id);
        assert!(message.contains("skipped duplicate invocation"));
        assert!(message.contains("summary count shows all passed"));
        assert!(message.contains("choose a distinct remaining action"));
        assert!(message.contains("`yield`"));
        assert!(!message.contains("goal_reached"));
        assert!(!message.contains("cannot_proceed"));
    }

