    /// A refinement pass is the same run continued on a new segment. The first
    /// pass's committed terminal leaves a speculative-phase fence bound to its
    /// segment; the refinement segment's Prepare must find that fence handed
    /// to it, or every refinement under the stateless driver fails at Prepare
    /// with a binding mismatch — which is how three harness-driven delegations
    /// lost children that had done their work.
    #[tokio::test]
    async fn a_refinement_pass_inherits_the_first_pass_s_terminal_fence() {
        use crate::magician_v2::execution::agentic::run_loop::steer_inbox;
        let temp = tempfile::tempdir().expect("tempdir");
        let workspace = crate::magician_v2::artifact_v2::workspace::ArtifactV2Workspace::new(
            temp.path().join("workspace"),
        );
        steer_inbox::activate_control_generation(
            &workspace,
            "principal",
            "workspace",
            "execution-1",
            "controls-a",
        )
        .await
        .expect("control generation");
        // The first pass ran on the bare segment and admitted its terminal.
        steer_inbox::admit_terminal_boundary(
            &workspace,
            "principal",
            "workspace",
            "execution-1",
            "controls-a",
            "execution-1",
            9,
            None,
        )
        .await
        .expect("terminal seal");
        let executors =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager())
                .with_artifact_v2_workspace(workspace.clone());
        let mut original = AgenticContext::new("goal", "criteria");
        original.principal = Some("principal".to_string());
        original.workspace = Some("workspace".to_string());
        original.execution_id = Some("execution-1".to_string());
        let refined = build_refinement_context(&original, &[], &["marker".to_string()]);
        assert_eq!(refined.refinement_pass_index, 1);

        hand_terminal_fence_to_continuation_segment(&refined, &executors)
            .await
            .expect("the refinement segment takes over the fence");

        // The refinement segment counts from one; its first Prepare is
        // iteration 1, not the first pass's ninth.
        steer_inbox::reopen_after_nonterminal_boundary(
            &workspace,
            "principal",
            "workspace",
            "execution-1",
            "execution-1-p1",
            1,
        )
        .await
        .expect("the refinement segment's Prepare reopens the fence it inherited");
    }

    /// A run that pauses for a person admits a terminal boundary on the
    /// segment that paused, and the answer resumes it on a fresh `-r1`
    /// segment. That segment's Prepare must find the fence handed to it, or
    /// every answered question under the stateless driver fails at Prepare
    /// with a binding mismatch and the run parks on the same question again
    /// — which is what the plane door's first answered run did.
    #[tokio::test]
    async fn a_resumed_run_inherits_the_paused_segment_s_terminal_fence() {
        use crate::magician_v2::execution::agentic::run_loop::steer_inbox;
        let temp = tempfile::tempdir().expect("tempdir");
        let workspace = crate::magician_v2::artifact_v2::workspace::ArtifactV2Workspace::new(
            temp.path().join("workspace"),
        );
        steer_inbox::activate_control_generation(
            &workspace,
            "principal",
            "workspace",
            "execution-1",
            "controls-a",
        )
        .await
        .expect("control generation");
        // The run paused for a question at its third iteration on the bare
        // segment and admitted that boundary as terminal. Past the first
        // iteration is the common case: a question usually follows some work.
        steer_inbox::admit_terminal_boundary(
            &workspace,
            "principal",
            "workspace",
            "execution-1",
            "controls-a",
            "execution-1",
            3,
            None,
        )
        .await
        .expect("terminal seal");
        let executors =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager())
                .with_artifact_v2_workspace(workspace.clone());
        let mut resumed = AgenticContext::new("goal", "criteria");
        resumed.principal = Some("principal".to_string());
        resumed.workspace = Some("workspace".to_string());
        resumed.execution_id = Some("execution-1".to_string());
        resumed.iteration_offset = 3;
        assert_eq!(
            derived_loop_state_address(&resumed, "execution-1"),
            "execution-1-r3"
        );

        hand_terminal_fence_to_continuation_segment(&resumed, &executors)
            .await
            .expect("the resume segment takes over the fence");

        // The resume segment seeds its own loop state at iteration one, so
        // its first Prepare reopens the fence at iteration 1 — the paused
        // segment's numbering must not be held against it.
        steer_inbox::reopen_after_nonterminal_boundary(
            &workspace,
            "principal",
            "workspace",
            "execution-1",
            "execution-1-r3",
            1,
        )
        .await
        .expect("the resume segment's first Prepare reopens the fence it inherited");
    }

    /// A pause whose authorization hash differs between its in-memory state
    /// and its read-back state names the field that moved, so the envelope
    /// seal and the resume check can be reconciled on evidence.
    #[test]
    fn the_authorization_field_lost_in_a_round_trip_is_named() {
        let mut in_memory = AgenticPauseState::new(
            1,
            "goal",
            "criteria",
            EnvironmentState::Shell(ShellState::default()),
            "history",
            10,
            3,
        );
        in_memory.stateless_retry_due_at = Some(Utc::now());
        let mut read_back = in_memory.clone();
        read_back.stateless_retry_due_at = None;
        assert_eq!(
            authorization_field_lost_in_round_trip(&in_memory, &read_back),
            Some("stateless_retry_due_at")
        );
        assert_eq!(
            authorization_field_lost_in_round_trip(&in_memory, &in_memory),
            None
        );
    }

    /// The stage-time read-back parses a pause body near the bottom of the
    /// execution worker's chain, where a few hundred KiB of headroom is all
    /// that is left of its 2 MiB stack. Parsing there overflowed the worker
    /// and took the service down mid-pause; the parse must run on a stack of
    /// its own, so a caller with almost no stack left still gets its body back.
    /// The body nests as deep as the depth guard admits (its two enclosing
    /// containers included); a debug-build parse of that depth needs more
    /// than the caller's whole stack, so an inline parse aborts this test.
    #[test]
    fn the_pause_read_back_does_not_borrow_the_caller_s_stack() {
        const CALLER_STACK_BYTES: usize = 64 * 1024;
        const NESTING_DEPTH: usize =
            crate::magician_v2::json_traversal::MAX_RETAINED_JSON_DEPTH - 3;

        let mut deep = serde_json::json!(1);
        for _ in 0..NESTING_DEPTH {
            deep = serde_json::json!({ "k": deep });
        }
        let pause_state = test_pause_state();
        let expected_hash = pause_state.authorization_hash();
        let serializable = SerializablePauseData {
            principal: None,
            workspace: None,
            pause_state,
            input_type: UserInputType::Text {
                placeholder: None,
                multiline: false,
            },
            question: Some("Which word?".to_string()),
            hint: None,
            confirmation_action_json: None,
            secret_approval_challenge_id: None,
            secret_approval_request: None,
            pending_inputs: Vec::new(),
            resolved_inputs: HashMap::from([("deep".to_string(), deep.clone())]),
            asking_for_parameter: None,
            retry_count: 0,
            previous_answer: None,
            retry_reason: None,
            escalation_trigger: None,
            confirmation_action_summary: None,
            confirmation_reason: None,
            confirmation_action_type: None,
            pause_kind: None,
            harness_pause: None,
        };
        let temp = tempfile::tempdir().expect("tempdir");
        let body_path = temp.path().join("pause-body.json");
        serde_json::to_writer(
            std::fs::File::create(&body_path).expect("body file"),
            &serializable,
        )
        .expect("body written");

        let read_back = std::thread::Builder::new()
            .name("starved-caller".to_string())
            .stack_size(CALLER_STACK_BYTES)
            .spawn(move || read_back_pause_body(&body_path))
            .expect("caller thread")
            .join()
            .expect("the caller thread finished")
            .expect("the body read back");

        assert_eq!(read_back.pause_state.authorization_hash(), expected_hash);
        assert_eq!(read_back.resolved_inputs.get("deep"), Some(&deep));
    }

