    /// The notes beside an external action's "done" button are free text the
    /// model reads on every later decision, and the goal is persisted in the
    /// pause record. A code typed there is withheld with a marker instead.
    #[test]
    fn a_code_typed_into_the_notes_never_reaches_the_goal() {
        let done = |guidance: &str| {
            UserInputResponse::new(
                UserInputType::ExternalAction {
                    instructions: "Approve it on your phone".to_string(),
                    done_label: None,
                },
                UserInputValue::ExternalActionCompleted {
                    guidance: Some(guidance.to_string()),
                },
            )
        };
        let leak = build_resumed_goal(
            "Sign in",
            "done",
            &done("the verification code is 482913"),
            "history",
            2,
            10,
            false,
        );
        assert!(!leak.contains("482913"), "{leak}");
        assert!(
            leak.contains("need_user_input"),
            "the model is told how to ask: {leak}"
        );
        // Ordinary advice is untouched.
        let advice = build_resumed_goal(
            "Sign in",
            "done",
            &done("I approved it on the phone; the banner is gone now"),
            "history",
            2,
            10,
            false,
        );
        assert!(advice.contains("I approved it on the phone"), "{advice}");
    }

    #[test]
    fn resumed_goal_skips_prior_actions_summary_when_conversation_restored() {
        let response = UserInputResponse::new(
            UserInputType::Text {
                placeholder: None,
                multiline: false,
            },
            UserInputValue::Text {
                value: "proceed".to_string(),
            },
        );

        let goal = build_resumed_goal(
            "Base goal",
            "proceed",
            &response,
            "Opened the fixture and attempted the action",
            3,
            12,
            true,
        );
        assert!(goal.contains("[User provided input: proceed]"));
        assert!(!goal.contains("Prior actions in this execution"));
        assert!(goal.contains("resumed at iteration 3/12"));

        let fallback = build_resumed_goal(
            "Base goal",
            "proceed",
            &response,
            "Opened the fixture and attempted the action",
            3,
            12,
            false,
        );
        assert!(fallback.contains("Prior actions in this execution"));
        assert!(fallback.contains("Opened the fixture and attempted the action"));
    }

