    #[test]
    fn delegation_resume_hydration_is_nondestructive_and_retirement_is_revision_bound() {
        let source = include_str!("executor.rs");
        let load = source
            .split("fn load_verified_delegation_from_disk_scoped")
            .nth(1)
            .and_then(|tail| {
                tail.split("pub(crate) async fn load_verified_delegation_on_execution_runtime")
                    .next()
            })
            .expect("verified delegation load source");
        assert!(load.contains("load_versioned_pause_body"));
        assert!(load.contains("ExecutionPauseKind::Delegation"));
        assert!(!load.contains("remove_pause_record_and_bodies"));
        assert!(!load.contains("remove_from_disk"));

        let retire = source
            .split("pub(crate) fn retire_verified_delegation_checkpoint")
            .nth(1)
            .and_then(|tail| tail.split("/// Take pause data for an execution").next())
            .expect("verified delegation retirement source");
        for authority in [
            "authority.revision",
            "authority.body_sha256",
            "authority.execution_id",
        ] {
            assert!(
                retire.contains(authority),
                "missing exact authority {authority}"
            );
        }
        let verify = retire
            .find("envelope.revision != authority.revision")
            .expect("revision revalidation");
        let remove = retire
            .find("remove_pause_record_and_bodies")
            .expect("exact durable retirement");
        assert!(verify < remove);
        // A same-execution successor parks exactly the segment this source
        // resumes as — the next delegation round's checkpoint or the resumed
        // parent's own user pause; that replacement retires the source and
        // keeps the envelope. Every other replacement is still refused, and
        // the superseding check runs before the refusal.
        let superseded = retire
            .find("envelope.pending.stateless_parked_segment == authority.resume_segment")
            .expect("successor supersession check");
        let refused = retire
            .find("delegation checkpoint was replaced before exact retirement")
            .expect("foreign replacement refusal");
        assert!(superseded < refused && refused < remove);
        let superseding_arm = &retire[superseded..refused];
        assert!(superseding_arm.contains("return Ok(())"));
        assert!(!superseding_arm.contains("remove_persisted_pending"));
        let same_execution = retire
            .find("let same_execution = ")
            .expect("supersession is keyed on the execution, not the pause kind");
        assert!(same_execution < superseded);
        assert!(!retire[same_execution..superseded].contains("ExecutionPauseKind::Delegation"));

        // And the successor's terminal may be stored over the retained source
        // in the first place: the StatelessTerminalPreparation precondition
        // retires a same-execution Delegation envelope whose resume segment is
        // the incoming pause's parked segment before it would refuse to
        // overwrite public authority.
        let store = source
            .split("PauseStorePrecondition::StatelessTerminalPreparation => {")
            .nth(1)
            .and_then(|tail| {
                tail.split("PauseStorePrecondition::ManualResumeExact {")
                    .next()
            })
            .expect("stateless terminal preparation precondition");
        let supersedes = store
            .find("let supersedes_delegation_source = ")
            .expect("delegation source supersession in the store precondition");
        let refuse_public = store
            .find("stateless terminal preparation refuses to overwrite public pause authority")
            .expect("public authority refusal");
        assert!(supersedes < refuse_public);
        let supersession = &store[supersedes..refuse_public];
        assert!(supersession.contains("existing.pending.stateless_resume_segment.as_deref()"));
        assert!(supersession.contains("pause_data.pause_state.stateless_parked_segment.as_deref()"));
        assert!(supersession.contains("remove_pause_record_and_bodies"));
    }

    #[test]
    fn terminal_delegation_cleanup_is_exact_and_consumes_protected_authority_first() {
        let source = include_str!("executor.rs");
        let retire = source
            .split("fn retire_terminal_delegation_checkpoint_scoped")
            .nth(1)
            .and_then(|tail| {
                tail.split(
                    "pub(crate) async fn retire_terminal_delegation_checkpoint_on_execution_runtime",
                )
                .next()
            })
            .expect("terminal delegation retirement source");
        for binding in [
            "envelope.pending.pause_kind != Some(ExecutionPauseKind::Delegation)",
            "envelope.pending.principal.as_deref() != Some(principal)",
            "envelope.pending.workspace.as_deref() != Some(workspace)",
            "envelope.pending.task_id.as_deref() != Some(task_id)",
            "envelope.pending.execution_id != execution_id",
            "serializable.pause_state.storage_key() == key",
        ] {
            assert!(retire.contains(binding), "missing exact binding: {binding}");
        }
        let verified_body = retire
            .find("load_versioned_pause_body_with_claim_recovery")
            .expect("bounded integrity-verified body read");
        let typed_foreign_claim = retire
            .find("ProtectedDelegationClaimAlreadyOwned")
            .expect("live foreign claim deferral");
        let consumed = retire
            .find("AppWorkflowControlLifecycle::Consumed")
            .expect("monotonic protected consume");
        let unlink = retire
            .rfind("remove_pause_record_and_bodies")
            .expect("exact envelope/body unlink");
        assert!(verified_body < typed_foreign_claim);
        assert!(typed_foreign_claim < consumed && consumed < unlink);
        assert!(!retire.contains("remove_for_execution"));
        assert!(!retire.contains("clear_pending_pauses_for_execution"));
    }

    #[test]
    fn protected_delegation_live_claim_is_verified_then_returned_as_typed_deferral() {
        let source = include_str!("executor.rs");
        let load = source
            .split("fn load_verified_delegation_from_disk_scoped")
            .nth(1)
            .and_then(|tail| {
                tail.split("pub(crate) async fn load_verified_delegation_on_execution_runtime")
                    .next()
            })
            .expect("verified delegation load source");
        let body = load
            .find("load_versioned_pause_body_with_claim_recovery")
            .expect("integrity-verifying bounded body load");
        let immutable_binding = load
            .find("delegation body does not match the claimed exact execution")
            .expect("exact execution binding check");
        let registry = load
            .find("current_workflow_control_sync")
            .expect("durable protected claim classification");
        let typed = load
            .find("ProtectedDelegationClaimAlreadyOwned")
            .expect("typed live-claim deferral");
        let claim = load
            .find("claim_recoverable_protected_serializable_pause")
            .expect("expired/Active exact claim acquisition");
        assert!(body < immutable_binding && immutable_binding < registry);
        assert!(registry < typed && typed < claim);
        let normalized_load = load.split_whitespace().collect::<Vec<_>>().join(" ");
        assert!(normalized_load.contains("&path, &envelope, false, true"));
    }

    #[test]
    fn verified_delegation_successor_seeds_or_exact_adopts_before_phase_entry() {
        let source = include_str!("executor.rs");
        let resume = source
            .split("fn delegation_resume_segment")
            .nth(1)
            .and_then(|tail| tail.split("const AGENTIC_ITERATION_CEILING").next())
            .expect("delegation successor selector source");
        assert!(resume.contains("park_resume_address"));
        assert!(
            !resume.contains("LoopStateStore::load"),
            "successor existence must be decided by the INITIAL CAS, not a TOCTOU preflight"
        );

        let exact_resume = source
            .split("async fn execute_agentically_resume_exact_inner")
            .nth(1)
            .and_then(|tail| {
                tail.split("pub async fn exact_pause_admission_failure")
                    .next()
            })
            .expect("exact resume source");
        let segment = exact_resume
            .find("enhanced_ctx.stateless_resume_source_segment = Some(segment)")
            .expect("declared exact successor installed");
        let permission = exact_resume
            .find("enhanced_ctx.stateless_resume_may_seed_declared_successor = true")
            .expect("verified delegation seed permission installed");
        assert!(segment < permission);

        let seed = source
            .split("async fn seed_declared_successor_before_restore")
            .nth(1)
            .and_then(|tail| tail.split("/// Commit the run's first `LoopState`").next())
            .expect("declared successor seed source");
        let initial_cas = seed
            .find("Revision::INITIAL")
            .expect("atomic initial successor commit");
        let conflict = seed
            .find("StoreError::Conflict")
            .expect("concurrent seed conflict adoption");
        let reload = seed
            .rfind("self.store.load(&self.key)")
            .expect("CAS loser reloads committed winner");
        assert!(initial_cas < conflict && conflict < reload);

        let drive = source
            .split("let mut resume_iteration = 1;")
            .nth(1)
            .and_then(|tail| tail.split("for iteration in resume_iteration").next())
            .expect("exact restoration seam");
        let seed_before_restore = drive
            .find("seed_declared_successor_before_restore")
            .expect("declared successor admitted before restore");
        let restore = drive
            .find("restore_exact_continuation_if_needed")
            .expect("exact winner continuation restored");
        assert!(seed_before_restore < restore);
    }

    #[test]
    fn delegation_foreign_owner_never_becomes_a_sleeping_workflow_outcome() {
        let source = include_str!("executor.rs");
        let advance = source
            .split("async fn advance_iteration_inner")
            .nth(1)
            .and_then(|tail| tail.split("impl InProcessWorkerHost").next())
            .expect("stateless advance source");
        for variant in ["Advanced::LeaseHeld", "Advanced::NotClaimable"] {
            let branch = advance
                .split(variant)
                .nth(1)
                .expect("foreign ownership branch");
            let typed_error = branch
                .find("DelegationSuccessorAlreadyOwned")
                .expect("delegation ownership surfaces a recognizable deferral");
            let sleeping = branch
                .find("AgenticOutcome::Sleeping")
                .expect("non-delegation exact retry retains sleeping behavior");
            assert!(
                typed_error < sleeping,
                "verified Delegation must escape before generic Sleeping projection"
            );
        }
    }

    #[tokio::test]
    async fn relationship_agent_exclusion_dedupes_colliding_process_stripes() {
        let mut first_by_stripe = HashMap::<usize, String>::new();
        let (first, second) = (0usize..10_000)
            .find_map(|index| {
                let agent_id = format!("relationship-agent-{index}");
                let digest =
                    stateless_agent_lifecycle_digest("principal-a", "workspace-a", &agent_id);
                let stripe = usize::from(digest[0]) % STATELESS_AGENT_LIFECYCLE_LOCK_STRIPES;
                first_by_stripe
                    .insert(stripe, agent_id.clone())
                    .map(|first| (first, agent_id))
            })
            .expect("bounded search should find two IDs sharing one process stripe");
        let tmp = tempfile::TempDir::new().unwrap();
        let store = FullPauseStore::with_persistence(tmp.path());
        let exclusion = tokio::time::timeout(
            Duration::from_secs(1),
            store.acquire_stateless_agent_lifecycle_exclusions_scoped(
                "principal-a",
                "workspace-a",
                &[second, first],
            ),
        )
        .await
        .expect("colliding agent IDs must not self-deadlock")
        .expect("relationship exclusion should succeed");
        drop(exclusion);
    }

