        let tmp = tempfile::TempDir::new().unwrap();
        let (key, due_at, envelope_path, mut envelope) =
            persisted_placement_retry_fixture(tmp.path());
        let body_path = envelope_path.with_file_name(&envelope.body_file);
        let mut body = std::fs::read(&body_path).unwrap();
