    #[test]
    fn pause_store_persists_long_keys_with_bounded_hashed_filename() {
        let tmp = tempfile::TempDir::new().unwrap();
        let store = FullPauseStore::with_persistence(tmp.path());
        let long_context = "Morning engineering standup P0 implementation ".repeat(20);
        let pause_state = test_pause_state()
            .with_agent_routing(
                "senior-software-developer",
                format!("[{long_context}][coding-flow]"),
                format!("senior-software-developer::{long_context}::1782890349697"),
            )
            .with_scope("principal-a", "workspace-a");
        let key = pause_state.storage_key();
        let hashed_filename = FullPauseStore::pause_filename_for_key(&key);
        let legacy_filename = FullPauseStore::legacy_encoded_pause_filename(&key);

        assert!(
            legacy_filename.len() > 255,
            "fixture should reproduce the old too-long filename shape"
        );
        assert!(
            hashed_filename.len() < 80,
            "hashed pause filename should stay comfortably below filesystem component limits"
        );

        let stored_key = store.store(test_full_pause_data(pause_state));
        assert_eq!(stored_key, key);
        assert!(tmp.path().join(&hashed_filename).exists());
        assert!(!tmp.path().join(&legacy_filename).exists());

        let restart_store = FullPauseStore::with_persistence(tmp.path());
        let recovered = restart_store
            .take_serializable_by_key_from_disk(&key)
            .unwrap()
            .expect("long-key pause should recover from the hashed filename");
        assert_eq!(recovered.pause_state.storage_key(), key);
        assert!(!tmp.path().join(&hashed_filename).exists());
    }

