    #[test]
    fn rolling_store_refuses_stale_cached_body_and_projects_canonical_replacement() {
        let tmp = tempfile::TempDir::new().unwrap();
        let stale = FullPauseStore::with_persistence(tmp.path());
        let peer = FullPauseStore::with_persistence(tmp.path());
        let initial = test_pause_state()
            .with_agent_routing("rolling-agent", "rolling-goal", "rolling-cycle")
            .with_scope("principal-a", "workspace-a");
        let execution_id = initial.execution_id.clone().unwrap();
        let key = initial.storage_key();
        stale
            .store_durable(test_manual_full_pause_data(initial.clone()))
            .unwrap();

        let mut replacement = initial;
        replacement.iteration = 9;
        peer.store_durable(test_manual_full_pause_data(replacement))
            .unwrap();

        let pending = stale.get_pending_for_execution(&execution_id);
        assert_eq!(pending.len(), 1);
        assert_eq!(pending[0].iteration, 9);
        let error = match stale.take_durable(&key) {
            Err(error) => error,
            Ok(_) => panic!("a rolling process must not consume a peer's replacement revision"),
        };
        assert!(error.to_string().contains("durable revision was replaced"));
        assert!(
            tmp.path()
                .join(FullPauseStore::pause_filename_for_key(&key))
                .exists(),
            "stale cache rejection must retain the peer's canonical pause"
        );
    }

