    #[test]
    fn post_rename_directory_sync_retry_adopts_exact_revision_and_preserves_prior_records() {
        let tmp = tempfile::TempDir::new().unwrap();
        let store = FullPauseStore::with_persistence(tmp.path());
        let pause_state = test_pause_state()
            .with_agent_routing("fsync-agent", "fsync-goal", "fsync-cycle")
            .with_scope("principal-a", "workspace-a");
        let key = pause_state.storage_key();
        store
            .store_durable(test_full_pause_data(pause_state.clone()))
            .expect("initial pause revision should persist");
        let envelope_path = tmp
            .path()
            .join(FullPauseStore::pause_filename_for_key(&key));
        let old_envelope = FullPauseStore::read_pause_envelope(&envelope_path)
            .expect("initial envelope should be readable");
        let old_body_path = envelope_path.with_file_name(&old_envelope.body_file);
        let legacy_path = tmp
            .path()
            .join(FullPauseStore::legacy_encoded_pause_filename(&key));
        std::fs::copy(&old_body_path, &legacy_path)
            .expect("prior exact pause body should form a valid legacy recovery record");

        FAIL_PAUSE_ENVELOPE_PARENT_SYNC.with(|fail| fail.set(true));

        let mut current_pause_state = pause_state;
        current_pause_state.iteration = 9;
        store
            .store_durable(test_full_pause_data(current_pause_state))
            .expect("exact envelope re-read plus parent fsync should reconcile uncertainty");

        let envelope = FullPauseStore::read_pause_envelope(&envelope_path)
            .expect("the renamed envelope is preserved after a directory sync error");
        assert!(envelope_path.with_file_name(&envelope.body_file).exists());
        assert_ne!(envelope.body_file, old_envelope.body_file);
        assert!(
            old_body_path.exists(),
            "an uncertain directory sync may roll the envelope back, so its prior body must \
             survive"
        );
        assert!(
            legacy_path.exists(),
            "legacy recovery authority must not be retired until the v2 envelope directory entry \
             is durable"
        );
        assert!(store.contains(&key));
        assert!(
            store.memory_pause_authority.contains_key(&key),
            "only the exact re-read and re-synced revision becomes cached authority"
        );

        let recovered = FullPauseStore::with_persistence(tmp.path())
            .take_serializable_by_key_from_disk(&key)
            .expect("same-scope v2 plus legacy recovery authority remains readable after restart")
            .expect("the preserved pair contains the pause");
        assert_eq!(
            recovered.pause_state.agent_id.as_deref(),
            Some("fsync-agent")
        );
        assert_eq!(
            recovered.pause_state.iteration, 9,
            "the valid current v2 revision must win over the preserved prior legacy record"
        );
        assert!(!envelope_path.exists());
        assert!(!legacy_path.exists());
        assert!(!old_body_path.exists());
    }

    #[test]
    fn same_key_store_commits_are_serialized_through_cleanup() {
        let _serial = PAUSE_MUTATION_TEST_SERIAL
            .get_or_init(|| StdMutex::new(()))
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let tmp = tempfile::TempDir::new().unwrap();
        let store = Arc::new(FullPauseStore::with_persistence(tmp.path()));
        let first = test_pause_state()
            .with_agent_routing("serialized-agent", "serialized-goal", "serialized-cycle")
            .with_scope("principal-a", "workspace-a");
        let key = first.storage_key();
        let hook = Arc::new(PauseMutationTestHook::new(key.clone(), tmp.path()));
        *PAUSE_MUTATION_TEST_HOOK
            .get_or_init(|| StdMutex::new(None))
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Arc::clone(&hook));

        let first_store = Arc::clone(&store);
        let first_thread = std::thread::spawn(move || {
            let mut first = first;
            first.iteration = 1;
            first_store.store_durable(test_full_pause_data(first))
        });
        hook.wait_until(|state| state.persist_gate_reached && state.acquisitions == 1);

        let second_store = Arc::clone(&store);
        let second_thread = std::thread::spawn(move || {
            let mut second = test_pause_state()
                .with_agent_routing("serialized-agent", "serialized-goal", "serialized-cycle")
                .with_scope("principal-a", "workspace-a");
            second.iteration = 2;
            second_store.store_durable(test_full_pause_data(second))
        });
        hook.wait_until(|state| state.attempts == 2);
        {
            let state = hook
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            assert_eq!(
                state.acquisitions, 1,
                "the replacement cannot enter mid-commit"
            );
        }
        hook.release();
        first_thread.join().unwrap().unwrap();
        second_thread.join().unwrap().unwrap();
        *PAUSE_MUTATION_TEST_HOOK
            .get()
            .unwrap()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;

        let recovered = FullPauseStore::with_persistence(tmp.path())
            .take_serializable_by_key_from_disk(&key)
            .unwrap()
            .unwrap();
        assert_eq!(recovered.pause_state.iteration, 2);
    }

    #[test]
    fn same_key_take_waits_for_the_replacement_commit() {
        let _serial = PAUSE_MUTATION_TEST_SERIAL
            .get_or_init(|| StdMutex::new(()))
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let tmp = tempfile::TempDir::new().unwrap();
        let store = Arc::new(FullPauseStore::with_persistence(tmp.path()));
        let original = test_pause_state()
            .with_agent_routing("take-agent", "take-goal", "take-cycle")
            .with_scope("principal-a", "workspace-a");
        let key = original.storage_key();
        store.store_durable(test_full_pause_data(original)).unwrap();

        let hook = Arc::new(PauseMutationTestHook::new(key.clone(), tmp.path()));
        *PAUSE_MUTATION_TEST_HOOK
            .get_or_init(|| StdMutex::new(None))
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Arc::clone(&hook));
        let replacing_store = Arc::clone(&store);
        let replacing = std::thread::spawn(move || {
            let mut replacement = test_pause_state()
                .with_agent_routing("take-agent", "take-goal", "take-cycle")
                .with_scope("principal-a", "workspace-a");
            replacement.iteration = 7;
            replacing_store.store_durable(test_full_pause_data(replacement))
        });
        hook.wait_until(|state| state.persist_gate_reached && state.acquisitions == 1);

        let taking_store = Arc::clone(&store);
        let taking_key = key.clone();
        let taking = std::thread::spawn(move || taking_store.take(&taking_key));
        hook.wait_until(|state| state.attempts == 2);
        {
            let state = hook
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            assert_eq!(
                state.acquisitions, 1,
                "take cannot revoke a partial replacement"
            );
        }
        hook.release();
        replacing.join().unwrap().unwrap();
        let taken = taking
            .join()
            .unwrap()
            .expect("replacement must be consumed");
        assert_eq!(taken.pause_state.iteration, 7);
        *PAUSE_MUTATION_TEST_HOOK
            .get()
            .unwrap()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;
        assert!(FullPauseStore::with_persistence(tmp.path())
            .take_serializable_by_key_from_disk(&key)
            .unwrap()
            .is_none());
    }

    #[test]
    fn execution_cleanup_waits_for_an_inflight_replacement_commit() {
        let _serial = PAUSE_MUTATION_TEST_SERIAL
            .get_or_init(|| StdMutex::new(()))
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let tmp = tempfile::TempDir::new().unwrap();
        let store = Arc::new(FullPauseStore::with_persistence(tmp.path()));
        let original = test_pause_state()
            .with_agent_routing("cleanup-agent", "cleanup-goal", "cleanup-cycle")
            .with_scope("principal-a", "workspace-a");
        let execution_id = original.execution_id.clone().unwrap();
        let key = original.storage_key();
        store.store_durable(test_full_pause_data(original)).unwrap();

        let hook = Arc::new(PauseMutationTestHook::new(key.clone(), tmp.path()));
        *PAUSE_MUTATION_TEST_HOOK
            .get_or_init(|| StdMutex::new(None))
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = Some(Arc::clone(&hook));
        let replacing_store = Arc::clone(&store);
        let replacing = std::thread::spawn(move || {
            let mut replacement = test_pause_state()
                .with_agent_routing("cleanup-agent", "cleanup-goal", "cleanup-cycle")
                .with_scope("principal-a", "workspace-a");
            replacement.iteration = 11;
            replacing_store.store_durable(test_full_pause_data(replacement))
        });
        hook.wait_until(|state| state.persist_gate_reached && state.acquisitions == 1);

        let cleaning_store = Arc::clone(&store);
        let cleaning =
            std::thread::spawn(move || cleaning_store.remove_for_execution(&execution_id));
        hook.wait_until(|state| state.attempts == 2);
        {
            let state = hook
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            assert_eq!(
                state.acquisitions, 1,
                "cleanup cannot observe a partial commit"
            );
        }
        hook.release();
        replacing.join().unwrap().unwrap();
        assert!(cleaning.join().unwrap() >= 1);
        *PAUSE_MUTATION_TEST_HOOK
            .get()
            .unwrap()
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner) = None;
        assert!(!store.contains(&key));
        assert!(FullPauseStore::with_persistence(tmp.path())
            .take_serializable_by_key_from_disk(&key)
            .unwrap()
            .is_none());
    }

