    #[test]
    fn pending_hitl_resolution_metadata_survives_restart() {
        let tmp = tempfile::TempDir::new().unwrap();
        let writer = FullPauseStore::with_persistence(tmp.path());
        let pause_state = test_pause_state()
            .with_agent_routing("agent-a", "goal-a", "cycle-a")
            .with_scope("principal-a", "workspace-a")
            .with_task_execution_context(
                Some("task-a".to_string()),
                Some("execution-a".to_string()),
                None,
            );
        // The resolution names the ask, exactly as this pause's
        // `HitlRequested` did — not the bare storage key, which the step's
        // next question reuses.
        let correlation_id = pause_state.hitl_correlation_id();
        assert!(correlation_id.starts_with(&pause_state.storage_key()));
        assert_ne!(correlation_id, pause_state.storage_key());
        writer
            .store_durable(test_full_pause_data(pause_state))
            .expect("pause should persist before restart");

        let restart_store = FullPauseStore::with_persistence(tmp.path());
        let resolutions = restart_store.pending_hitl_resolutions_for_execution("execution-a");

        assert_eq!(resolutions.len(), 1);
        let resolution = &resolutions[0];
        assert_eq!(resolution.correlation_id, correlation_id);
        assert_eq!(resolution.source, "agentic");
        assert_eq!(resolution.task_id.as_deref(), Some("task-a"));
        assert_eq!(resolution.execution_id.as_deref(), Some("execution-a"));
        assert_eq!(resolution.agent_id.as_deref(), Some("agent-a"));
        assert_eq!(resolution.principal.as_deref(), Some("principal-a"));
        assert_eq!(resolution.workspace.as_deref(), Some("workspace-a"));
    }

