    #[test]
    fn terminal_pause_cleanup_removes_exact_ordinary_unverifiable_body() {
        let tmp = tempfile::TempDir::new().unwrap();
        let store = FullPauseStore::with_persistence(tmp.path());
        let pause_state = test_pause_state()
            .with_agent_routing("agent-cleanup", "goal-cleanup", "cycle-cleanup")
            .with_scope("principal-a", "workspace-a");
        let execution_id = pause_state.execution_id.clone().unwrap();
        let key = store.store(test_full_pause_data(pause_state));
        let persisted_path = tmp
            .path()
            .join(FullPauseStore::pause_filename_for_key(&key));

        // Ordinary pauses are owned by the exact in-memory execution index, so
        // a corrupt persisted body must not strand either copy indefinitely.
        std::fs::write(&persisted_path, "not a serialized pause").unwrap();
        assert!(store.load_pause_file(&persisted_path).is_err());

        assert_eq!(store.remove_for_execution(&execution_id), 2);
        assert!(!persisted_path.exists());
        assert!(!store.contains(&key));
    }

    #[test]
    fn protected_terminal_cleanup_verifies_body_and_local_claim_before_registry_cas() {
        let source = include_str!("executor.rs");
        let cleanup = source
            .split("fn consume_protected_pause_envelope_for_cleanup")
            .nth(1)
            .and_then(|tail| tail.split("fn remove_execution_pause_path").next())
            .expect("protected terminal cleanup source");
        let verified_body = cleanup
            .find("load_versioned_pause_body_with_claim_recovery")
            .expect("exact versioned body verification");
        let ordinary_fast_path = cleanup
            .find("if !body_is_protected && !carries_protected_authority")
            .expect("ordinary cleanup classification");
        let local_claim = cleanup
            .find("protected pause cleanup found a conflicting local claim generation")
            .expect("local protected-claim identity validation");
        let registry_cas = cleanup
            .find("transition_workflow_pause_sync")
            .expect("irreversible registry transition");
        assert!(verified_body < ordinary_fast_path);
        assert!(local_claim < registry_cas);
        let active_claim = cleanup
            .find("AppWorkflowControlLifecycle::Active")
            .expect("protected cleanup Active classification");
        let claimed = cleanup[active_claim..]
            .find("AppWorkflowControlLifecycle::Claimed")
            .map(|offset| active_claim + offset)
            .expect("bounded cleanup claim");
        let consumed = cleanup[claimed..]
            .find("AppWorkflowControlLifecycle::Consumed")
            .map(|offset| claimed + offset)
            .expect("monotonic terminal consume");
        assert!(active_claim < claimed && claimed < consumed);
        assert!(cleanup.contains("current.claim_ref() != Some(&claim.claim_ref)"));

        let unlink = source
            .split("fn remove_execution_pause_path")
            .nth(1)
            .and_then(|tail| tail.split("fn remove_pause_record_and_bodies").next())
            .expect("pause unlink source");
        let identity = unlink
            .find("persisted_execution_id.as_deref() != Some(execution_id)")
            .expect("exact execution identity validation");
        let protected_consume = unlink
            .find("consume_protected_pause_envelope_for_cleanup")
            .expect("protected registry consumption");
        let remove = unlink.find("remove_file(path)").expect("envelope unlink");
        assert!(identity < protected_consume && protected_consume < remove);

        let checked = source
            .split("pub(crate) fn remove_for_execution_checked")
            .nth(1)
            .and_then(|tail| {
                tail.split("fn consume_protected_pause_envelope_for_cleanup")
                    .next()
            })
            .expect("checked execution cleanup");
        assert!(checked.contains("cleanup_incomplete"));
        assert!(checked.contains("could not be proven retired"));
    }

