    #[test]
    fn pause_store_rejects_an_exact_key_duplicated_across_scope_directories() {
        let tmp = tempfile::TempDir::new().unwrap();
        let writer = FullPauseStore::with_scoped_v3_persistence_root(tmp.path());
        let first = test_pause_state()
            .with_agent_routing("shared-agent", "shared-goal", "shared-cycle")
            .with_scope("principal-a", "workspace-a");
        let key = first.storage_key();
        writer.store(test_full_pause_data(first));
        let second = test_pause_state()
            .with_agent_routing("shared-agent", "shared-goal", "shared-cycle")
            .with_scope("principal-b", "workspace-b");
        writer.store(test_full_pause_data(second));

        let restart = FullPauseStore::with_scoped_v3_persistence_root(tmp.path());
        let error = restart
            .take_serializable_by_key_from_disk(&key)
            .expect_err("an unscoped key lookup must not choose between tenant directories");
        assert!(error
            .to_string()
            .contains("ambiguous across multiple scope"));
        assert_eq!(
            restart
                .pause_file_paths_for_key(restart.persistence_target.as_ref().unwrap(), &key,)
                .unwrap()
                .len(),
            2
        );

        let consumed = writer
            .take(&key)
            .expect("the in-memory value remains bound to its own embedded scope");
        assert_eq!(
            consumed.pause_state.principal.as_deref(),
            Some("principal-b")
        );
        let survivor = FullPauseStore::with_scoped_v3_persistence_root(tmp.path())
            .take_serializable_by_key_from_disk(&key)
            .expect("consuming one scoped in-memory pause must leave the other tenant readable")
            .expect("the first tenant pause should survive");
        assert_eq!(survivor.principal.as_deref(), Some("principal-a"));
    }

