    #[test]
    fn pause_encoded_node_admission_is_exact_for_wide_arrays_and_strings_on_small_stack() {
        let tmp = tempfile::TempDir::new().unwrap();
        let path = tmp.path().join("node-admission.json");
        let path_for_thread = path.clone();
        std::thread::Builder::new()
            .name("pause-node-admission".to_string())
            .stack_size(512 * 1024)
            .spawn(move || {
                let wide_string = "x".repeat(1024 * 1024);
                std::fs::write(
                    &path_for_thread,
                    serde_json::to_vec(&serde_json::json!([wide_string])).unwrap(),
                )
                .unwrap();
                let admitted: Value = FullPauseStore::read_guarded_pause_json(
                    &path_for_thread,
                    MAX_PAUSE_BODY_BYTES,
                    2,
                )
                .expect("array plus one wide string is exactly two nodes");
                assert!(admitted.as_array().is_some_and(|values| values.len() == 1));
                assert!(FullPauseStore::read_guarded_pause_json::<Value>(
                    &path_for_thread,
                    MAX_PAUSE_BODY_BYTES,
                    1,
                )
                .unwrap_err()
                .to_string()
                .contains("node limit"));
                drop(admitted);

                let wide_array = format!("[{}]", vec!["0"; 20_000].join(","));
                std::fs::write(&path_for_thread, wide_array).unwrap();
                let exact: Value = FullPauseStore::read_guarded_pause_json(
                    &path_for_thread,
                    MAX_PAUSE_BODY_BYTES,
                    20_001,
                )
                .expect("container and every scalar fit the exact node boundary");
                assert_eq!(exact.as_array().map(Vec::len), Some(20_000));
                drop(exact);
                assert!(FullPauseStore::read_guarded_pause_json::<Value>(
                    &path_for_thread,
                    MAX_PAUSE_BODY_BYTES,
                    20_000,
                )
                .unwrap_err()
                .to_string()
                .contains("node limit"));
            })
            .unwrap()
            .join()
            .expect("raw pause node admission fits a small execution stack");
    }

