            let envelope_path = tmp
                .path()
                .join(FullPauseStore::pause_filename_for_key(&key));
            let envelope = FullPauseStore::read_pause_envelope(&envelope_path).unwrap();
            body_paths.push(envelope_path.with_file_name(envelope.body_file));
