    #[test]
    fn versioned_pause_bodies_fail_closed_when_missing_corrupt_swapped_or_oversized() {
        fn persisted_fixture(
            root: &std::path::Path,
            suffix: &str,
        ) -> (String, std::path::PathBuf, PauseEnvelope) {
            let store = FullPauseStore::with_persistence(root);
            let mut pause_state = test_pause_state()
                .with_agent_routing(
                    format!("agent-{suffix}"),
                    format!("goal-{suffix}"),
                    format!("cycle-{suffix}"),
                )
                .with_scope("principal-a", "workspace-a");
            pause_state.execution_id = Some(format!("execution-{suffix}"));
            let key = store.store(test_full_pause_data(pause_state));
            let envelope_path = root.join(FullPauseStore::pause_filename_for_key(&key));
            let envelope = FullPauseStore::read_pause_envelope(&envelope_path).unwrap();
            (key, envelope_path, envelope)
        }

        let missing = tempfile::TempDir::new().unwrap();
        let (missing_key, missing_envelope, missing_record) =
            persisted_fixture(missing.path(), "missing");
        std::fs::remove_file(missing_envelope.with_file_name(missing_record.body_file)).unwrap();
        assert!(FullPauseStore::with_persistence(missing.path())
            .take_serializable_by_key_from_disk(&missing_key)
            .is_err());

        let corrupt = tempfile::TempDir::new().unwrap();
        let (corrupt_key, corrupt_envelope, corrupt_record) =
            persisted_fixture(corrupt.path(), "corrupt");
        std::fs::write(
            corrupt_envelope.with_file_name(corrupt_record.body_file),
            "same-ish bytes but wrong hash",
        )
        .unwrap();
        assert!(FullPauseStore::with_persistence(corrupt.path())
            .take_serializable_by_key_from_disk(&corrupt_key)
            .is_err());

        let swapped = tempfile::TempDir::new().unwrap();
        let (left_key, left_envelope, left_record) = persisted_fixture(swapped.path(), "left");
        let (_, right_envelope, right_record) = persisted_fixture(swapped.path(), "right");
        std::fs::copy(
            right_envelope.with_file_name(right_record.body_file),
            left_envelope.with_file_name(left_record.body_file),
        )
        .unwrap();
        assert!(FullPauseStore::with_persistence(swapped.path())
            .take_serializable_by_key_from_disk(&left_key)
            .is_err());

        let oversized = tempfile::TempDir::new().unwrap();
        let (oversized_key, oversized_envelope, mut oversized_record) =
            persisted_fixture(oversized.path(), "oversized");
        oversized_record.body_size = MAX_PAUSE_BODY_BYTES + 1;
        std::fs::write(
            &oversized_envelope,
            serde_json::to_vec(&oversized_record).unwrap(),
        )
        .unwrap();
        assert!(FullPauseStore::with_persistence(oversized.path())
            .take_serializable_by_key_from_disk(&oversized_key)
            .is_err());
    }

