    #[test]
    fn protected_app_pause_seal_survives_restart_and_binds_every_identity_and_byte() {
        let tmp = tempfile::TempDir::new().unwrap();
        let first_layout =
            crate::magician_v2::artifact_v2::workspace::ArtifactV2Workspace::new(tmp.path());
        let exact = br#"{"goal":"private-value","history":["tool-result"]}"#;
        let seal = seal_app_pause_continuation(
            &first_layout,
            "principal-a",
            "workspace-a",
            "task_app_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
            "exec-a",
            "pause-a",
            exact,
        )
        .unwrap();

        // A new workspace owner reloads the same restricted scope key, proving
        // this is durable restart authority rather than a boot-local seal.
        let restarted_layout =
            crate::magician_v2::artifact_v2::workspace::ArtifactV2Workspace::new(tmp.path());
        verify_app_pause_continuation_seal(
            &restarted_layout,
            "principal-a",
            "workspace-a",
            "task_app_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
            "exec-a",
            "pause-a",
            exact,
            &seal,
        )
        .unwrap();

        let mut modified = exact.to_vec();
        modified.extend_from_slice(b" ");
        assert!(verify_app_pause_continuation_seal(
            &restarted_layout,
            "principal-a",
            "workspace-a",
            "task_app_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
            "exec-a",
            "pause-a",
            &modified,
            &seal,
        )
        .is_err());
        assert!(verify_app_pause_continuation_seal(
            &restarted_layout,
            "principal-b",
            "workspace-a",
            "task_app_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
            "exec-a",
            "pause-a",
            exact,
            &seal,
        )
        .is_err());
        assert!(verify_app_pause_continuation_seal(
            &restarted_layout,
            "principal-a",
            "workspace-a",
            "task_app_bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb",
            "exec-a",
            "pause-a",
            exact,
            &seal,
        )
        .is_err());
    }

    #[test]
    fn every_reconnect_and_confirmation_envelope_field_is_bound_to_the_hashed_body() {
        for tamper_case in 0..5 {
            let tmp = tempfile::TempDir::new().unwrap();
            let writer = FullPauseStore::with_persistence(tmp.path());
            let mut pause = test_full_pause_data(
                test_pause_state()
                    .with_agent_routing("metadata-agent", "metadata-goal", "metadata-cycle")
                    .with_scope("principal-a", "workspace-a"),
            );
            pause.question = Some("Original question".to_string());
            pause.hint = Some("Original hint".to_string());
            pause.retry_count = 2;
            pause.previous_answer = Some("Original answer".to_string());
            pause.retry_reason = Some("Original retry reason".to_string());
            pause.confirmation_action_json = Some(r#"{"action":"original"}"#.to_string());
            let key = writer.store(pause);
            let envelope_path = tmp
                .path()
                .join(FullPauseStore::pause_filename_for_key(&key));
            let mut envelope = FullPauseStore::read_pause_envelope(&envelope_path).unwrap();
            match tamper_case {
                0 => envelope.pending.question = Some("Forged question".to_string()),
                1 => envelope.pending.hint = Some("Forged hint".to_string()),
                2 => envelope.pending.retry_count = 99,
                3 => envelope.pending.previous_answer = Some("Forged answer".to_string()),
                4 => envelope.confirmation_action_json = Some(r#"{"action":"forged"}"#.to_string()),
                _ => unreachable!(),
            }
            std::fs::write(&envelope_path, serde_json::to_vec(&envelope).unwrap()).unwrap();

            assert!(FullPauseStore::with_persistence(tmp.path())
                .take_serializable_by_key_from_disk(&key)
                .is_err());
            assert!(envelope_path.exists());
        }
    }

