    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn legacy_monolithic_pause_remains_readable_and_index_migration_is_idempotent() {
        let tmp = tempfile::TempDir::new().unwrap();
        let writer = FullPauseStore::with_persistence(tmp.path());
        let pause_state = test_pause_state()
            .with_agent_routing("legacy-agent", "legacy-goal", "legacy-cycle")
            .with_scope("principal-a", "workspace-a");
        let key = writer.store(test_full_pause_data(pause_state));
        let envelope_path = tmp
            .path()
            .join(FullPauseStore::pause_filename_for_key(&key));
        let serializable = writer.load_pause_file(&envelope_path).unwrap();
        let envelope = FullPauseStore::read_pause_envelope(&envelope_path).unwrap();
        std::fs::remove_file(envelope_path.with_file_name(envelope.body_file)).unwrap();
        std::fs::write(
            &envelope_path,
            serde_json::to_vec_pretty(&serializable).unwrap(),
        )
        .unwrap();

        let restart = Arc::new(FullPauseStore::with_persistence(tmp.path()));
        assert!(restart.load_pending_index_from_disk().unwrap().is_empty());
        assert_eq!(
            restart
                .repair_legacy_pending_index_on_execution_runtime()
                .await
                .unwrap(),
            1
        );
        let pending = restart.get_pending_for_execution("thread-pause");
        assert_eq!(pending.len(), 1);
        assert_eq!(pending[0].key, key);
        assert!(restart.load_pending_index_from_disk().unwrap().is_empty());
        assert_eq!(
            restart
                .repair_legacy_pending_index_on_execution_runtime()
                .await
                .unwrap(),
            0,
            "legacy discovery is consumed exactly once per restart"
        );
        assert_eq!(restart.get_pending_for_execution("thread-pause").len(), 1);
        let recovered = restart
            .take_serializable_by_key_from_disk_on_execution_runtime(&key)
            .await
            .unwrap()
            .expect("legacy body recovers exactly once");
        assert_eq!(
            recovered.pause_state.agent_id.as_deref(),
            Some("legacy-agent")
        );
        assert!(!envelope_path.exists());
    }

