    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn background_legacy_repair_drains_beyond_one_batch_without_false_absence() {
        let tmp = tempfile::TempDir::new().unwrap();
        let writer = FullPauseStore::with_persistence(tmp.path());
        for index in 0..(MAX_LEGACY_PAUSE_REPAIRS_PER_BATCH + 1) {
            let mut pause_state = test_pause_state()
                .with_agent_routing(
                    format!("legacy-agent-{index}"),
                    format!("legacy-goal-{index}"),
                    format!("legacy-cycle-{index}"),
                )
                .with_scope("principal-a", "workspace-a");
            pause_state.execution_id = Some(format!("legacy-execution-{index}"));
            let key = writer.store(test_full_pause_data(pause_state));
            let envelope_path = tmp
                .path()
                .join(FullPauseStore::pause_filename_for_key(&key));
            let serializable = writer.load_pause_file(&envelope_path).unwrap();
            let envelope = FullPauseStore::read_pause_envelope(&envelope_path).unwrap();
            std::fs::remove_file(envelope_path.with_file_name(envelope.body_file)).unwrap();
            std::fs::write(&envelope_path, serde_json::to_vec(&serializable).unwrap()).unwrap();
        }

        let restart = Arc::new(FullPauseStore::with_persistence(tmp.path()));
        assert!(restart.load_pending_index_from_disk().unwrap().is_empty());
        assert!(restart.legacy_pending_index_repair_in_progress());
        assert_eq!(
            restart
                .repair_legacy_pending_index_on_execution_runtime()
                .await
                .unwrap(),
            MAX_LEGACY_PAUSE_REPAIRS_PER_BATCH
        );
        assert!(
            restart.legacy_pending_index_repair_in_progress(),
            "one remaining legacy record must keep execution-only lookup retryable"
        );

        let repair = restart
            .schedule_legacy_pending_index_background_repair()
            .expect("remaining repair schedules");
        repair.await.expect("background repair joins");
        assert!(!restart.legacy_pending_index_repair_in_progress());
        for index in 0..(MAX_LEGACY_PAUSE_REPAIRS_PER_BATCH + 1) {
            assert_eq!(
                restart
                    .get_pending_for_execution(&format!("legacy-execution-{index}"))
                    .len(),
                1
            );
        }
    }

