    #[tokio::test]
    async fn task_execution_updates_apply_only_to_active_root_execution() {
        let tmp = tempfile::TempDir::new().unwrap();
        let v3_service = build_test_artifact_v2_service(tmp.path());
        let (task, execution) = v3_service
            .create_task_with_execution_shell(crate::magician_v2::artifact_v2::CreateTaskInput {
                principal: "principal".to_string(),
                workspace: "workspace".to_string(),
                title: "Task root".to_string(),
                description: "Task root".to_string(),
                agent_id: "personal-assistant".to_string(),
                goal_id: None,
                ui_thread_id: "general".to_string(),
                priority: None,
                due_date: None,
                tags: Vec::new(),
                created_by: "user".to_string(),
                depends_on: Vec::new(),
                approved: true,
                schedule: None,
                output_mode: crate::magician_v2::artifact_v2::models::TaskOutputMode::Accumulate,
                chat_session_id: None,
                lifecycle: crate::magician_v2::artifact_v2::models::TaskLifecycle::default(),
                sync_mode: crate::magician_v2::artifact_v2::models::TaskSyncMode::default(),
            })
            .await
            .expect("task created");
        let scope = crate::magician_v2::artifact_v2::ScopeRef::system_internal_unauthenticated(
            &"principal".to_string(),
            &"workspace".to_string(),
        );
        v3_service
            .activate_execution(
                &scope,
                &task.manifest.task_id,
                &execution.state.execution_id,
            )
            .await
            .expect("root execution activated");

        let executors =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager())
                .with_artifact_v2_service(v3_service.clone());

        let mut root_ctx = AgenticContext::new("Task root goal", "Task root complete")
            .with_observability(&execution.state.execution_id, "plan-root", "step-root");
        root_ctx.task_id = Some(task.manifest.task_id.clone());
        root_ctx.execution_id = Some(execution.state.execution_id.clone());

        assert!(
            task_execution_updates_apply_to_root(&executors, &root_ctx, &task.manifest.task_id)
                .await,
            "active root execution should be allowed to persist task state"
        );

        let mut child_ctx = AgenticContext::new("Child goal", "Child complete").with_observability(
            "exec-child",
            "plan-child",
            "step-child",
        );
        child_ctx.task_id = Some(task.manifest.task_id.clone());
        child_ctx.execution_id = Some("exec-child".to_string());

        assert!(
            !task_execution_updates_apply_to_root(&executors, &child_ctx, &task.manifest.task_id,)
                .await,
            "delegated child execution must not overwrite root task state"
        );
    }

    #[tokio::test]
    async fn tool_authorization_user_request_service_returns_allow_always() {
        let broadcaster = Arc::new(RuntimeTransportBroadcaster::new(32));
        let user_request_service = Arc::new(UserRequestService::new(Arc::clone(&broadcaster)));
        let executors =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager())
                .with_user_request_service(Arc::clone(&user_request_service));
        let ctx = scoped_execution_context();

        let service_clone = Arc::clone(&user_request_service);
        let responder = tokio::spawn(async move {
            tokio::time::sleep(tokio::time::Duration::from_millis(50)).await;
            let pending = service_clone.list_pending().await;
            assert_eq!(pending.len(), 1);
            assert_eq!(pending[0].request_type, "tool_authorization");
            assert_eq!(pending[0].execution_id.as_deref(), Some("exec-1"));
            assert!(
                service_clone
                    .respond_scoped(
                        crate::magician_v2::user_requests::UserResponse {
                            request_id: pending[0].id.clone(),
                            decision: "allow_always".to_string(),
                            input: None,
                            channel: "web".to_string(),
                            sensitive: Vec::new(),
                        },
                        Some("principal-a"),
                        Some("workspace-a"),
                    )
                    .await
                    == crate::magician_v2::user_requests::ScopedResponseResult::Accepted
            );
        });

        let decision = ask_tool_authorization_via_user_request_service(
            &ctx,
            &executors,
            "browser:execute",
            "url=https://example.com",
            "Allow browser:execute?",
        )
        .await;

        responder.await.unwrap();
        assert_eq!(decision, Some(UserRequestEscalationDecision::AllowAlways));
    }

