    #[tokio::test]
    async fn merge_prior_delegation_result_artifacts_preserves_child_outputs() {
        let tempdir = tempfile::tempdir().expect("tempdir");
        let storage =
            build_screenshot_storage_with_registered_execution(&tempdir, "thread-delegated").await;
        storage
            .store_execution_summary(&AgenticExecutionSummaryRecord {
                execution_id: "thread-delegated".to_string(),
                loop_mode: None,
                plan_id: "plan-delegated".to_string(),
                step_id: "step-delegated".to_string(),
                outcome: DELEGATION_RESULTS_READY_OUTCOME.to_string(),
                iterations_used: 1,
                artifacts: vec![
                    "inline:result.json|application/json|{\"verified_title\":\"Dhurandhar 2\"}"
                        .to_string(),
                    "durable:research/monthly-report.md".to_string(),
                ],
                duration_ms: 0,
                summary: "Delegated child completed".to_string(),
                timestamp: Utc::now().timestamp_millis(),
                loop_detection_type: None,
                loop_repeated_action: None,
                loop_recommendation: None,
                loop_cycle_pattern: None,
                loop_similarity: None,
                budget_dimension: None,
                budget_details: None,
                cannot_proceed_reason: None,
                yield_payload: None,
                child_deliverables: Vec::new(),
            })
            .await
            .expect("summary should persist");

        let executors =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager())
                .with_screenshot_storage(storage);
        let ctx = AgenticContext::new("Parent goal", "Success").with_observability(
            "thread-delegated",
            "plan-parent",
            "step-parent",
        );

        let mut artifacts = vec![
            "inline:parent.txt|text/plain|done".to_string(),
            "durable:research/monthly-report.md".to_string(),
        ];
        merge_prior_delegation_result_artifacts(&ctx, &executors, &mut artifacts).await;

        assert!(
            artifacts
                .iter()
                .any(|artifact| artifact.contains("result.json")),
            "delegated inline result should be carried into the final parent artifact set"
        );
        assert_eq!(
            artifacts
                .iter()
                .filter(|artifact| artifact.as_str() == "durable:research/monthly-report.md")
                .count(),
            1,
            "existing durable artifacts should not be duplicated"
        );
        assert!(
            artifacts
                .iter()
                .any(|artifact| artifact.contains("parent.txt")),
            "parent artifacts should be preserved when delegated artifacts are merged"
        );
    }

