    fn provision_http_bearer_secret(
        store: &SecretStore,
        secret_id: &str,
        domain: &str,
        requires_approval: bool,
    ) {
        store
            .store_provisioned(
                secret_id,
                "HTTP bearer",
                HashMap::from([("token".to_string(), "super-secret-token".to_string())]),
                InjectionTarget::Header {
                    name: "Authorization".to_string(),
                    prefix: Some("Bearer ".to_string()),
                },
                SecretPolicy {
                    allowed_tools: vec!["http:post".to_string()],
                    allowed_domains: vec![domain.to_string()],
                    requires_approval,
                    ..Default::default()
                },
            )
            .expect("secret should be stored");
    }

    #[test]
    fn stateless_lifecycle_file_locks_revalidate_the_published_inode() {
        let source = include_str!("executor.rs");
        let agent = source
            .split("fn acquire_agent_lifecycle_file_lock_sync_with_timeout")
            .nth(1)
            .and_then(|tail| tail.split("fn try_acquire_pause_file_lock_sync").next())
            .expect("agent lifecycle file-lock helper");
        assert!(agent.contains("validate_locked_file_path_identity"));

        let pause = source
            .split("fn acquire_pause_file_lock_sync_with_timeout")
            .nth(1)
            .and_then(|tail| tail.split("fn cached_pause_envelope_locked").next())
            .expect("pause lifecycle file-lock helper");
        assert!(pause.contains("validate_locked_file_path_identity"));
    }

    #[test]
    fn load_trust_dispatch_guard_uses_preloaded_enforcer_without_reparse() {
        let enforcer = Arc::new(
            TrustPolicyEnforcer::from_yaml_str(
                r#"
trust_policies:
  - level: local
    allow:
      - tool: browser
        action: [observe]
"#,
            )
            .expect("trust policy should parse"),
        );

        let missing_path = std::env::temp_dir().join(format!(
            "missing-trust-policy-{}.yaml",
            uuid::Uuid::new_v4()
        ));
        let ctx = AgenticContext::new("goal", "criteria")
            .with_trust_policy("local", &missing_path)
            .with_preloaded_trust_enforcer(Arc::clone(&enforcer));

        let guard = load_trust_dispatch_guard(&ctx)
            .expect("preloaded enforcer should bypass file parse")
            .expect("trust guard should be available");

        assert!(Arc::ptr_eq(&guard.enforcer, &enforcer));
        assert!(guard
            .enforcer
            .is_allowed(&guard.level, "browser", "observe"));
    }

