    #[test]
    fn active_history_shares_authoritative_large_action_result_until_rewrite() {
        let authoritative = Arc::new(ActionResult::Browser {
            data: json!({"rows": vec!["x".repeat(1024); 8_192]}),
        });

        let unchanged = shared_action_result_for_history(&authoritative, None);
        assert!(Arc::ptr_eq(&authoritative, &unchanged));

        let rewritten = shared_action_result_for_history(
            &authoritative,
            Some(ActionResult::text("bounded rewritten locator")),
        );
        assert!(!Arc::ptr_eq(&authoritative, &rewritten));
        assert!(matches!(
            rewritten.as_ref(),
            ActionResult::Text { content } if content == "bounded rewritten locator"
        ));
        assert_eq!(Arc::strong_count(&authoritative), 2);
    }

    #[test]
    fn collect_tool_output_file_paths_ignores_input_files_and_tracks_explicit_outputs() {
        let temp_dir = tempfile::tempdir().expect("temp dir");
        let input_path = temp_dir.path().join("input.txt");
        let output_path = temp_dir.path().join("output.jpg");
        let exported_path = temp_dir.path().join("exported.csv");
        std::fs::write(&input_path, "input").expect("write input");
        std::fs::write(&output_path, "output").expect("write output");
        std::fs::write(&exported_path, "export").expect("write export");

        let payload = json!({
            "input_file": input_path.to_string_lossy(),
            "images": [
                {
                    "path": output_path.to_string_lossy(),
                    "size_bytes": 6
                }
            ],
            "export_path": exported_path.to_string_lossy()
        });
        let mut seen = HashSet::new();
        let mut paths = Vec::new();

        collect_tool_output_file_paths(&payload, false, &mut seen, &mut paths);

        let actual = paths.into_iter().collect::<HashSet<_>>();
        let expected = HashSet::from([
            output_path.to_string_lossy().to_string(),
            exported_path.to_string_lossy().to_string(),
        ]);
        assert_eq!(actual, expected);
    }

