    #[test]
    fn rewrite_tool_output_file_paths_matches_trimmed_whitespace_values() {
        let payload = json!({
            "images": [
                {
                    "path": "  /tmp/generated.png  ",
                    "size_bytes": 10
                }
            ]
        });
        let rewrites = HashMap::from([(
            "/tmp/generated.png".to_string(),
            "/persisted/generated.png".to_string(),
        )]);

        let payload = rewrite_tool_output_file_paths(payload, false, &rewrites)
            .expect("bounded payload rewrites");

        let rewritten_path = payload
            .get("images")
            .and_then(Value::as_array)
            .and_then(|items| items.first())
            .and_then(|item| item.get("path"))
            .and_then(Value::as_str)
            .expect("rewritten path");
        assert_eq!(rewritten_path, "/persisted/generated.png");
    }

    #[test]
    fn tool_output_artifact_walk_rejects_deep_values_without_recursive_drop() {
        std::thread::Builder::new()
            .name("tool-output-artifact-small-stack".to_string())
            .stack_size(256 * 1024)
            .spawn(|| {
                let mut payload = Value::String("leaf".to_string());
                for _ in 0..10_000 {
                    payload = Value::Array(vec![payload]);
                }
                assert!(rewrite_tool_output_file_paths(payload, false, &HashMap::new()).is_none());

                let raw = format!(
                    "{}\"leaf\"{}",
                    "[".repeat(MAX_RETAINED_JSON_DEPTH + 1),
                    "]".repeat(MAX_RETAINED_JSON_DEPTH + 1)
                );
                assert!(parse_admitted_tool_output_json(&raw).is_none());
            })
            .expect("spawn tool-output artifact regression")
            .join()
            .expect("tool-output artifact regression completes");
    }

    #[test]
    fn tool_output_json_rejects_one_over_the_raw_node_ceiling_before_retention() {
        // The array itself is one node. Add exactly the configured number of
        // scalar children so the encoded document is one node over the
        // retained ceiling. This exercises the pre-Serde scanner used by raw
        // and wrapped compiled-tool output capture.
        let mut raw = String::with_capacity(
            MAX_CAPTURE_TOOL_OUTPUT_JSON_NODES
                .saturating_mul(5)
                .saturating_add(2),
        );
        raw.push('[');
        for index in 0..MAX_CAPTURE_TOOL_OUTPUT_JSON_NODES {
            if index > 0 {
                raw.push(',');
            }
            raw.push_str("null");
        }
        raw.push(']');

        assert!(parse_admitted_tool_output_json(&raw).is_none());
    }

    #[test]
    fn collect_tool_output_file_paths_counts_but_does_not_retain_past_cap() {
        let temp_dir = tempfile::tempdir().expect("temp dir");
        let mut outputs = Vec::new();
        for index in 0..(MAX_CAPTURED_TOOL_OUTPUT_FILES_PER_ACTION + 3) {
            let path = temp_dir.path().join(format!("output-{index}.txt"));
            std::fs::write(&path, format!("output {index}")).expect("write output");
            outputs.push(json!({"path": path.to_string_lossy()}));
        }
        let payload = json!({"outputs": outputs});
        let mut seen = HashSet::new();
        let mut paths = Vec::new();

        let discovered = collect_tool_output_file_paths(&payload, false, &mut seen, &mut paths);

        assert_eq!(discovered, MAX_CAPTURED_TOOL_OUTPUT_FILES_PER_ACTION + 3);
        assert_eq!(paths.len(), MAX_CAPTURED_TOOL_OUTPUT_FILES_PER_ACTION);
    }

