    #[tokio::test]
    async fn capture_pack_action_artifacts_keeps_execution_copies_unique_per_invocation() {
        let temp_dir = tempfile::tempdir().expect("temp dir");
        let first_source = temp_dir.path().join("generated-1.txt");
        let second_source = temp_dir.path().join("generated-2.txt");
        std::fs::write(&first_source, "first output").expect("write first source");
        std::fs::write(&second_source, "second output").expect("write second source");

        let action = ExecutableAction::Pack {
            capability_name: "image_generator".to_string(),
            implementation:
                crate::magician_v2::execution::capability::ImplementationType::Compiled {
                    provider_name: "image_generator".to_string(),
                },
            resolved_params: HashMap::new(),
        };
        let executors =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager())
                .with_taskplan_base_path(temp_dir.path().join("storage"));
        let mut ctx = AgenticContext::new("goal", "criteria");
        ctx.principal = Some("principal-a".to_string());
        ctx.workspace = Some("workspace-a".to_string());
        ctx.task_id = Some("task-1".to_string());
        ctx.execution_id = Some("exec-1".to_string());

        let make_result =
            |path: &std::path::Path| {
                ActionResult::text(crate::magician_v2::execution::agentic::shell_tool::wrap_output(
                &serde_json::to_string_pretty(&json!({
                    "images": [{ "path": path.to_string_lossy(), "size_bytes": 12 }]
                }))
                .expect("serialize payload"),
                "image_generator",
                &crate::magician_v2::execution::agentic::shell_tool::ContentType::ToolOutput,
            ))
            };

        let mut first_result = make_result(&first_source);
        let mut second_result = make_result(&second_source);

        capture_pack_action_artifacts(&action, &mut first_result, &ctx, &executors, None, 0).await;
        capture_pack_action_artifacts(&action, &mut second_result, &ctx, &executors, None, 0).await;

        let first_execution_path = extract_wrapped_tool_output_json(&first_result)
            .and_then(|value| {
                value
                    .get("images")
                    .and_then(Value::as_array)
                    .and_then(|items| items.first())
                    .and_then(|item| item.get("path"))
                    .and_then(Value::as_str)
                    .map(ToOwned::to_owned)
            })
            .expect("first rewritten path");
        let second_execution_path = extract_wrapped_tool_output_json(&second_result)
            .and_then(|value| {
                value
                    .get("images")
                    .and_then(Value::as_array)
                    .and_then(|items| items.first())
                    .and_then(|item| item.get("path"))
                    .and_then(Value::as_str)
                    .map(ToOwned::to_owned)
            })
            .expect("second rewritten path");

        assert_ne!(first_execution_path, second_execution_path);
        assert_eq!(
            std::fs::read_to_string(&first_execution_path).expect("read first execution copy"),
            "first output"
        );
        assert_eq!(
            std::fs::read_to_string(&second_execution_path).expect("read second execution copy"),
            "second output"
        );
    }

