    /// The scoped router a run resolves its LLM calls through names the run's
    /// parent engine on every operation — the launch pin first, else a parent
    /// the context already carries, else the process snapshot — with the
    /// context's endpoints kept beside it.
    #[test]
    fn the_scoped_router_carries_the_run_engine_as_parent() {
        use crate::magician_v2::query_analysis::operation_llm_router::OperationRoutingEndpoint;

        let mut executors =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager());
        executors.operation_llm_router = Some(Arc::new(OperationLlmRouter::new(None)));
        let parent_of = |ctx: &AgenticContext| {
            operation_router_for_context(&executors, ctx)
                .expect("the executors carry a router")
                .routing_overrides()
                .and_then(|overrides| overrides.parent_engine.clone())
        };

        let mut ctx = AgenticContext::new("route under the run engine", "routed");
        ctx.harness_engine = Some("codex".to_string());
        assert_eq!(parent_of(&ctx).as_deref(), Some("codex"));

        // A pinned engine outranks a parent the context's overrides carry.
        ctx.llm_routing_overrides =
            Some(OperationRoutingOverrides::default().with_parent_engine(Some("grok".to_string())));
        assert_eq!(parent_of(&ctx).as_deref(), Some("codex"));

        // A terminal grant pins no engine and names its parent — the MCP
        // client's family — on the overrides; that is the parent.
        ctx.harness_engine = None;
        assert_eq!(parent_of(&ctx).as_deref(), Some("grok"));
        ctx.harness_engine = Some("codex".to_string());

        // The endpoints the context carries survive beside the parent.
        ctx.llm_routing_overrides = Some(OperationRoutingOverrides {
            planning: OperationRoutingEndpoint::for_profile("eval-luna"),
            ..Default::default()
        });
        let router = operation_router_for_context(&executors, &ctx).expect("router");
        let overrides = router.routing_overrides().expect("scoped overrides");
        assert_eq!(overrides.parent_engine.as_deref(), Some("codex"));
        assert_eq!(
            overrides
                .planning
                .as_ref()
                .and_then(|endpoint| endpoint.profile_name()),
            Some("eval-luna")
        );

        ctx.harness_engine = Some("magician".to_string());
        assert_eq!(parent_of(&ctx), None, "the native loop is no parent");

        // Unpinned with nothing carried, the process snapshot governs.
        ctx.harness_engine = None;
        assert_eq!(
            parent_of(&ctx),
            crate::magician_v2::query_analysis::parent_engine::normalize_parent_engine(Some(
                &crate::magician_v2::execution::plane::harness_engine_snapshot().engine
            )),
        );
    }

    /// A run's phases reach shared services through lane jobs, which are
    /// other tasks: the run's parent engine is re-scoped onto each job
    /// together with its coding flag and secret scope, or the ambient value
    /// is lost exactly where the background operations start. The coding
    /// flag is probed beside the parent because that is the property that
    /// was silently lost across the direct-path spawn.
    #[tokio::test]
    async fn a_scheduler_root_job_runs_under_the_run_parent_engine() {
        use crate::magician_v2::execution::coding_engine::{
            coding_context_active, with_coding_context,
        };
        use crate::magician_v2::query_analysis::parent_engine::current_parent_engine;

        let (lane, worker) = SchedulerRootLane::new();
        let mut executors =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager());
        executors.scheduler_root_lane = Some(lane);
        let mut workers = tokio::task::JoinSet::new();
        let worker: Pin<Box<dyn Future<Output = ()> + Send>> = Box::pin(worker.run());
        spawn_with_execution_token_meter_in_set(&mut workers, worker);
        let probe = || async { Ok((coding_context_active(), current_parent_engine())) };

        let mut ctx = AgenticContext::new("probe the parent", "seen");
        ctx.harness_engine = Some("codex".to_string());
        let seen = with_coding_context(
            true,
            run_on_agentic_scheduler_root(&ctx, &executors, "parent probe", probe),
        )
        .await
        .expect("lane job result");
        assert_eq!(seen, (true, Some("codex".to_string())));

        ctx.harness_engine = Some("magician".to_string());
        let seen = with_coding_context(
            true,
            run_on_agentic_scheduler_root(&ctx, &executors, "native probe", probe),
        )
        .await
        .expect("lane job result");
        assert_eq!(seen, (true, None), "the native loop is no parent");

        // Outside a coding run the flag crosses as false, not as a leak.
        let seen = run_on_agentic_scheduler_root(&ctx, &executors, "general probe", probe)
            .await
            .expect("lane job result");
        assert_eq!(seen, (false, None));

        workers.abort_all();
        while workers.join_next().await.is_some() {}
    }

    /// Every scheduler-lane hop re-scopes the run's task-locals as ONE value.
    /// A hop that carried the coding flag and the secret scope by hand and
    /// forgot the parent engine is exactly what this pins against: the
    /// carrier is the only way onto a lane job.
    #[test]
    fn every_lane_hop_carries_the_run_task_locals_as_one_value() {
        let source = include_str!("executor.rs");
        let implementation = source
            .split("#[cfg(any(test, feature = \"test-fixtures\"))]\nmod tests {")
            .next()
            .expect("implementation half");
        let hops = [
            "async fn run_on_agentic_scheduler_root",
            "pub(super) fn execute_direct_path_on_scheduler_root",
            "fn schedule_delegation_spawn_job",
            "fn schedule_app_agent_tool_spawn_job",
            "pub(super) fn schedule_agentic_decision_job",
            "fn schedule_action_execution_job",
            "fn schedule_state_build_job",
        ];
        for hop in hops {
            let body = implementation
                .split(hop)
                .nth(1)
                .and_then(|tail| tail.split("\n}\n").next())
                .unwrap_or_else(|| panic!("{hop} body"));
            assert!(
                body.contains("CapturedRunTaskLocals::for_context("),
                "{hop} must capture the run's task-locals through the carrier"
            );
            assert!(
                body.contains("task_locals.scope("),
                "{hop} must re-scope the carrier around its job"
            );
            assert!(
                !body.contains("with_coding_context(") && !body.contains("with_secret_scope("),
                "{hop} must not re-scope one task-local by hand beside the carrier"
            );
        }
        assert_eq!(
            implementation
                .matches("scheduler_root_lane.schedule(")
                .count()
                + implementation
                    .matches(".schedule(\"agentic decision\"")
                    .count(),
            hops.len() + 1,
            "a new lane hop must be added to this list — or, if it dispatches no work that \
             reads a task-local (the projection sanitizer), named here as the exception"
        );
    }

    /// The run seam scopes the parent where the run's other task-locals are
    /// scoped, so every phase of either driver runs under it.
    #[test]
    fn the_run_seam_scopes_the_parent_engine_beside_the_coding_context() {
        let source = include_str!("executor.rs");
        let seam = source
            .split("async fn execute_agentically_scoped_on_execution_runtime")
            .nth(1)
            .and_then(|tail| tail.split("fn validate_app_disclosure_checkpoint").next())
            .expect("run seam body");
        let coding = seam
            .find("with_coding_context(")
            .expect("the coding context scope");
        let parent = seam
            .find("parent_engine::with_parent_engine(")
            .expect("the parent engine scope");
        let secret = seam.find("with_secret_scope(").expect("the secret scope");
        assert!(coding < parent && parent < secret);
        assert!(seam.contains("plane::run_parent_engine(&ctx)"));
    }

    #[tokio::test]
    #[allow(clippy::needless_return)]
    async fn test_execute_agentically_immediate_success() {
        test_execute_agentically_immediate_success_inner().await;
    }

    async fn test_execute_agentically_immediate_success_inner() {
        let run = scoped_loop_run(
            "Test goal",
            "Goal is achieved",
            vec![
                // goal_reached carries evidence → lowered to Yield{Done, completed:[evidence]}
                // → dispose_yield → Completed → AgenticOutcome::Success (Phase 0.8c-12).
                r#"{"decision": "goal_reached", "evidence": "Goal achieved successfully", "artifacts": []}"#,
            ],
        )
        .heap_boxed()
        .await;
        let initial_state = EnvironmentState::Shell(ShellState::default());

        let outcome = execute_agentically(&run.ctx, initial_state, &run.executors, None)
            .await
            .unwrap();

        assert!(
            matches!(outcome, AgenticOutcome::Success { .. }),
            "scoped loop should reach Success, got {outcome:?}"
        );
        assert_eq!(outcome.iterations_used(), 1);
    }

    /// Explicit long-horizon qualification for the ordinary Tokio worker-stack
    /// policy. Kept out of the routine suite because it intentionally drives a
    /// thousand complete decide/execute/history iterations; the Makefile's
    /// `test-agentic-default-stack` lane runs it with `RUST_MIN_STACK` removed.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    #[ignore = "long-horizon default-stack qualification lane"]
    async fn default_stack_one_thousand_sequential_agentic_iterations() {
        #[derive(Debug)]
        struct StackProbeProvider {
            executions: Arc<std::sync::atomic::AtomicUsize>,
        }

        #[async_trait]
        impl crate::magician_v2::execution::capability::CapabilityProvider for StackProbeProvider {
            fn tool_name(&self) -> &str {
                "stack_probe"
            }

            fn lower(
                &self,
                step: &crate::magician_v2::strategy::plan::PlanStep,
            ) -> std::result::Result<
                crate::magician_v2::resource_authority::gated_action::MaybeGatedAction,
                crate::magician_v2::execution::error::ExecutionError,
            > {
                Ok(
                    crate::magician_v2::resource_authority::gated_action::MaybeGatedAction::Bare(
                        ExecutableAction::Pack {
                            capability_name: "stack_probe".to_string(),
                            implementation: crate::magician_v2::execution::capability::ImplementationType::Compiled {
                                provider_name: "stack_probe".to_string(),
                            },
                            resolved_params: step.parameters.clone(),
                        },
                    ),
                )
            }

            async fn execute(
                &self,
                action: &ExecutableAction,
                _session_id: Option<String>,
                _timeout_secs: u64,
            ) -> std::result::Result<
                ActionResult,
                crate::magician_v2::execution::error::ExecutionError,
            > {
                let ExecutableAction::Pack {
                    resolved_params, ..
                } = action
                else {
                    return Err(crate::magician_v2::execution::error::ExecutionError::Step(
                        "stack probe received a non-pack action".to_string(),
                    ));
                };
                let sequence = resolved_params
                    .get("sequence")
                    .and_then(Value::as_u64)
                    .ok_or_else(|| {
                        crate::magician_v2::execution::error::ExecutionError::Step(
                            "stack probe requires an integer sequence".to_string(),
                        )
                    })?;
                self.executions
                    .fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                Ok(ActionResult::text(format!("stack-probe-{sequence}")))
            }
        }

        let mut fixtures = (0..1_000)
            .map(|index| {
                format!(
                    r#"{{"decision":"execute","action_type":"tool","capability_name":"stack_probe","sequence":{index}}}"#
                )
            })
            .collect::<Vec<_>>();
        fixtures.push(
            r#"{"decision":"goal_reached","evidence":"All one thousand probes completed","artifacts":[]}"#
                .to_string(),
        );
        let mut executors = test_executors_with_decision_fixtures(fixtures);
        let mut ctx = AgenticContext::new(
            "Complete one thousand bounded probe iterations",
            "Every probe is processed before success",
        );
        let stack_probe_pack: crate::magician_v2::execution::capability::CapabilityPackDefinition =
            serde_yaml::from_str(
                r#"
name: stack_probe
description: In-memory state-changing provider for ordinary-stack qualification.
version: "1.0.0"
parameters:
  - name: sequence
    required: true
    param_type: integer
    description: Monotonic probe sequence.
implementation:
  type: compiled
  provider_name: stack_probe
execution:
  requires_browser_session: false
  default_timeout_secs: 5
  categories: [test]
  composition_category: action
  sandbox: none
"#,
            )
            .expect("stack probe pack");
        let executions = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let registry =
            Arc::new(crate::magician_v2::execution::capability::CapabilityRegistry::new());
        registry.register(Arc::new(StackProbeProvider {
            executions: Arc::clone(&executions),
        }));
        registry.set_pack_definition("stack_probe", stack_probe_pack.clone());
        executors.capability_registry = Some(Arc::clone(&registry));
        ctx.tool_index = Some(Arc::new(
            crate::magician_v2::execution::flat_loop::build_tool_index(&[stack_probe_pack]),
        ));
        ctx.scratch
            .loaded_tools
            .lock()
            .expect("loaded tools")
            .insert("stack_probe".to_string());
        ctx.merged_agent_tools = vec![runtime_core::ToolInfo {
            name: "stack_probe".to_string(),
            description: "Run an in-memory stack qualification probe".to_string(),
            category: "test".to_string(),
            categories: vec!["test".to_string()],
            parameters: vec![runtime_core::ParameterDefinition {
                name: "sequence".to_string(),
                param_type: "integer".to_string(),
                required: true,
                description: "Monotonic probe sequence".to_string(),
                validation_rules: Vec::new(),
                default_value: None,
                enum_values: None,
                schema: serde_json::json!({"type": "integer"}),
            }],
            enhanced_description: None,
            keywords: Vec::new(),
            use_cases: Vec::new(),
            composition_category: Some("action".to_string()),
            providing_agent_id: None,
        }];
        ctx.max_iterations = 1_001;
        ctx.max_repeated_actions = 1_001;

        let outcome = execute_agentically(
            &ctx,
            EnvironmentState::Shell(ShellState::default()),
            &executors,
            None,
        )
        .await
        .expect("a thousand sequential iterations must fit ordinary worker stacks");

        assert!(matches!(outcome, AgenticOutcome::Success { .. }));
        assert_eq!(outcome.iterations_used(), 1_001);
        assert_eq!(
            executions.load(std::sync::atomic::Ordering::SeqCst),
            1_000,
            "every non-terminal iteration must execute through the real capability registry"
        );
    }

    /// A pack provider that fails the way a governed file read of a missing
    /// path does: the provider returns `Err`, so the executor's error arm runs.
    #[derive(Debug)]
    struct RefusingProbeProvider;

    #[async_trait]
    impl crate::magician_v2::execution::capability::CapabilityProvider for RefusingProbeProvider {
        fn tool_name(&self) -> &str {
            "refusing_probe"
        }

        fn lower(
            &self,
            step: &crate::magician_v2::strategy::plan::PlanStep,
        ) -> std::result::Result<
            crate::magician_v2::resource_authority::gated_action::MaybeGatedAction,
            crate::magician_v2::execution::error::ExecutionError,
        > {
            Ok(
                crate::magician_v2::resource_authority::gated_action::MaybeGatedAction::Bare(
                    ExecutableAction::Pack {
                        capability_name: "refusing_probe".to_string(),
                        implementation:
                            crate::magician_v2::execution::capability::ImplementationType::Compiled {
                                provider_name: "refusing_probe".to_string(),
                            },
                        resolved_params: step.parameters.clone(),
                    },
                ),
            )
        }

        async fn execute(
            &self,
            _action: &ExecutableAction,
            _session_id: Option<String>,
            _timeout_secs: u64,
        ) -> std::result::Result<ActionResult, crate::magician_v2::execution::error::ExecutionError>
        {
            Err(crate::magician_v2::execution::error::ExecutionError::Step(
                "probe refused: no such file".to_string(),
            ))
        }
    }

    /// A pack provider that returns a result the executor classifies as
