    fn probe_pack(
        name: &str,
    ) -> crate::magician_v2::execution::capability::CapabilityPackDefinition {
        serde_yaml::from_str(&format!(
            r#"
name: {name}
description: In-memory probe provider for failed-action journalling.
version: "1.0.0"
parameters: []
implementation:
  type: compiled
  provider_name: {name}
execution:
  requires_browser_session: false
  default_timeout_secs: 5
  categories: [test]
  composition_category: action
  sandbox: none
"#
        ))
        .expect("probe pack")
    }

    /// Run one probe action followed by goal_reached on the scoped (stateless)
    /// loop fixture — the driver production uses — observing every
    /// `AgenticActionExecuted` the run emits.
    async fn failed_action_events(
        name: &str,
        provider: Arc<dyn crate::magician_v2::execution::capability::CapabilityProvider>,
    ) -> Vec<(String, bool, Option<String>)> {
        let probe_tool = runtime_core::ToolInfo {
            name: name.to_string(),
            description: "Run an in-memory failing probe".to_string(),
            category: "test".to_string(),
            categories: vec!["test".to_string()],
            parameters: Vec::new(),
            enhanced_description: None,
            keywords: Vec::new(),
            use_cases: Vec::new(),
            composition_category: Some("action".to_string()),
            providing_agent_id: None,
        };
        let mut run = scoped_loop_run_owned_by_with_direct_tools(
            "Observe one failed probe",
            "The failure is journalled",
            vec![
                format!(
                    r#"{{"decision":"execute","action_type":"tool","capability_name":"{name}"}}"#
                ),
                r#"{"decision":"goal_reached","evidence":"the probe was observed","artifacts":[]}"#
                    .to_string(),
            ],
            SCOPED_LOOP_OWNER,
            Vec::new(),
            vec![probe_tool.clone()],
        )
        .heap_boxed()
        .await;
        let broadcaster =
            Arc::new(crate::magician_v2::realtime_events::RuntimeTransportBroadcaster::new(256));
        let mut events = broadcaster.subscribe();
        run.executors.event_broadcaster = Some(Arc::clone(&broadcaster));
        run.ctx.plan_id = Some(format!("plan-{name}"));
        run.ctx.step_id = Some(format!("step-{name}"));
        let pack = probe_pack(name);
        let registry =
            Arc::new(crate::magician_v2::execution::capability::CapabilityRegistry::new());
        registry.register(provider);
        registry.set_pack_definition(name, pack.clone());
        run.executors.capability_registry = Some(Arc::clone(&registry));
        run.ctx.tool_index = Some(Arc::new(
            crate::magician_v2::execution::flat_loop::build_tool_index(&[pack]),
        ));
        run.ctx
            .scratch
            .loaded_tools
            .lock()
            .expect("loaded tools")
            .insert(name.to_string());
        run.ctx.merged_agent_tools = vec![probe_tool];
        run.ctx.max_iterations = 4;

        let outcome = execute_agentically(
            &run.ctx,
            EnvironmentState::Shell(ShellState::default()),
            &run.executors,
            None,
        )
        .await
        .expect("a failed probe is recoverable, not fatal");
        assert!(
            matches!(outcome, AgenticOutcome::Success { .. }),
            "the loop recovers after the failed probe, got {outcome:?}"
        );

        let mut seen = Vec::new();
        while let Ok(event) = events.try_recv() {
            if let RuntimeTransportEvent::AgenticActionExecuted {
                target,
                success,
                error,
                ..
            } = event
            {
                seen.push((target, success, error));
            }
        }
        seen
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_pack_action_that_errors_is_journalled_as_a_failed_tool_call() {
        let seen = failed_action_events("refusing_probe", Arc::new(RefusingProbeProvider)).await;
        let failed: Vec<_> = seen.iter().filter(|(_, success, _)| !success).collect();
        assert_eq!(
            failed.len(),
            1,
            "exactly one failed action event, got {seen:?}"
        );
        let (target, _, error) = failed[0];
        assert!(
            target.contains("refusing_probe"),
            "the event names the action: {target}"
        );
        assert!(
            error
                .as_deref()
                .is_some_and(|e| e.contains("probe refused")),
            "the event carries the failure reason: {error:?}"
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn a_pack_action_that_reports_failure_is_journalled_as_a_failed_tool_call() {
        let seen =
            failed_action_events("unsuccessful_probe", Arc::new(UnsuccessfulProbeProvider)).await;
        let failed: Vec<_> = seen.iter().filter(|(_, success, _)| !success).collect();
        assert_eq!(
            failed.len(),
            1,
            "exactly one failed action event, got {seen:?}"
        );
        assert!(
            failed[0].0.contains("unsuccessful_probe"),
            "the event names the action: {}",
            failed[0].0
        );
        assert!(
            failed[0].2.as_deref().is_some_and(|e| !e.is_empty()),
            "the event carries a reason: {:?}",
            failed[0].2
        );
    }

    #[tokio::test]
    async fn twenty_four_iteration_budget_pause_resumes_on_an_ordinary_test_stack() {
        use magicllm::prelude::{ContentBlock, LLMMessage, MessageRole};

        let run = scoped_loop_run(
            "Summarize the latest news",
            "A concise sourced summary is returned",
            vec![
                r#"{"decision": "goal_reached", "evidence": "Recovered findings synthesized", "artifacts": []}"#,
            ],
        )
        .heap_boxed()
        .await;
        let executors = run.executors;
        let mut pause_state = AgenticPauseState::new(
            24,
            "Summarize the latest news",
            "A concise sourced summary is returned",
            EnvironmentState::Shell(ShellState::default()),
            "Twenty-four prior research iterations completed before the budget pause",
            24,
            5,
        );
        pause_state.live_messages = (1..=24)
            .flat_map(|iteration| {
                [
                    LLMMessage {
                        role: MessageRole::Assistant,
                        content: vec![ContentBlock::Text {
                            text: format!("Research decision {iteration}"),
                        }],
                    },
                    LLMMessage {
                        role: MessageRole::User,
                        content: vec![ContentBlock::Text {
                            text: format!("Research result {iteration}"),
                        }],
                    },
                ]
            })
            .collect();
        // The resumed run is driven by the same durable arm as a fresh one, and
        // that arm addresses loop state by scope + execution id. The pause
        // snapshot is where a resume carries them.
        let pause_state = pause_state
            .with_observability(
                run.ctx
                    .execution_id
                    .as_deref()
                    .expect("scoped execution id"),
                "plan-budget-resume",
                "step-budget-resume",
            )
            .with_scope(SCOPED_LOOP_PRINCIPAL, SCOPED_LOOP_WORKSPACE)
            // The terminal settle refuses an incomplete agent scope, and a
            // resume carries the owner in the snapshot rather than on a context
            // it no longer has.
            .with_agent_routing(
                SCOPED_LOOP_OWNER,
                "goal-budget-resume",
                "cycle-budget-resume",
            );
        let confirmation_type = UserInputType::Confirmation {
            confirm_label: Some("Continue".to_string()),
            deny_label: Some("Cancel".to_string()),
            destructive: false,
        };
        let pause_data = FullPauseData::new(
            pause_state,
            confirmation_type.clone(),
            executors,
            Some("Cost budget reached. Continue?".to_string()),
            None,
        )
        .with_pause_kind(ExecutionPauseKind::Budget);
        let response = UserInputResponse::new(
            confirmation_type,
            UserInputValue::Confirmation { confirmed: true },
        );

        let resume_future = execute_agentically_resume_with_validation(
            pause_data, response, None, None, None, None, None,
        );
        let result = resume_future
            .await
            .expect("budget resume should complete without a special-stack thread");

        assert!(matches!(
            result,
            ResumeResult::Continue(AgenticOutcome::Success { .. })
        ));
    }

    /// The outer pipeline deadline encloses response interpretation and exact
    /// admission, not only the loop constructed afterwards. A wedged
    /// interpreter/authority lookup must therefore settle as deterministic
    /// failure and cancel the cooperative owner.
    #[test]
    fn resumed_pipeline_deadline_wraps_all_pre_loop_awaits() {
        let source = include_str!("executor.rs");
        let validation_wrapper = source
            .split("pub fn execute_agentically_resume_with_validation")
            .nth(1)
            .and_then(|tail| {
                tail.split("async fn execute_agentically_resume_with_validation_inner")
                    .next()
            })
            .expect("response resume wrapper");
        assert!(validation_wrapper.contains("tokio::time::timeout"));
        assert!(validation_wrapper.contains("deadline_cancel"));
        let validation_inner = source
            .split("async fn execute_agentically_resume_with_validation_inner")
            .nth(1)
            .and_then(|tail| tail.split("fn agentic_outcome_label").next())
            .expect("response resume inner");
        assert!(validation_inner.contains("interpreter.interpret"));

        for (entry, inner) in [
            (
                "pub async fn execute_agentically_continue",
                "async fn execute_agentically_continue_inner",
            ),
            (
                "pub async fn execute_agentically_resume_exact",
                "async fn execute_agentically_resume_exact_inner",
            ),
        ] {
            let wrapper = source
                .split(entry)
                .nth(1)
                .and_then(|tail| tail.split(inner).next())
                .expect("exact resume wrapper");
            assert!(wrapper.contains("tokio::time::timeout"));
            assert!(wrapper.contains("cancel.cancel()"));
            if entry.contains("resume_exact") {
                assert!(wrapper.contains("forget_exact_pause_process_authority"));
            }
        }
    }

    async fn steer_drained_by_running_loop_inner() {
        // On the default stateless arm an operator steer is delivered through the
        // durable inbox, not a process-local queue -- the loop that consumes it
        // may be in another process entirely, which is the whole point of that
        // arm. So enqueue it the way `steer_execution` does for a stateless
        // execution, then run a real agentic loop.
        let run = scoped_loop_run(
            "Test goal",
            "Goal is achieved",
            vec![r#"{"decision": "goal_reached", "evidence": "done", "artifacts": []}"#],
        )
        .heap_boxed()
        .await;
        let execution_id = run
            .ctx
            .execution_id
            .clone()
            .expect("scoped run names its execution");
        crate::magician_v2::execution::agentic::run_loop::steer_inbox::enqueue(
            &run.executors.artifact_v2_workspace,
            SCOPED_LOOP_PRINCIPAL,
            SCOPED_LOOP_WORKSPACE,
            &execution_id,
            SCOPED_LOOP_GENERATION,
            "focus on the pricing page",
        )
        .await
        .expect("enqueue an operator steer for the run");
        let initial_state = EnvironmentState::Shell(ShellState::default());

        let outcome = execute_agentically(&run.ctx, initial_state, &run.executors, None)
            .await
            .unwrap();

        assert!(matches!(outcome, AgenticOutcome::Success { .. }));
        // The running loop reached its per-iteration steer injection point and
        // drained the queue — proving a wired steer is consumed (folded into the
        // decision conversation) during a real run rather than left stranded.
        // Asserting the exact `[OPERATOR STEER]` text in the conversation would
        // need a recording decision adapter; the drain proves consumption.
        // The loop reached its per-iteration steer injection point and consumed
        // the inbox -- proving a delivered steer is folded into the decision
        // conversation during a real run rather than left stranded. Asserting
        // the exact `[OPERATOR STEER]` text in the conversation would need a
        // recording decision adapter; the consumption proves delivery.
        // Read the inbox rather than claiming it: a run that reaches a terminal
        // fences its own inbox against further admission, so a post-run claim is
        // refused by design and would say nothing about consumption. An entry
        // carries a claim once a loop has taken it.
        let inbox_path = run
            .executors
            .artifact_v2_workspace
            .scope_root(SCOPED_LOOP_PRINCIPAL, SCOPED_LOOP_WORKSPACE)
            .join("restricted")
            .join("operator_steers")
            .join(format!(
                "{}.json",
                blake3::hash(execution_id.as_bytes()).to_hex()
            ));
        let inbox: serde_json::Value = serde_json::from_str(
            &tokio::fs::read_to_string(&inbox_path)
                .await
                .expect("the run's steer inbox exists"),
        )
        .expect("the steer inbox is JSON");
        // Consumption either claims the entry or retires it, so what proves the
        // loop took the steer is that no UNCLAIMED one is left. A run that never
        // reached its injection point would leave the enqueued entry sitting
        // here with no claim on it.
        let unclaimed = inbox
            .get("entries")
            .and_then(serde_json::Value::as_array)
            .map(|entries| {
                entries
                    .iter()
                    .filter(|entry| entry.get("claim").is_none_or(serde_json::Value::is_null))
                    .count()
            })
            .unwrap_or(0);
        assert_eq!(
            unclaimed, 0,
            "the running loop must consume a delivered operator steer during the run: {inbox}"
        );
    }

    #[tokio::test]
    #[allow(clippy::needless_return)]
    async fn steer_drained_by_running_loop() {
        steer_drained_by_running_loop_inner().await;
    }

