    #[test]
    fn production_scoped_tool_search_first_action_fits_default_execution_worker_stack() {
        // Reproduce the 2026-08-05 web-research live crash through the complete
        // outer loop, not just the direct-action helper. The production failure
        // occurred after a scoped first-turn `tool_search` decision and before
        // scheduler handoff on a normal `magician-execution-worker` stack.
        let runtime = crate::magician_v2::execution::runtime_boundary::build_execution_runtime()
            .expect("execution runtime");
        runtime.block_on(async {
            tokio::spawn(async {
                let packs = crate::magician_v2::execution::compiled_providers::embedded_compiled_pack_defs();
                let index = Arc::new(
                    crate::magician_v2::execution::flat_loop::build_tool_index(&packs),
                );
                let definition = crate::magician_v2::agents::AgentDefinition::from_yaml_str(
                    "agent_id: web-researcher\nname: Web Researcher\npersona: Test scoped research agent\ntrust_level: local\ntools:\n  - tool_search\n  - save_preference\n  - search_memory\n",
                )
                .expect("web-researcher definition");
                let mut run = scoped_loop_run_owned_by(
                    "Compare prices of GPT 5.6 family and Sarvam.",
                    "Use authoritative current sources.",
                    [
                        r#"{"decision":"execute","action_type":"tool","capability_name":"tool_search","query":"select:save_preference,search_memory"}"#,
                    ],
                    "web-researcher",
                    Vec::new(),
                )
                .heap_boxed()
                .await;
                run.ctx.active_owner_agent_id = Some("web-researcher".to_string());
                run.ctx.owner_definition = Some(Arc::new(definition));
                run.ctx.tool_index = Some(index);
                run.ctx.max_iterations = 1;
                run.ctx.max_tokens_per_cycle = Some(20_000_000);

                let outcome = execute_agentically(
                    &run.ctx,
                    EnvironmentState::Shell(ShellState::default()),
                    &run.executors,
                    None,
                )
                .await
                .expect("scoped tool_search execution");

                assert!(
                    matches!(outcome, AgenticOutcome::MaxIterationsReached { .. }),
                    "the one-iteration fixture must terminate after tool_search: {outcome:?}",
                );
                assert_eq!(
                    *run.ctx.scratch.loaded_tools.lock().expect("loaded tools"),
                    std::collections::HashSet::from([
                        "save_preference".to_string(),
                        "search_memory".to_string(),
                    ]),
                    "tool_search must complete family projection before termination",
                );
            })
            .await
            .expect("production-shaped tool_search execution worker");
        });
    }

    /// End-to-end Flat-mode loop WITH a real flat dispatch: the stubbed LLM
    /// picks the `duckdb__query` leaf directly (no inner LLM), the
    /// executor's flat guard routes it through `dispatch_flat_action` → the
    /// compiled duckdb provider, then a second decision terminates. Proves
    /// the index-driven flat catalog + flat dispatch + terminal all run
    /// inside the full outer loop.
    async fn test_execute_agentically_flat_mode_dispatches_pack_then_succeeds_inner() {
        use crate::magician_v2::execution::{
            capability::CapabilityRegistry,
            compiled_providers::{embedded_compiled_pack_defs, DuckDbCapabilityProvider},
        };

        // Registry: the embedded duckdb pack def (so the flat catalog promotes
        // `duckdb__query` and the flat guard classifies it as a compiled-provider
        // primitive) + a live DuckDbCapabilityProvider to execute it.
        let pack = embedded_compiled_pack_defs()
            .into_iter()
            .find(|p| p.name == "duckdb")
            .expect("embedded duckdb pack def present");
        let registry = CapabilityRegistry::new();
        registry.set_pack_definition("duckdb", pack.clone());
        registry.register(Arc::new(
            DuckDbCapabilityProvider::new()
                .expect("duckdb provider init (bundled dep)")
                .with_pack_def(pack),
        ));
        let registry = Arc::new(registry);

        let mut run = scoped_loop_run(
            "Run a SELECT via duckdb in flat mode",
            "The query executed",
            vec![
                // Flat mode: the outer LLM picks the per-action leaf directly.
                r#"{"decision": "execute", "action_type": "tool", "capability_name": "duckdb__query", "sql": "SELECT 1 AS x"}"#,
                // Then terminate, evidence referencing the executed query.
                r#"{"decision": "goal_reached", "evidence": "Ran the duckdb query and observed the result row.", "artifacts": []}"#,
            ],
        )
        .heap_boxed()
        .await;
        run.executors = run.executors.with_capability_registry(registry);
        let initial_state = EnvironmentState::Shell(ShellState::default());

        let outcome = execute_agentically(&run.ctx, initial_state, &run.executors, None)
            .await
            .unwrap();

        assert!(
            matches!(outcome, AgenticOutcome::Success { .. }),
            "flat-mode duckdb dispatch run should succeed, got {outcome:?}"
        );
        assert_eq!(
            outcome.iterations_used(),
            2,
            "one flat duckdb dispatch + one terminal"
        );
    }

    // === Orchestration spine harness (Tier 1) =================================
    // Deterministic, in-process test of the multi-agent delegation boundary —
    // no orchestrator, no live LLM, no MagicutorClient, no spawned executions.
    // This is the instrument that turns the multi-step pipeline from a ~30-min
    // non-deterministic live run into a millisecond assertion, and locks each
    // historically-fixed bug as a regression test.

    /// A scripted `DelegationDispatcher` test double: records every requested
    /// target into a capture log and returns canned child handles WITHOUT
    /// spawning real executions, so a `delegate_to_agent` decision can be
    /// driven to its `WaitingForChildren` park deterministically.
    #[derive(Debug, Default)]
    struct ScriptedDelegationDispatcher {
        available:
            Vec<crate::magician_v2::execution::agentic::delegation_dispatch::DelegationTarget>,
        spawned: std::sync::Arc<
            std::sync::Mutex<Vec<crate::magician_v2::execution::actions::DelegationTargetRequest>>,
        >,
        completed_reused: bool,
    }

    #[async_trait::async_trait]
    impl crate::magician_v2::execution::agentic::delegation_dispatch::DelegationDispatcher
        for ScriptedDelegationDispatcher
    {
        async fn available_targets(
            &self,
            _source_agent_id: &str,
            _principal: Option<&str>,
            _workspace: Option<&str>,
        ) -> Vec<crate::magician_v2::execution::agentic::delegation_dispatch::DelegationTarget>
        {
            self.available.clone()
        }

        async fn spawn_children(
            &self,
            _source_agent_id: &str,
            _source_execution_id: &str,
            _source_chain_id: Option<&str>,
            targets: Vec<crate::magician_v2::execution::actions::DelegationTargetRequest>,
            _cancel: Option<tokio_util::sync::CancellationToken>,
        ) -> Result<
            crate::magician_v2::execution::agentic::delegation_dispatch::DelegationSpawnResult,
            crate::magician_v2::execution::agentic::delegation_dispatch::DispatchError,
        > {
            use crate::magician_v2::execution::agentic::delegation_dispatch::{
                DelegationSpawnResult, SpawnedDelegationChild,
            };
            let child_executions: Vec<SpawnedDelegationChild> = targets
                .iter()
                .map(|t| SpawnedDelegationChild {
                    execution_id: format!("child-{}", t.target_agent_id),
                    target_agent_id: t.target_agent_id.clone(),
                })
                .collect();
            self.spawned.lock().unwrap().extend(targets);
            let completed_reused_execution_ids = if self.completed_reused {
                child_executions
                    .iter()
                    .map(|child| child.execution_id.clone())
                    .collect()
            } else {
                Vec::new()
            };
            Ok(DelegationSpawnResult {
                child_executions,
                completed_reused_execution_ids,
                admission_queue_ms: 0,
                admission_preflight_ms: 0,
                child_shells_ready_ms: 0,
                resource_wait_ms: 0,
                dispatch_total_ms: 0,
            })
        }
    }

    fn scripted_target(
        agent_id: &str,
        tools: &[&str],
    ) -> crate::magician_v2::execution::agentic::delegation_dispatch::DelegationTarget {
        crate::magician_v2::execution::agentic::delegation_dispatch::DelegationTarget {
            agent_id: agent_id.to_string(),
            name: agent_id.to_string(),
            aliases: Vec::new(),
            description: format!("{agent_id} (scripted test target)"),
            tools: tools.iter().map(|t| t.to_string()).collect(),
            allowed_invocation_surfaces: vec![
                crate::magician_v2::agents::InvocationSurface::Delegation,
                crate::magician_v2::agents::InvocationSurface::Handover,
            ],
        }
    }

    #[test]
    fn delegation_target_aliases_canonicalize_to_agent_id() {
        let targets = vec![
            crate::magician_v2::execution::agentic::delegation_dispatch::DelegationTarget {
                agent_id: "senior-software-developer".to_string(),
                name: "Halo".to_string(),
                aliases: vec!["halo".to_string()],
                description: "Senior engineer".to_string(),
                tools: vec!["run_coding_task".to_string()],
                allowed_invocation_surfaces: vec![
                    crate::magician_v2::agents::InvocationSurface::Delegation,
                    crate::magician_v2::agents::InvocationSurface::Handover,
                ],
            },
            scripted_target("internal-system-analyst", &["rg__run"]),
            crate::magician_v2::execution::agentic::delegation_dispatch::DelegationTarget {
                agent_id: "handover-only".to_string(),
                name: "Handover Only".to_string(),
                aliases: vec!["handover".to_string()],
                description: "May receive ownership but not delegated work".to_string(),
                tools: Vec::new(),
                allowed_invocation_surfaces: vec![
                    crate::magician_v2::agents::InvocationSurface::Handover,
                ],
            },
        ];

        assert_eq!(
            canonical_delegation_target_id(&targets, "Halo"),
            Some("senior-software-developer".to_string())
        );
        assert_eq!(
            canonical_delegation_target_id(&targets, " senior-software-developer "),
            Some("senior-software-developer".to_string())
        );
        assert_eq!(canonical_delegation_target_id(&targets, "missing"), None);
        assert_eq!(canonical_delegation_target_id(&targets, "handover"), None);
    }

