    #[test]
    fn owner_policy_fingerprint_ignores_set_iteration_order() {
        let tool = |name: &str| runtime_core::ToolInfo {
            name: name.to_string(),
            description: format!("{name} description"),
            category: "custom".to_string(),
            categories: Vec::new(),
            parameters: Vec::new(),
            enhanced_description: None,
            keywords: Vec::new(),
            use_cases: Vec::new(),
            composition_category: None,
            providing_agent_id: None,
        };
        let mut first = AgenticContext::new("goal", "success");
        first.merged_agent_tools = vec![tool("browser"), tool("search_memory")];
        first.delegation_targets = vec![
            scripted_target("browser-worker", &["browser"]),
            scripted_target("memory-worker", &["search_memory"]),
        ];
        first.denied_capability_names = vec!["write_file".into(), "shell".into()];
        first.allowed_action_types = Some(vec!["tool".into(), "delegate".into()]);
        first.available_procedure_skills = vec![
            ("research".into(), "Research carefully".into()),
            ("summarize".into(), "Summarize findings".into()),
        ];

        let mut reordered = first.clone();
        reordered.merged_agent_tools.reverse();
        reordered.delegation_targets.reverse();
        reordered.denied_capability_names.reverse();
        reordered
            .allowed_action_types
            .as_mut()
            .expect("actions")
            .reverse();
        reordered.available_procedure_skills.reverse();

        assert_eq!(
            owner_effective_policy_fingerprint(&first).expect("first fingerprint"),
            owner_effective_policy_fingerprint(&reordered).expect("reordered fingerprint"),
            "semantically identical authorization sets must not invalidate an in-flight decision"
        );

        reordered.merged_agent_tools[0].description = "authority metadata changed".into();
        assert_ne!(
            owner_effective_policy_fingerprint(&first).expect("first fingerprint"),
            owner_effective_policy_fingerprint(&reordered).expect("changed fingerprint"),
            "material tool metadata changes must still invalidate the decision"
        );

        let mut ownership_changed = first.clone();
        ownership_changed.merged_agent_tools[0].providing_agent_id = Some("worker".into());
        assert_ne!(
            owner_effective_policy_fingerprint(&first).expect("first fingerprint"),
            owner_effective_policy_fingerprint(&ownership_changed).expect("ownership fingerprint"),
            "direct-to-delegated ownership changes must invalidate the decision"
        );
    }

