    #[test]
    fn delegation_work_budget_is_not_clamped_by_source_agent_config() {
        assert_eq!(delegation_work_budget_secs(Some(600), None), Ok(Some(600)));
        assert_eq!(
            delegation_work_budget_secs(None, Some("deep")),
            Ok(Some(900))
        );
        assert_eq!(
            delegation_work_budget_secs(None, Some("thorough")),
            Ok(Some(1800))
        );
        // An explicit value extends its tier and never reduces it: a request
        // below the normal tier comes back at the tier, not at the request.
        // This assertion read `Ok(Some(30))` until the floor was introduced —
        // a model-authored 120 s and 180 s had each ended a whole desktop job
        // as "partial" at the budget, on every engine — and the stale
        // expectation outlived the change it was written against. The name of
        // this test is about the SOURCE AGENT's config not clamping a caller's
        // value, which is a separate rule and still holds above.
        assert_eq!(delegation_work_budget_secs(Some(30), None), Ok(Some(300)));
        assert_eq!(
            delegation_work_budget_secs(Some(30), Some("thorough")),
            Ok(Some(1800)),
            "a named depth is the tier an explicit value is raised to"
        );
        assert_eq!(delegation_work_budget_secs(None, None), Ok(None));
        assert!(delegation_work_budget_secs(Some(0), None).is_err());
        assert!(delegation_work_budget_secs(None, Some("extended")).is_err());
    }

    /// The in-context delegation hop must leave the delegating owner on the
    /// stack. Everything that stops `A -> B -> A` and stops a leaf from
    /// sub-delegating reads that stack; pushing an empty one (what this path
    /// used to do) disarmed all of it at once.
    #[test]
    fn in_context_delegate_frame_keeps_the_delegating_owner_on_the_stack() {
        let mut root = AgenticContext::new("orchestrate", "done");
        root.agent_id = Some("personal-assistant".to_string());
        root.active_owner_agent_id = Some("personal-assistant".to_string());

        let first_hop = delegate_frame_owner_stack(&root).expect("root has an owner");
        assert_eq!(first_hop, vec!["personal-assistant".to_string()]);

        // A second, nested in-context hop stacks on top of the first — it does
        // not replace it, or the depth accounting would forget a level.
        let mut nested = root.clone();
        nested.owner_stack = first_hop;
        nested.active_owner_agent_id = Some("researcher".to_string());
        assert_eq!(
            delegate_frame_owner_stack(&nested).expect("nested has an owner"),
            vec!["personal-assistant".to_string(), "researcher".to_string()]
        );
    }

    /// A loop running as an in-context delegate must not yield back on its own:
    /// the frame that pushed it owns the restore. Nested same-owner sub-goals
    /// inside that delegate are still inside it.
    #[test]
    fn in_context_delegate_detection_spans_nested_frames() {
        fn frame(kind: AgenticContinuationKind) -> AgenticContinuationFrame {
            AgenticContinuationFrame {
                kind,
                goal: "goal".to_string(),
                success_criteria: "criteria".to_string(),
                remaining_iterations: 1,
                max_repeated_actions: 1,
                iteration_offset: 0,
                depth: 0,
                work_budget_secs: None,
                work_budget_consumed_ms: 0,
                nested_work_budget_baseline_ms: 0,
                loop_protective_state: None,
                step_id: None,
                pending_inputs: Vec::new(),
                resolved_inputs: HashMap::new(),
                resolved_input_sensitivity: HashMap::new(),
                asking_for_parameter: None,
                prior_environment_knowledge: None,
                action_history_summary: String::new(),
                approved_confirmation_actions: Vec::new(),
                active_owner_agent_id: Some("personal-assistant".to_string()),
                owner_stack: Vec::new(),
                owner_invocation_stack: Vec::new(),
                invocation_context_override: None,
            }
        }

        let mut ctx = AgenticContext::new("goal", "criteria");
        assert!(!running_as_in_context_delegate(&ctx));

        ctx.continuation_frames = vec![frame(AgenticContinuationKind::SameOwnerSubGoal)];
        assert!(
            !running_as_in_context_delegate(&ctx),
            "a same-owner sub-goal under a handover specialist must still yield back"
        );

        ctx.continuation_frames = vec![
            frame(AgenticContinuationKind::InContextDelegation),
            frame(AgenticContinuationKind::SameOwnerSubGoal),
        ];
        assert!(
            running_as_in_context_delegate(&ctx),
            "a sub-goal nested inside an in-context delegate is still inside it"
        );
    }

    /// `A -> B -> A`: B is running on A's execution with A suspended beneath
    /// it, and tries to delegate straight back to A. Handover has always
    /// refused this (`CircularHandover`); delegation admitted it, and the
    /// in-context path never reaches the dispatcher where the durable chain
    /// check lives.
    #[tokio::test]
    async fn delegating_back_to_a_suspended_owner_is_rejected() {
        let spawned = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let dispatcher = std::sync::Arc::new(ScriptedDelegationDispatcher {
            available: vec![scripted_target("personal-assistant", &["search_memory"])],
            spawned: spawned.clone(),
            completed_reused: false,
        });
        let executors = test_executors_with_decision_fixtures(Vec::<String>::new())
            .with_delegation_dispatcher(dispatcher);

        let mut ctx = AgenticContext::new("write the section", "section written");
        ctx.agent_id = Some("researcher".to_string());
        ctx.active_owner_agent_id = Some("researcher".to_string());
        ctx.execution_id = Some("exec-cycle-guard".to_string());
        // The PA root delegated in-context to `researcher`; it is suspended
        // beneath this frame, waiting for it to return.
        ctx.owner_stack = vec!["personal-assistant".to_string()];
        ctx.delegation_targets = vec![scripted_target("personal-assistant", &["search_memory"])];

        let request = DelegationTargetRequest {
            target_agent_id: "personal-assistant".to_string(),
            context: "hand this straight back to the coordinator".to_string(),
            input_artifact_ids: Vec::new(),
            input_data: None,
            depth: None,
            timeout_secs: None,
            spend_token_ids: Vec::new(),
            required_capability: None,
            expected_artifacts: Vec::new(),
        };

        let error = match validate_delegation_request(&ctx, &executors, &[request], 0).await {
            Ok(_) => panic!("A -> B -> A must be refused"),
            Err(error) => error,
        };
        assert_eq!(error.error_code, "CircularDelegation");
        assert!(
            spawned.lock().unwrap().is_empty(),
            "the cycle must be refused before any dispatch side effect"
        );
    }

    /// A target that is NOT an ancestor owner stays delegable — the cycle guard
