    #[tokio::test]
    async fn pause_resume_rejects_changed_or_removed_execution_route_binding() {
        let temp = tempfile::tempdir().expect("tempdir");
        let storage_root = temp.path().join("magician_data_v3");
        let workspace = crate::magician_v2::artifact_v2::workspace::ArtifactV2Workspace::new(
            storage_root.clone(),
        );
        let principal = "principal-a";
        let workspace_id = "workspace-a";
        let task_id = "task-routing";
        let execution_id = "exec-routing";
        workspace
            .ensure_task_workspace(principal, workspace_id, task_id)
            .await
            .expect("task workspace");
        workspace
            .ensure_execution_workspace(principal, workspace_id, task_id, execution_id)
            .await
            .expect("execution workspace");
        let durable_route = OperationRoutingOverrides {
            planning: crate::magician_v2::query_analysis::operation_llm_router::OperationRoutingEndpoint::for_profile(
                "eval-luna",
            ),
            ..Default::default()
        };
        workspace
            .write_json_atomic_path(
                workspace
                    .execution_dir(principal, workspace_id, task_id, execution_id)
                    .join(
                        crate::magician_v2::artifact_v2::service::EXECUTION_LLM_ROUTING_OVERRIDES_FILE,
                    ),
                &durable_route,
            )
            .await
            .expect("routing binding");
        let seal = crate::magician_v2::execution::trusted_store::seal_execution_routing(
            &workspace,
            principal,
            workspace_id,
            task_id,
            execution_id,
            &durable_route,
        )
        .expect("routing seal");
        let seal_path = crate::magician_v2::execution::trusted_store::execution_routing_seal_path(
            &workspace,
            principal,
            workspace_id,
            task_id,
            execution_id,
        );
        workspace
            .create_dir_all_path(seal_path.parent().expect("seal parent"))
            .await
            .expect("routing seal directory");
        workspace
            .write_json_atomic_path(&seal_path, &seal)
            .await
            .expect("routing integrity seal");

        let mut pause = test_pause_state();
        pause.storage_base_path = storage_root;
        pause.principal = Some(principal.to_string());
        pause.workspace = Some(workspace_id.to_string());
        pause.task_id = Some(task_id.to_string());
        pause.execution_id = Some(execution_id.to_string());
        pause.execution_llm_routing_overrides = Some(durable_route.clone());
        pause.llm_routing_overrides = Some(durable_route.clone());
        validate_paused_execution_routing(&pause)
            .await
            .expect("matching durable route");

        let tampered_route = OperationRoutingOverrides {
            planning: crate::magician_v2::query_analysis::operation_llm_router::OperationRoutingEndpoint::for_profile(
                "tampered-profile",
            ),
            ..Default::default()
        };
        pause.execution_llm_routing_overrides = Some(tampered_route.clone());
        assert!(validate_paused_execution_routing(&pause)
            .await
            .expect_err("changed route must fail closed")
            .contains("execution_routing_binding_mismatch"));

        workspace
            .write_json_atomic_path(
                workspace
                    .execution_dir(principal, workspace_id, task_id, execution_id)
                    .join(
                        crate::magician_v2::artifact_v2::service::EXECUTION_LLM_ROUTING_OVERRIDES_FILE,
                    ),
                &tampered_route,
            )
            .await
            .expect("simulate sidecar tamper");
        assert!(validate_paused_execution_routing(&pause)
            .await
            .expect_err("changing pause and sidecar cannot forge the restricted seal")
            .contains("execution_routing_binding_invalid"));

        workspace
            .write_json_atomic_path(
                workspace
                    .execution_dir(principal, workspace_id, task_id, execution_id)
                    .join(
                        crate::magician_v2::artifact_v2::service::EXECUTION_LLM_ROUTING_OVERRIDES_FILE,
                    ),
                &durable_route,
            )
            .await
            .expect("restore bound route");

        pause.execution_llm_routing_overrides = None;
        pause.llm_routing_overrides = None;
        assert!(validate_paused_execution_routing(&pause)
            .await
            .expect_err("removed route must fail closed")
            .contains("execution_routing_binding_mismatch"));

        tokio::fs::remove_file(
            workspace
                .execution_dir(principal, workspace_id, task_id, execution_id)
                .join(
                    crate::magician_v2::artifact_v2::service::EXECUTION_LLM_ROUTING_OVERRIDES_FILE,
                ),
        )
        .await
        .expect("simulate deleting agent-visible route");
        assert!(validate_paused_execution_routing(&pause)
            .await
            .expect_err("protected seal must detect stripping both pause and route")
            .contains("execution_routing_binding_missing"));
    }

