    // A scoped run resolves an owner profile and settles a real terminal, and
    // that path is deeper than a plain test thread's stack. Production runs it
    // on `magician-execution-worker`; so does this, like its siblings above.
    #[test]
    fn test_spine_delegate_to_agent_yields_waiting_for_children() {
        let runtime = delegation_decision_runtime();
        runtime.block_on(async {
            tokio::spawn(async {
                test_spine_delegate_to_agent_yields_waiting_for_children_inner()
                    .heap_boxed()
                    .await;
            })
            .await
            .expect("spine delegation execution worker");
        });
    }

    /// A scripted `delegate_to_agent` decision must route through
    /// `validate_delegation_request` -> `dispatcher.spawn_children` and PARK
    /// the loop as `WaitingForChildren`, handing the dispatcher exactly the
    /// requested target. Asserting `WaitingForChildren` (not
    /// `Continue`/`Success`) is the canary for the silent-degrade class
    /// that kept the multi-step flow broken: if delegation ever quietly
    /// no-ops again, this fails in milliseconds at the boundary instead of
    /// as a far-downstream symptom 30 minutes later.
    async fn test_spine_delegate_to_agent_yields_waiting_for_children_inner() {
        let spawned = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let dispatcher = std::sync::Arc::new(ScriptedDelegationDispatcher {
            available: vec![
                scripted_target("web-researcher", &["web_search"]),
                scripted_target("creative-mind", &["image-generation"]),
            ],
            spawned: spawned.clone(),
            completed_reused: false,
        });

        let mut run = scoped_loop_run_owned_by(
            "research X, ELI5 it, then make a comic",
            "a comic strip explaining the fund raise is produced",
            vec![
                r#"{"decision":"delegate_to_agent","delegation_targets":[{"target_agent_id":"web-researcher","context":"research the latest fund raise"}]}"#,
            ],
            "personal-assistant",
            vec![
                scripted_target("web-researcher", &["web_search"]),
                scripted_target("creative-mind", &["image-generation"]),
            ],
        )
        .heap_boxed()
        .await;
        run.executors = run.executors.with_delegation_dispatcher(dispatcher);

        let initial_state = EnvironmentState::Shell(ShellState::default());
        let outcome = execute_agentically(&run.ctx, initial_state, &run.executors, None)
            .await
            .expect("execute_agentically should not error");

        match outcome {
            AgenticOutcome::WaitingForChildren {
                child_execution_ids,
                ..
            } => {
                assert_eq!(
                    child_execution_ids,
                    vec!["child-web-researcher".to_string()],
                    "the scripted web-researcher child should be the parked child"
                );
            },
            other => panic!("delegate_to_agent must park as WaitingForChildren, got {other:?}"),
        }

        let captured = spawned.lock().unwrap();
        assert_eq!(
            captured.len(),
            1,
            "dispatcher should receive exactly one delegation request"
        );
        assert_eq!(captured[0].target_agent_id, "web-researcher");
    }

