    async fn completed_idempotent_delegation_is_consumed_without_waiting_again_inner() {
        let spawned = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let dispatcher = std::sync::Arc::new(ScriptedDelegationDispatcher {
            available: vec![scripted_target("web-researcher", &["web_search"])],
            spawned: spawned.clone(),
            completed_reused: true,
        });
        let mut run = scoped_loop_run_owned_by(
            "research the latest fund raise",
            "the delegated result is consumed",
            vec![
                r#"{"decision":"delegate_to_agent","delegation_targets":[{"target_agent_id":"web-researcher","context":"research the latest fund raise"}]}"#,
                r#"{"decision":"goal_reached","evidence":"Consumed the already-completed delegated research result.","artifacts":[]}"#,
            ],
            "personal-assistant",
            vec![scripted_target("web-researcher", &["web_search"])],
        )
        .heap_boxed()
        .await;
        run.executors = run.executors.with_delegation_dispatcher(dispatcher);

        let outcome = execute_agentically(
            &run.ctx,
            EnvironmentState::Shell(ShellState::default()),
            &run.executors,
            None,
        )
        .await
        .expect("idempotent delegation replay should remain in the current loop");

        assert!(
            matches!(outcome, AgenticOutcome::Success { .. }),
            "a completed reused child must be consumed, not parked again: {outcome:?}"
        );
        assert_eq!(spawned.lock().unwrap().len(), 1);
    }

    /// Option B — `delegate_outcome_primary_text` extracts the sub-agent's text
    /// deliverable from a Success outcome (excluding binary), and surfaces an
    /// explanatory note for a Failed outcome. This is the text the in-context
    /// delegate threads into the PA root's `prior_environment_knowledge` so the
    /// root's NEXT decision sees the result. Mirrors the orchestrator's
    /// `primary_text_from_outcome` lock so the executor-side copy can't drift.
    #[test]
    fn test_delegate_outcome_primary_text_extracts_text_excludes_binary() {
        use crate::magician_v2::execution::{AgenticOutcome, Artifact, EnvironmentState};
        let success = AgenticOutcome::Success {
            completion: crate::magician_v2::execution::agentic::types::CompletionKind::Full,
            open: Vec::new(),
            final_state: EnvironmentState::Uninitialized,
            iterations_used: 2,
            artifacts: vec![
                Artifact {
                    name: "research.md".to_string(),
                    content_type: "text/markdown".to_string(),
                    data: b"# Findings\nThe fund raised $40M.".to_vec(),
                    artifact_type: None,
                    render_hints: None,
                    materialized_path: None,
                },
                Artifact {
                    name: "chart.png".to_string(),
                    content_type: "image/png".to_string(),
                    data: vec![0u8, 1, 2, 255],
                    artifact_type: None,
                    render_hints: None,
                    materialized_path: None,
                },
            ],
        };
        let text = delegate_outcome_primary_text(&success)
            .expect("a text artifact should yield primary text");
        assert!(
            text.contains("The fund raised $40M"),
            "expected the sub-agent's text deliverable, got: {text}"
        );
        assert!(
            !text.contains('\u{0}'),
            "binary image bytes must not leak into the threaded deliverable"
        );

        let failed = AgenticOutcome::Failed {
            reason: "tool timed out".to_string(),
            last_state: EnvironmentState::Uninitialized,
            iterations_used: 5,
        };
        let note = delegate_outcome_primary_text(&failed)
            .expect("a Failed outcome should still surface a note so the PA root advances");
        assert!(
            note.contains("did not complete") && note.contains("tool timed out"),
            "Failed note should explain the incompletion, got: {note}"
        );
    }

    /// A `DelegationDispatcher` whose spawn always returns a HARD dispatch
    /// error, to exercise the B9 fail-loud boundary.
    #[derive(Debug, Default)]
    struct FailingDelegationDispatcher {
        available:
            Vec<crate::magician_v2::execution::agentic::delegation_dispatch::DelegationTarget>,
    }

    #[async_trait::async_trait]
    impl crate::magician_v2::execution::agentic::delegation_dispatch::DelegationDispatcher
        for FailingDelegationDispatcher
    {
        async fn available_targets(
            &self,
            _source_agent_id: &str,
            _principal: Option<&str>,
            _workspace: Option<&str>,
        ) -> Vec<crate::magician_v2::execution::agentic::delegation_dispatch::DelegationTarget>
        {
            self.available.clone()
        }

        async fn spawn_children(
            &self,
            _source_agent_id: &str,
            _source_execution_id: &str,
            _source_chain_id: Option<&str>,
            _targets: Vec<crate::magician_v2::execution::actions::DelegationTargetRequest>,
            _cancel: Option<tokio_util::sync::CancellationToken>,
        ) -> Result<
            crate::magician_v2::execution::agentic::delegation_dispatch::DelegationSpawnResult,
            crate::magician_v2::execution::agentic::delegation_dispatch::DispatchError,
        > {
            Err(crate::magician_v2::execution::agentic::delegation_dispatch::DispatchError::ServiceUnavailable)
        }
    }

    // A scoped run resolves an owner profile and settles a real terminal, and
    // that path is deeper than a plain test thread's stack. Production runs it
    // on `magician-execution-worker`; so does this, like its siblings above.
    #[test]
    fn test_spine_hard_dispatch_error_fails_loud_not_livelock() {
        let runtime = delegation_decision_runtime();
        runtime.block_on(async {
            tokio::spawn(async {
                test_spine_hard_dispatch_error_fails_loud_not_livelock_inner()
                    .heap_boxed()
                    .await;
            })
            .await
            .expect("spine dispatch-failure execution worker");
        });
    }

    /// B9 (dispatcher half): a HARD dispatch error (`ServiceUnavailable`) must
    /// abort the run as `Failed` — NOT degrade to Continue and retry the
    /// identical delegation (the runaway class, previously bounded only by
    /// max_iterations=4000). If it ever silently retries again, this fails in
    /// milliseconds instead of spinning thousands of iterations.
    async fn test_spine_hard_dispatch_error_fails_loud_not_livelock_inner() {
        let dispatcher = std::sync::Arc::new(FailingDelegationDispatcher {
            available: vec![scripted_target("web-researcher", &["web_search"])],
        });

        // The decision queue re-emits its last response forever, so without the
        // B9 fail-loud the loop would retry this delegation up to max_iterations.
        let mut run = scoped_loop_run_owned_by(
            "research X",
            "research done",
            vec![
                r#"{"decision":"delegate_to_agent","delegation_targets":[{"target_agent_id":"web-researcher","context":"research the latest fund raise"}]}"#,
            ],
            "personal-assistant",
            vec![scripted_target("web-researcher", &["web_search"])],
        )
        .heap_boxed()
        .await;
        run.executors = run.executors.with_delegation_dispatcher(dispatcher);
        // Preserve the fail-loud contract without producing thousands of
        // repeated fixture turns if the pre-dispatch boundary regresses.
        run.ctx.max_iterations = 8;

        let initial_state = EnvironmentState::Shell(ShellState::default());
        let outcome = execute_agentically(&run.ctx, initial_state, &run.executors, None)
            .await
            .expect("execute_agentically should not error");

        match outcome {
            AgenticOutcome::Failed {
                reason,
                iterations_used,
                ..
            } => {
                assert!(
                    reason.contains("Delegation dispatch failed"),
                    "expected a dispatch-failure reason, got: {reason}"
                );
                assert!(
                    iterations_used <= 2,
                    "a hard dispatch error must fail fast, not spin (got {iterations_used})"
                );
            },
            other => panic!(
                "a hard dispatch error must abort as Failed, not {other:?} (livelock regression)"
            ),
        }
    }

    // === Item 1.4: records-as-derived-sink verification ===
    //
    // Since the live-conversation inversion, `iterations`/`assistant_turns`
    // records are a DERIVED sink (the model's input is `live_messages`), but
    // several subsystems still read the records. These tests evidence-back
    // the two contract points the plan calls out explicitly: (a) terminal
    // rejection feedback must reach the model through the live array, and
    // (b) every emitted-but-unrun tool_call must fold with a deferred
    // placeholder so providers' tool_use/tool_result pairing invariant holds.
    // (Stuck-auto-yield, would-repeat, partial-success, and persistence
    // already have dedicated suites; call-frequency is pinned in decision.rs.)

    #[test]
    fn terminal_rejection_feedback_reaches_model_via_live_array() {
        use magicllm::prelude::MessageRole;
        let mut history = ExecutionHistory::new();
        let mut consecutive = 0usize;
        let observed = EnvironmentState::Shell(ShellState::default());

        let honour = handle_terminal_evidence_rejection(
            &mut history,
            &observed,
            4,
            "REJECTED-MARKER-4412: task-backed runs require evidence",
            Some("model claimed success without proof"),
            &mut consecutive,
        );
        assert!(
            !honour,
            "the first rejection must bounce, not honour the yield"
        );
        assert_eq!(
            history.iterations.len(),
            1,
            "the rejection must land as a record"
        );

        crate::magician_v2::execution::agentic::decision::sync_live_messages(&mut history);

        let last = history
            .live_messages
            .last()
            .expect("the rejection record must fold into the live conversation");
        assert_eq!(
            last.role,
            MessageRole::User,
            "the fold must end on the user (tool-result) turn"
        );
        assert_eq!(
            history.live_messages.len() % 2,
            0,
            "the fold emits whole (assistant, user) pairs — alternation preserved"
        );
        let serialized = serde_json::to_string(&history.live_messages).unwrap();
        assert!(
            serialized.contains("REJECTED-MARKER-4412"),
            "the model's next decision input must carry the rejection feedback"
        );
    }

    #[test]
    fn deferred_placeholder_present_for_every_emitted_but_unrun_tool_call() {
        use magicllm::prelude::ContentBlock;
        let mut history = ExecutionHistory::new();
        // One executed record for iteration 1 — but the assistant turn emitted
        // TWO tool calls (the second never ran: budget cut, mid-batch bail, …).
        history
            .iterations
            .push(stuck_counter_test_iteration_record(1, true));
        history.record_assistant_turn(AgenticAssistantTurnRecord {
            iteration: 1,
            operation: "agentic_decision".to_string(),
            llm_trace_context: None,
            text: Some("Running both steps.".to_string()),
            tool_calls: vec![
                AgenticAssistantToolCallRecord {
                    id: "call_ran".to_string(),
                    name: "bash".to_string(),
                    arguments: serde_json::json!({"command": "true"}),
                },
                AgenticAssistantToolCallRecord {
                    id: "call_unrun".to_string(),
                    name: "bash".to_string(),
                    arguments: serde_json::json!({"command": "false"}),
                },
            ],
            finish_reason: Some("tool_calls".to_string()),
            prompt_tokens: None,
            completion_tokens: None,
            reasoning: None,
            timestamp: chrono::Utc::now(),
        });

        crate::magician_v2::execution::agentic::decision::sync_live_messages(&mut history);

        let user_msg = history
            .live_messages
            .last()
            .expect("the turn must fold into a pair");
        let results: Vec<(&str, &serde_json::Value)> = user_msg
            .content
            .iter()
            .filter_map(|block| match block {
                ContentBlock::ToolResult {
                    tool_call_id,
                    content,
                } => Some((tool_call_id.as_str(), content)),
                _ => None,
            })
            .collect();
        assert_eq!(
            results.len(),
            2,
            "every emitted tool_call must have a matching ToolResult"
        );
        assert_eq!(results[0].0, "call_ran");
        assert_eq!(results[1].0, "call_unrun");
        assert_eq!(
            results[1].1.get("status").and_then(|v| v.as_str()),
            Some("deferred"),
            "an emitted-but-unrun tool_call must fold as the deferred placeholder"
        );
        assert_ne!(
            results[0].1.get("status").and_then(|v| v.as_str()),
            Some("deferred"),
            "the executed call must carry its real result, not a placeholder"
        );
    }

    #[test]
    fn handover_dedupe_flags_target_that_previously_yielded_cannot_proceed() {
        let mut history = ExecutionHistory::new();
        let mut failed = stuck_counter_test_iteration_record(1, false);
        failed.action = ExecutableAction::HandoverToAgent {
            target_agent_id: "research-agent".to_string(),
            context: "please research X".to_string(),
        };
        failed.result.error = Some("HandoverCannotProceed".to_string());
        history.iterations.push(failed);

        assert!(
            handover_target_previously_failed(&history, "research-agent"),
            "a repeat handover to a target that already failed must be flagged"
        );
        assert!(
            !handover_target_previously_failed(&history, "other-agent"),
            "unrelated targets must not be flagged"
        );

        // The yield-back marker form dedupes by the SOURCE agent id.
        let mut yielded_back = stuck_counter_test_iteration_record(2, false);
        yielded_back.action = ExecutableAction::HandoverToAgent {
            target_agent_id: "coordinator".to_string(),
            context: "yield_back:cannot_proceed:from=writer-agent".to_string(),
        };
        yielded_back.result.error = Some("HandoverCannotProceed".to_string());
        history.iterations.push(yielded_back);
        assert!(
            handover_target_previously_failed(&history, "writer-agent"),
            "a cannot_proceed yield-back must dedupe re-handover to its source"
        );
    }

    // === Item 1.3 (Change 2): success claims need harness-corroborated backing ===
    //
    // The narrative acceptance path of `goal_reached_has_sufficient_evidence`
    // requires ≥1 substantive successful iteration. These tests pin the
    // Change 2 tightening: an iteration the harness itself contradicted —
    // `NoEffect` (the no-effect probe fired: the act ran but moved nothing,
    // e.g. a missed drag) or a verification reporting `Mismatch`/`NoChange` —
    // cannot be that backing. `Unknown`/absent verification is NOT a negative
    // signal (non-browser actions never produce one), which is the plan's
    // over-rejection safeguard: non-browser runs keep today's evidence rules.

    fn substantive_success_record(iteration: usize) -> IterationRecord {
        let mut record = stuck_counter_test_iteration_record(iteration, true);
        record.result.output = Some(
            "Executed the drag across the slider track and re-read the handle position."
                .to_string(),
        );
        record
    }

    #[test]
    fn no_effect_iteration_cannot_back_a_narrative_success_claim() {
        let mut history = ExecutionHistory::new();
        let mut record = substantive_success_record(1);
        record.result.outcome_category = Some(ActionOutcomeCategory::NoEffect);
        record.verification = Some(ActionVerification {
            matches_expectation: VerificationMatch::NoChange,
            change_assessment: Some("progress: no_effect".to_string()),
            ..Default::default()
        });
        history.iterations.push(record);

        assert!(
            !goal_reached_has_sufficient_evidence(
                &history,
                Some("Dragged the slider to 75% and verified the task is complete now."),
                &[],
            ),
            "an iteration the harness tagged NoEffect must not back a success narrative"
        );
    }

    #[test]
    fn verification_mismatch_iteration_cannot_back_a_narrative_success_claim() {
        let mut history = ExecutionHistory::new();
        let mut record = substantive_success_record(1);
        record.verification = Some(ActionVerification {
            matches_expectation: VerificationMatch::Mismatch,
            ..Default::default()
        });
        history.iterations.push(record);

        assert!(
            !goal_reached_has_sufficient_evidence(
                &history,
                Some("Completed the requested page interaction and confirmed the outcome."),
                &[],
            ),
            "an iteration whose verification contradicted the claim must not back it"
        );
    }

    #[test]
    fn unknown_or_absent_verification_still_backs_a_narrative_success_claim() {
        // Non-browser safety pin: actions that never produce a harness
        // verification (or produce a neutral one) must keep today's
        // acceptance — the stricter rule engages only on NEGATIVE signals.
        let mut history = ExecutionHistory::new();
        history.iterations.push(substantive_success_record(1)); // verification: None
        assert!(goal_reached_has_sufficient_evidence(
            &history,
            Some("Ran the analysis over the exported data and summarised the findings."),
            &[],
        ));

        let mut neutral = substantive_success_record(2);
        neutral.verification = Some(ActionVerification::default()); // Unknown
        let mut history = ExecutionHistory::new();
        history.iterations.push(neutral);
        assert!(goal_reached_has_sufficient_evidence(
            &history,
            Some("Ran the analysis over the exported data and summarised the findings."),
            &[],
        ));
    }

    #[test]
    fn task_backed_success_claim_requires_harness_corroborated_backing() {
        let mut ctx = AgenticContext::new(
            "Adjust the range slider to 75 percent",
            "The slider reports 75 percent",
        );
        ctx.task_id = Some("task-evidence-gate".to_string());

        // Only backing: an act the harness said moved nothing → rejected.
        let mut history = ExecutionHistory::new();
        let mut no_effect = substantive_success_record(1);
        no_effect.result.outcome_category = Some(ActionOutcomeCategory::NoEffect);
        no_effect.verification = Some(ActionVerification {
            matches_expectation: VerificationMatch::NoChange,
            change_assessment: Some("progress: no_effect".to_string()),
            ..Default::default()
        });
        history.iterations.push(no_effect);

        let rejection = goal_reached_rejection_reason(
            &ctx,
            &history,
            Some("Dragged the slider handle and the task is finished as requested."),
            &[],
            true,
        )
        .expect("task-backed claim backed only by a no-effect act must be rejected");
        assert!(
            rejection.contains("task-backed runs require evidence"),
            "expected the evidence gate; got: {rejection}"
        );

        // Same run with one harness-corroborated productive act → accepted.
        history.iterations.push(substantive_success_record(2));
        assert_eq!(
            goal_reached_rejection_reason(
                &ctx,
                &history,
                Some("Dragged the slider handle and the task is finished as requested."),
                &[],
                true,
            ),
            None,
            "a clean productive iteration must keep backing task-backed claims"
        );
    }

    #[test]
    fn goal_reached_rejection_reason_rejects_incomplete_evidence() {
        let ctx = AgenticContext::new("Open the page", "The page is opened");
        let history = ExecutionHistory::new();

        let rejection = goal_reached_rejection_reason(
            &ctx,
            &history,
            Some("Need to proceed by executing the test actions before this is complete."),
            &[],
            true,
        );

        assert!(rejection
            .as_deref()
            .is_some_and(|reason| reason.contains("evidence still says more work is needed")));
    }

    /// The judge is told what the agent DID, across every tool — not just the
    /// pages that happen to feed the source excerpt.
    ///
    /// It used to receive only the claim-eligible `content_read` tally under a
    /// field the prompt renders as the record's observed actions. A draft that
    /// truthfully mentioned any other step therefore read as an invented claim,
    /// and runs were rejected for accurately reporting work they had done.
    #[test]
    fn grounding_observed_actions_report_every_tool_the_run_invoked() {
        use crate::magician_v2::execution::actions::ExecutableAction;
        use std::collections::HashMap;

        fn pack(name: &str, success: bool) -> IterationRecord {
            IterationRecord {
                iteration: 1,
                timestamp: chrono::Utc::now(),
                state_before: EnvironmentState::Uninitialized,
                action: ExecutableAction::Pack {
                    capability_name: name.to_string(),
                    implementation:
                        crate::magician_v2::execution::capability::ImplementationType::Compiled {
                            provider_name: "p".to_string(),
                        },
                    resolved_params: HashMap::new(),
                },
                result: ActionResultRecord {
                    success,
                    output: None,
                    error: (!success).then(|| "boom".to_string()),
                    duration_ms: 1,
                    outcome_category: None,
                    api_replay_used: None,
                    api_replay_time_ms: None,
                    browser_fallback_reason: None,
                    tool_result_projection: None,
                },
                state_after: EnvironmentState::Uninitialized,
                verification: None,
                llm_reasoning: None,
            }
        }

        let mut history = ExecutionHistory::new();
        history.iterations.push(pack("content_search", true));
        history.iterations.push(pack("content_read", true));
        history.iterations.push(pack("content_read", true));
        history.iterations.push(pack("browser__open", false));

        let observed = terminal_grounding_observed_actions(&history);
        assert_eq!(
            observed,
            vec![
                "content_search x1".to_string(),
                "content_read x2".to_string(),
                "browser__open x0 (1 failed)".to_string(),
            ],
            "a search the run really performed must not be missing from what the judge is shown"
        );
    }

    /// A PARTIAL yield may say its deliverable is unfinished — that is the
    /// whole content of a partial — while a CLEAN completion claim may not.
    ///
    /// The deliverable-gap needles ("was not produced", "remains blocked") are
    /// the vocabulary of an honest `open[]`. Applying them to a partial
    /// rejected the agent for being accurate: it reported real completed work
    /// plus a named gap, the gate read the gap as a false completion claim, and
    /// the loop bounced it until the strike cap turned a good partial answer
    /// into a total failure with no output at all.
    #[test]
    fn deliverable_gap_gate_applies_to_completion_claims_not_partials() {
        let mut ctx = AgenticContext::new("Compare two releases", "Both releases compared");
        ctx.task_id = Some("task_partial_gate".to_string());
        let history = ExecutionHistory::new();
        let evidence = "Python verified.\n\nCOMPLETED:\n- Python release confirmed\n\nBLOCKED:\n- \
                        the Rust deliverable was not produced\n";

        assert!(
            goal_reached_rejection_reason(&ctx, &history, Some(evidence), &[], true).is_some(),
            "a CLEAN completion claim may not also say its deliverable is missing"
        );
        assert!(
            goal_reached_rejection_reason(&ctx, &history, Some(evidence), &[], false).is_none(),
            "a PARTIAL yield exists to name the gap; naming it must not be a rejection"
        );
    }

    /// A call that already failed with identical arguments cannot succeed by
    /// being repeated, and the message must say what the failure is evidence
    /// of — otherwise the model reads its own failed fetch as a fact about the
    /// world.
    #[test]
    fn repeated_failed_action_is_rejected_with_the_call_versus_data_distinction() {
        use crate::magician_v2::execution::actions::ExecutableAction;
        use std::collections::HashMap;

        let mut params: HashMap<String, Value> = HashMap::new();
        params.insert("url".to_string(), Value::String("https://example/x".into()));
        let implementation =
            crate::magician_v2::execution::capability::ImplementationType::Compiled {
                provider_name: "browser".to_string(),
            };
        let action = ExecutableAction::Pack {
            capability_name: "browser__open".to_string(),
            implementation: implementation.clone(),
            resolved_params: params.clone(),
        };

        let mut history = ExecutionHistory::new();
        assert!(
            repeated_failed_action_rejection(&history, &action).is_none(),
            "a first attempt is not a repeat"
        );

        history.iterations.push(IterationRecord {
            iteration: 1,
            timestamp: chrono::Utc::now(),
            state_before: EnvironmentState::Uninitialized,
            action: action.clone(),
            result: ActionResultRecord {
                success: false,
                output: None,
                error: Some("page could not be opened".to_string()),
                duration_ms: 10,
                outcome_category: Some(ActionOutcomeCategory::Failed),
                api_replay_used: None,
                api_replay_time_ms: None,
                browser_fallback_reason: None,
                tool_result_projection: None,
            },
            state_after: EnvironmentState::Uninitialized,
            verification: None,
            llm_reasoning: None,
        });

        let rejection = repeated_failed_action_rejection(&history, &action)
            .expect("a repeat of a failed call must be rejected");
        assert!(rejection.contains("page could not be opened"));
        assert!(
            rejection.contains("evidence about the CALL"),
            "the message must separate a failed call from an absent fact"
        );

        // A different target is a different strategy, not a repeat.
        let mut other_params: HashMap<String, Value> = HashMap::new();
        other_params.insert("url".to_string(), Value::String("https://example/y".into()));
        let other = ExecutableAction::Pack {
            capability_name: "browser__open".to_string(),
            implementation,
            resolved_params: other_params,
        };
        assert!(
            repeated_failed_action_rejection(&history, &other).is_none(),
            "changing the arguments is exactly the behaviour the guard asks for"
        );
    }

