    #[test]
    fn successful_iteration_credits_goal_call_by_tool_name() {
        // Reinforcement: a goal "call fetch_report()" is satisfied by a
        // successful iteration whose ACTION tool name is `fetch_report`, even
        // though the iteration output never contains the literal `fetch_report()`.
        let record = IterationRecord {
            iteration: 1,
            timestamp: chrono::Utc::now(),
            state_before: EnvironmentState::Uninitialized,
            state_after: EnvironmentState::Uninitialized,
            action: ExecutableAction::Pack {
                capability_name: "fetch_report".to_string(),
                implementation:
                    crate::magician_v2::execution::capability::ImplementationType::Compiled {
                        provider_name: "reports".to_string(),
                    },
                resolved_params: HashMap::new(),
            },
            result: ActionResultRecord {
                success: true,
                // Deliberately does NOT contain the literal `fetch_report()`.
                output: Some("The quarterly report was retrieved successfully.".to_string()),
                error: None,
                duration_ms: 12,
                outcome_category: None,
                api_replay_used: None,
                api_replay_time_ms: None,
                browser_fallback_reason: None,
                tool_result_projection: None,
            },
            verification: None,
            llm_reasoning: None,
        };

        assert!(
            successful_iteration_invokes_js_call(&record, "fetch_report()"),
            "a successful iteration whose action tool name is `fetch_report` must satisfy the \
             goal call by tool-name"
        );

        // And it also works when the capability name is leaf-suffixed
        // (`<pack>__<action>`) — match the trailing leaf.
        let leaf_suffixed = IterationRecord {
            action: ExecutableAction::Pack {
                capability_name: "reports__fetch_report".to_string(),
                implementation:
                    crate::magician_v2::execution::capability::ImplementationType::Compiled {
                        provider_name: "reports".to_string(),
                    },
                resolved_params: HashMap::new(),
            },
            ..record.clone()
        };
        assert!(
            successful_iteration_invokes_js_call(&leaf_suffixed, "fetch_report()"),
            "a leaf-suffixed capability name (`reports__fetch_report`) must satisfy the goal call \
             by its `__`-leaf"
        );

        // A FAILED iteration with the matching tool name must NOT satisfy it.
        let mut failed = record.clone();
        failed.result.success = false;
        assert!(
            !successful_iteration_invokes_js_call(&failed, "fetch_report()"),
            "a failed iteration must not satisfy the goal call even with a matching tool name"
        );
    }

