    #[test]
    fn terminal_grounding_deduplicates_a_source_and_keeps_its_latest_read() {
        let mut stale = successful_pack_iteration("content_read");
        stale.result.output = Some(
            serde_json::json!({
                "status": "complete",
                "fetch_status": "complete",
                "evidence_role": "opened_page",
                "claim_eligible": true,
                "url": "https://same.example/pricing?utm_source=old-crawl",
                "document": {
                    "canonical_url": "https://same.example/pricing",
                    "text": "STALE_PRICE $99.00"
                }
            })
            .to_string(),
        );
        let mut refreshed = successful_pack_iteration("content_read");
        refreshed.iteration = 2;
        refreshed.result.output = Some(
            serde_json::json!({
                "status": "complete",
                "fetch_status": "complete",
                "evidence_role": "opened_page",
                "claim_eligible": true,
                "url": "https://same.example/pricing?utm_source=new-crawl#prices",
                "document": {
                    "canonical_url": "https://same.example/pricing",
                    "text": "CURRENT_PRICE $2.00"
                }
            })
            .to_string(),
        );

        let history = ExecutionHistory {
            iterations: vec![stale, refreshed],
            ..ExecutionHistory::new()
        };
        let evidence = terminal_grounding_evidence(&history, "").expect("opened evidence");

        assert_eq!(evidence.successful_reads, 1, "reads count distinct sources");
        assert!(evidence.source_excerpt.contains("CURRENT_PRICE"));
        assert!(!evidence.source_excerpt.contains("STALE_PRICE"));
        assert!(evidence.source_excerpt.contains("OPENED PAGE EVIDENCE 1/1"));
        assert!(evidence
            .source_excerpt
            .contains("source=url:https://same.example/pricing"));
    }

