    fn grounding_evidence(
        source_excerpt: String,
        successful_reads: usize,
        failed_reads: usize,
    ) -> TerminalGroundingEvidence {
        TerminalGroundingEvidence {
            evidence_fingerprint: blake3::hash(source_excerpt.as_bytes()).to_hex().to_string(),
            source_excerpt,
            successful_reads,
            failed_reads,
            non_admissible_retrievals: 0,
            coverage: Vec::new(),
        }
    }

    #[test]
    fn terminal_grounding_repair_ends_when_a_resubmit_brings_no_new_evidence() {
        let evidence = grounding_evidence("authoritative evidence A".to_string(), 1, 1);
        let mut state = TerminalGroundingRepairState::default();

        let first = terminal_grounding_repair_decision(
            &mut state,
            "a material claim is unsupported",
            &evidence,
        );
        assert!(match first {
            TerminalGroundingRepairDecision::Continue(reason) => {
                reason.contains("Decide agentically")
            },
            TerminalGroundingRepairDecision::Exhausted(_) => false,
        });
        assert_eq!(state.rejected_drafts, 1);

        // Same evidence again: no strike is spent, the repair simply ends.
        let second = terminal_grounding_repair_decision(
            &mut state,
            "the claim is still unsupported",
            &evidence,
        );
        assert!(match second {
            TerminalGroundingRepairDecision::Exhausted(reason) => {
                reason.contains("No new claim-eligible opened-page evidence")
            },
            TerminalGroundingRepairDecision::Continue(_) => false,
        });
        assert_eq!(
            state.rejected_drafts,
            MAX_TERMINAL_GROUNDING_REJECTED_DRAFTS
        );
    }

    #[test]
    fn terminal_grounding_repair_spends_one_strike_per_advance() {
        let mut state = TerminalGroundingRepairState::default();
        let mut decisions = Vec::new();
        for round in 0..MAX_TERMINAL_GROUNDING_REJECTED_DRAFTS {
            let evidence = grounding_evidence(format!("evidence set {round}"), round + 1, 0);
            decisions.push(terminal_grounding_repair_decision(
                &mut state,
                "still unsupported",
                &evidence,
            ));
        }
        let (last, earlier) = decisions.split_last().expect("at least one round");
        assert!(earlier
            .iter()
            .all(|decision| matches!(decision, TerminalGroundingRepairDecision::Continue(_))));
        assert!(matches!(
            last,
            TerminalGroundingRepairDecision::Exhausted(_)
        ));
        assert_eq!(
            state.rejected_drafts,
            MAX_TERMINAL_GROUNDING_REJECTED_DRAFTS
        );
    }

    #[test]
    fn terminal_grounding_route_caveats_absent_claims_only_when_coverage_is_incomplete() {
        use crate::magician_v2::evidence::{PrecisionVerdict, UnsupportedKind};
        let verdict = |kind: Option<UnsupportedKind>| PrecisionVerdict {
            evidence_id: "terminal-draft:test".to_string(),
            faithful: false,
            reason: "the source does not mention the second release".to_string(),
            unsupported_kind: kind,
            declared_open: Vec::new(),
        };
        let mut full_coverage = grounding_evidence("evidence".to_string(), 2, 0);
        let mut partial_coverage = grounding_evidence("evidence".to_string(), 2, 0);
        partial_coverage.non_admissible_retrievals = 1;
        partial_coverage.coverage = vec![
            "novel_reader: 1 retrieval(s) with no evidence envelope (content NOT in the source)"
                .to_string(),
        ];

        assert!(matches!(
            terminal_grounding_route(&verdict(Some(UnsupportedKind::Absent)), &partial_coverage),
            TerminalGroundingRoute::Caveat(reason) if reason.contains("novel_reader")
        ));
        assert_eq!(
            terminal_grounding_route(&verdict(Some(UnsupportedKind::Absent)), &full_coverage),
            TerminalGroundingRoute::Repair
        );
        assert_eq!(
            terminal_grounding_route(
                &verdict(Some(UnsupportedKind::Contradicted)),
                &partial_coverage
            ),
            TerminalGroundingRoute::Repair
        );
        // A judge that does not say which kind is treated conservatively.
        assert_eq!(
            terminal_grounding_route(&verdict(None), &partial_coverage),
            TerminalGroundingRoute::Repair
        );
        full_coverage.non_admissible_retrievals = 0;
        let faithful = PrecisionVerdict {
            faithful: true,
            ..verdict(None)
        };
        assert_eq!(
            terminal_grounding_route(&faithful, &full_coverage),
            TerminalGroundingRoute::Accept
        );
    }

    #[test]
    fn degrade_yield_to_partial_keeps_completed_work_and_adds_the_caveat_once() {
        use crate::magician_v2::execution::agentic::yield_decision::{
            YieldDecision, YieldDisposition,
        };
        let mut payload = YieldDecision {
            summary: "both branches verified".to_string(),
            completed: vec!["Rust release verified".to_string()],
            ..YieldDecision::default()
        };
        let disposition = degrade_yield_to_partial(&mut payload, " unverified: coverage ");
        assert!(matches!(
            disposition,
            YieldDisposition::PartialSuccess {
                completed_count: 1,
                open_count: 1,
                ..
            }
        ));
        let again = degrade_yield_to_partial(&mut payload, "unverified: coverage");
        assert!(matches!(
            again,
            YieldDisposition::PartialSuccess { open_count: 1, .. }
        ));
        assert_eq!(payload.completed, vec!["Rust release verified".to_string()]);
    }

    #[test]
    fn terminal_grounding_admits_envelope_evidence_from_any_tool_and_only_by_shape() {
        // A tool the walk has never heard of, whose result carries the envelope.
        let mut novel = successful_pack_iteration("novel_reader");
        novel.result.output = Some(
            serde_json::json!({
                "fetch_status": "complete",
                "evidence_role": "opened_page",
                "claim_eligible": true,
                "document": {
                    "canonical_url": "https://example.org/release",
                    "text": "NOVEL_TOOL_FACT 1.98.1"
                }
            })
            .to_string(),
        );
        // The governed reader, returning a document WITHOUT the envelope.
        let mut bare = successful_pack_iteration("content_read");
        bare.result.output = Some(
            serde_json::json!({
                "status": "complete",
                "document": {
                    "canonical_url": "https://example.org/bare",
                    "text": "BARE_FACT must not be admitted"
                }
            })
            .to_string(),
        );
        let history = ExecutionHistory {
            iterations: vec![novel, bare],
            ..ExecutionHistory::new()
        };

        let evidence = terminal_grounding_evidence(&history, "").expect("envelope evidence");

        assert_eq!(evidence.successful_reads, 1);
        assert!(evidence.source_excerpt.contains("NOVEL_TOOL_FACT"));
        assert!(!evidence.source_excerpt.contains("BARE_FACT"));
        assert_eq!(evidence.non_admissible_retrievals, 1);
        assert!(evidence.coverage_is_incomplete());
        assert!(
            evidence
                .coverage
                .iter()
                .any(|line| line.starts_with("content_read:")
                    && line.contains("no evidence envelope"))
        );
        assert!(evidence
            .coverage
            .iter()
            .any(|line| line.starts_with("novel_reader:") && line.contains("1 admissible")));
    }

