    #[test]
    fn schema_gate_rejects_artifact_missing_required_field() {
        // Simulates the 5-questions task: declared schema requires
        // q1..q5; agent's artifact only carries q1..q4. Schema gate
        // must reject with a path-precise message so the LLM knows
        // q5 is missing.
        use crate::magician_v2::agents::types::ArtifactDeclaration;
        let mut ctx =
            AgenticContext::new("Answer 5 metabase questions", "All 5 questions answered");
        ctx.task_id = Some("task-q5".to_string());
        ctx.expected_artifact_declarations = vec![ArtifactDeclaration {
            name: "answers.json".to_string(),
            artifact_type: "json".to_string(),
            source: None,
            content_type: Some("application/json".to_string()),
            schema: Some(json!({
                "type": "object",
                "required": ["q1", "q2", "q3", "q4", "q5"]
            })),
            render_hints: None,
            enrichment_only: false,
        }];
        let history = ExecutionHistory::new();
        let artifact = crate::magician_v2::execution::agentic::types::Artifact::text(
            "answers.json",
            r#"{"q1":"a","q2":"b","q3":"c","q4":"d"}"#,
        );

        let rejection = goal_reached_rejection_reason(
            &ctx,
            &history,
            Some("All five answered."),
            &[artifact],
            true,
        )
        .expect("schema gate must reject missing q5");
        assert!(
            rejection.contains("schema validation"),
            "rejection must mention schema validation; got: {rejection}"
        );
        assert!(
            rejection.contains("q5"),
            "rejection must name the missing field; got: {rejection}"
        );
    }

