    #[test]
    fn schema_gate_skips_when_no_artifact_with_declared_name() {
        // No artifact named `answers.json` present → schema gate
        // doesn't fire (the upstream evidence gate handles missing
        // artifacts). This isolates schema validation from
        // artifact-presence concerns.
        use crate::magician_v2::agents::types::ArtifactDeclaration;
        let mut ctx = AgenticContext::new("Answer 5 questions", "Done");
        ctx.task_id = Some("task-skip".to_string());
        ctx.expected_artifact_declarations = vec![ArtifactDeclaration {
            name: "answers.json".to_string(),
            artifact_type: "json".to_string(),
            source: None,
            content_type: Some("application/json".to_string()),
            schema: Some(json!({"type": "object", "required": ["q1"]})),
            render_hints: None,
            enrichment_only: false,
        }];
        let history = ExecutionHistory::new();
        // Provide a DIFFERENT artifact so the upstream evidence
        // gate doesn't fire.
        let unrelated = crate::magician_v2::execution::agentic::types::Artifact::text(
            "other_notes.md",
            "just some notes",
        );

        let rejection =
            goal_reached_rejection_reason(&ctx, &history, Some("Done."), &[unrelated], true);
        assert!(
            rejection.is_none(),
            "missing declared artifact must not trigger schema rejection; got: {rejection:?}"
        );
    }

