    #[test]
    fn input_sensitivity_round_trips_on_the_context_and_the_pause_state() {
        use crate::magician_v2::user_requests::SensitiveKind;
        // The in-memory context carries it (it is not itself a persisted type).
        let ctx = AgenticContext::new("Log in", "Logged in").with_input_sensitivity(HashMap::from(
            [("text_input".to_string(), SensitiveKind::Otp)],
        ));
        assert_eq!(
            ctx.resolved_input_sensitivity.get("text_input"),
            Some(&SensitiveKind::Otp)
        );

        // The persisted continuation frame carries it too, so a second pause
        // after a first sensitive answer does not forget the decision.
        let mut frame = AgenticContinuationFrame {
            kind: AgenticContinuationKind::SameOwnerSubGoal,
            goal: "Log in".into(),
            success_criteria: "Logged in".into(),
            remaining_iterations: 1,
            max_repeated_actions: 3,
            iteration_offset: 0,
            depth: 0,
            work_budget_secs: None,
            work_budget_consumed_ms: 0,
            nested_work_budget_baseline_ms: 0,
            loop_protective_state: None,
            step_id: None,
            pending_inputs: Vec::new(),
            resolved_inputs: HashMap::new(),
            resolved_input_sensitivity: HashMap::new(),
            asking_for_parameter: None,
            prior_environment_knowledge: None,
            action_history_summary: String::new(),
            approved_confirmation_actions: Vec::new(),
            active_owner_agent_id: None,
            owner_stack: Vec::new(),
            owner_invocation_stack: Vec::new(),
            invocation_context_override: None,
        };
        let json = serde_json::to_value(&frame).unwrap();
        assert!(
            json.get("resolved_input_sensitivity").is_none(),
            "empty map is not serialized"
        );
        frame
            .resolved_input_sensitivity
            .insert("password".to_string(), SensitiveKind::Password);
        let json = serde_json::to_value(&frame).unwrap();
        let back: AgenticContinuationFrame = serde_json::from_value(json).unwrap();
        assert_eq!(
            back.resolved_input_sensitivity.get("password"),
            Some(&SensitiveKind::Password)
        );
    }

    #[test]
    fn sensitivity_of_a_resumed_answer_is_decided_at_collection() {
        use crate::magician_v2::user_requests::SensitiveKind;
        let text = UserInputType::Text {
            placeholder: None,
            multiline: false,
        };
        let password = UserInputResponse::new(
            UserInputType::Password { placeholder: None },
            UserInputValue::Password { value: "x".into() },
        );
        assert_eq!(
            collected_input_sensitivity(&password, None, None, None, None),
            Some(SensitiveKind::Password)
        );
        let otp = UserInputResponse::new(
            text.clone(),
            UserInputValue::Text {
                value: "123456".into(),
            },
        );
        assert_eq!(
            collected_input_sensitivity(
                &otp,
                None,
                None,
                Some("Enter the verification code we sent"),
                None
            ),
            Some(SensitiveKind::Otp)
        );
        let secret_wording =
            UserInputResponse::new(text.clone(), UserInputValue::Text { value: "x".into() });
        assert_eq!(
            collected_input_sensitivity(
                &secret_wording,
                None,
                None,
                Some("What is your account PIN?"),
                None
            ),
            Some(SensitiveKind::Other)
        );
        let plain = UserInputResponse::new(
            text,
            UserInputValue::Text {
                value: "Lisbon".into(),
            },
        );
        assert_eq!(
            collected_input_sensitivity(&plain, None, None, Some("Which city?"), None),
            None
        );
    }

    // ---- P3 Task 3.1: the spec is decided at pause time and published -----

    #[test]
    fn a_pause_decides_its_spec_the_way_the_request_service_would() {
        use crate::magician_v2::execution::agentic::types::FormQuestion;
        use crate::magician_v2::user_requests::{SensitiveKind, SensitiveProvenance};
        const NOW: i64 = 1_700_000_000_000;
        let text = UserInputType::Text {
            placeholder: None,
            multiline: false,
        };

        let password = sensitive_spec_for_pause(
            &UserInputType::Password { placeholder: None },
            "Your password",
            None,
            None,
            &[],
            NOW,
        )
        .expect("a password widget is always sensitive");
        assert_eq!(
            (password.kind, password.provenance, password.one_time),
            (
                Some(SensitiveKind::Password),
                SensitiveProvenance::TypedInput,
                false
            )
        );
        assert_eq!(password.collection_deadline_ms, NOW + 24 * 60 * 60 * 1000);

        let otp = sensitive_spec_for_pause(
            &text,
            "Enter the verification code we sent",
            None,
            None,
            &[],
            NOW,
        )
        .expect("OTP wording is one-time material");
        assert_eq!(
            (otp.kind, otp.provenance, otp.one_time),
            (
                Some(SensitiveKind::Otp),
                SensitiveProvenance::Heuristic,
                true
            )
        );
        assert_eq!(
            otp.collection_deadline_ms,
            NOW + 180_000,
            "one-time collection is clamped like the service does"
        );

        let by_name = sensitive_spec_for_pause(&text, "Value?", None, Some("api_key"), &[], NOW)
            .expect("a secret-named parameter is conservatively sensitive");
        assert_eq!(
            (by_name.kind, by_name.provenance),
            (Some(SensitiveKind::Other), SensitiveProvenance::Heuristic)
        );

        let form = UserInputType::Form {
            questions: vec![
                FormQuestion {
                    id: "user".into(),
                    prompt: "Username".into(),
                    input_type: "text".into(),
                    options: vec![],
                },
                FormQuestion {
                    id: "pw".into(),
                    prompt: "Password".into(),
                    input_type: "text".into(),
                    options: vec![],
                },
                FormQuestion {
                    id: "city".into(),
                    prompt: "City".into(),
                    input_type: "text".into(),
                    options: vec![],
                },
            ],
        };
        let spec = sensitive_spec_for_pause(&form, "Sign in", None, None, &[], NOW)
            .expect("a form with a password");
        assert_eq!(spec.kind, None);
        assert_eq!(spec.provenance, SensitiveProvenance::FormSchema);
        let mut fields: Vec<(String, SensitiveKind)> =
            spec.fields.iter().map(|f| (f.id.clone(), f.kind)).collect();
        fields.sort_by(|a, b| a.0.cmp(&b.0));
        assert_eq!(
            fields,
            vec![
                ("pw".to_string(), SensitiveKind::Password),
                ("user".to_string(), SensitiveKind::LoginIdentifier)
            ]
        );

        for decision_only in [
            UserInputType::Confirmation {
                confirm_label: None,
                deny_label: None,
                destructive: false,
            },
            UserInputType::Choice {
                options: vec![ChoiceOption::new("pin", "Pin the token")],
                allow_other: false,
            },
            UserInputType::ExternalAction {
                instructions: "Enter your password on the device".into(),
                done_label: None,
            },
            UserInputType::ToolAuthorization {
                tool_name: "secret_tool".into(),
                params_summary: "token".into(),
            },
        ] {
            assert!(
                sensitive_spec_for_pause(
                    &decision_only,
                    "Provide the secret token now",
                    None,
                    Some("password"),
                    &[],
                    NOW
                )
                .is_none(),
                "a decision prompt is never classified: {decision_only:?}"
            );
        }
        assert!(
            sensitive_spec_for_pause(&text, "Which city?", None, Some("city"), &[], NOW).is_none()
        );
    }

    #[test]
    fn the_announcement_schema_carries_the_spec_and_the_pause_state_persists_it() {
        use crate::magician_v2::user_requests::{
            SensitiveInputSpec, SensitiveKind, SensitiveProvenance,
        };
        let spec = SensitiveInputSpec {
            kind: Some(SensitiveKind::Otp),
            fields: Vec::new(),
            provenance: SensitiveProvenance::TypedInput,
            one_time: true,
            collection_deadline_ms: 1_700_000_180_000,
            challenge_id: None,
            revision: 0,
            expected_destination: None,
        };
        let input_type = UserInputType::Text {
            placeholder: Some("6 digits".into()),
            multiline: false,
        };
        let schema = hitl_input_schema_for_pause(&input_type, Some(&spec), false).unwrap();
        assert_eq!(schema["sensitive"]["kind"], "otp");
        assert_eq!(schema["sensitive"]["one_time"], true);
        assert_eq!(
            schema["placeholder"], "6 digits",
            "the typed schema is still there"
        );
        let protected = hitl_input_schema_for_pause(&input_type, Some(&spec), true).unwrap();
        assert_eq!(protected["protected"], true);
        assert_eq!(
            protected["sensitive"]["kind"], "otp",
            "a protected app still masks by the spec"
        );
        assert!(
            protected.get("placeholder").is_none(),
            "and still hides the question's details"
        );
        assert!(hitl_input_schema_for_pause(&input_type, None, false)
            .unwrap()
            .get("sensitive")
            .is_none());

        let mut state = test_pause_state();
        assert!(serde_json::to_value(&state)
            .unwrap()
            .get("pending_sensitive")
            .is_none());
        state.pending_sensitive = Some(spec.clone());
        let json = serde_json::to_value(&state).unwrap();
        let back: AgenticPauseState = serde_json::from_value(json).unwrap();
        assert_eq!(back.pending_sensitive, Some(spec));
    }

