    #[test]
    fn persisted_resolved_inputs_blank_flagged_values_not_only_secret_named_ones() {
        use crate::magician_v2::user_requests::SensitiveKind;
        let pending = vec![
            PendingInput::from_planning(
                "input-code",
                "code",
                None,
                Some("Enter the verification code".into()),
            ),
            PendingInput::from_planning("input-login", "login", None, Some("Log in".into())),
            PendingInput::from_planning("input-city", "city", None, Some("Which city?".into())),
        ];
        let resolved = HashMap::from([
            (
                "input-code".to_string(),
                Value::String("p19-otp-canary-24".into()),
            ),
            (
                "input-login".to_string(),
                serde_json::json!([
                    { "id": "pw", "value": "p19-pw-canary-25" },
                    { "id": "remember", "value": "yes" }
                ]),
            ),
            ("input-city".to_string(), Value::String("Lisbon".into())),
        ]);
        let sensitivity = HashMap::from([
            ("input-code".to_string(), SensitiveKind::Otp),
            ("input-login.pw".to_string(), SensitiveKind::Password),
        ]);
        let persisted = persisted_resolved_inputs(&pending, &resolved, &sensitivity);
        let rendered = serde_json::to_string(&persisted).unwrap();
        assert!(!rendered.contains("p19-otp-canary-24"), "{rendered}");
        assert!(!rendered.contains("p19-pw-canary-25"), "{rendered}");
        assert!(rendered.contains("Lisbon"), "{rendered}");
        assert!(
            rendered.contains("remember"),
            "ordinary form fields persist: {rendered}"
        );
    }

    #[test]
    fn a_resumed_answer_flagged_at_collection_skips_interpretation() {
        let text = UserInputType::Text {
            placeholder: None,
            multiline: false,
        };
        let code = PendingInput::from_planning("input-code", "code", None, None);
        let response = UserInputResponse::new(
            text.clone(),
            UserInputValue::Text {
                value: "123456".into(),
            },
        );
        assert!(resumed_answer_skips_interpretation(
            &code,
            &response,
            Some("Enter the verification code we sent"),
            None,
            None
        ));
        let city = PendingInput::from_planning("input-city", "city", None, None);
        let response = UserInputResponse::new(
            text.clone(),
            UserInputValue::Text {
                value: "Lisbon".into(),
            },
        );
        assert!(!resumed_answer_skips_interpretation(
            &city,
            &response,
            Some("Which city?"),
            None,
            None
        ));
        // A spec the wording rules would NOT derive — a producer's own, or one
        // from a classifier that has since changed — decides on its own, or the
        // raw value would reach the LLM interpreter and the re-ask card while
        // the answer summary redacted it.
        let spec = crate::magician_v2::user_requests::SensitiveInputSpec {
            kind: Some(crate::magician_v2::user_requests::SensitiveKind::Other),
            fields: Vec::new(),
            provenance: crate::magician_v2::user_requests::SensitiveProvenance::Producer,
            one_time: false,
            collection_deadline_ms: i64::MAX,
            challenge_id: None,
            revision: 0,
            expected_destination: None,
        };
        let response = UserInputResponse::new(
            text,
            UserInputValue::Text {
                value: "Lisbon".into(),
            },
        );
        assert!(resumed_answer_skips_interpretation(
            &city,
            &response,
            Some("Which city?"),
            None,
            Some(&spec)
        ));
        assert!(should_redact_retry_previous_answer(
            &UserInputType::Text {
                placeholder: None,
                multiline: false
            },
            Some("city"),
            &[],
            Some("Which city?"),
            None,
            Some(&spec)
        ));
    }

    #[test]
    fn form_summary_placeholder_matches_the_vault_key() {
        let questions = vec![
            crate::magician_v2::execution::agentic::types::FormQuestion {
                id: "password".into(),
                prompt: "Password".into(),
                input_type: "password".into(),
                options: vec![],
            },
            crate::magician_v2::execution::agentic::types::FormQuestion {
                id: "remember".into(),
                prompt: "Remember me?".into(),
                input_type: "text".into(),
                options: vec![],
            },
        ];
        let answer =
            |id: &str, value: &str| crate::magician_v2::execution::agentic::types::FormAnswer {
                id: id.into(),
                skipped: false,
                value: Some(value.into()),
                selected_ids: vec![],
            };
        let response = UserInputResponse::new(
            UserInputType::Form { questions },
            UserInputValue::Form {
                answers: vec![
                    answer("password", "p19-form-canary-26"),
                    answer("remember", "yes"),
                ],
            },
        );
        let summary = format_user_input_for_llm_with_pending(
            &response,
            Some("login"),
            None,
            None,
            None,
            false,
        );
        assert!(
            summary.contains(&redacted_placeholder("login.password")),
            "{summary}"
        );
        assert!(!summary.contains("p19-form-canary-26"), "{summary}");
        let summary =
            format_user_input_for_llm_with_pending(&response, None, None, None, None, false);
        assert!(
            summary.contains(&redacted_placeholder("form.password")),
            "{summary}"
        );
    }

    #[test]
    fn form_field_sensitivity_is_decided_from_the_questions() {
        use crate::magician_v2::user_requests::SensitiveKind;
        let question = |id: &str, prompt: &str, input_type: &str| {
            crate::magician_v2::execution::agentic::types::FormQuestion {
                id: id.into(),
                prompt: prompt.into(),
                input_type: input_type.into(),
                options: vec![],
            }
        };
        let questions = vec![
            question("email", "Email address", "text"),
            question("pw", "Password", "password"),
            question("remember", "Remember me?", "choice"),
        ];
        let mut flagged = collected_form_field_sensitivity(&questions);
        flagged.sort_by(|a, b| a.0.cmp(&b.0));
        assert_eq!(
            flagged,
            vec![
                ("email".to_string(), SensitiveKind::LoginIdentifier),
                ("pw".to_string(), SensitiveKind::Password),
            ]
        );
        // No password → an email is ordinary.
        let questions = vec![
            question("email", "Recipient email", "text"),
            question("cc", "Cc?", "text"),
        ];
        assert!(collected_form_field_sensitivity(&questions).is_empty());
    }

