    #[test]
    fn collect_browser_storage_for_origin_prefers_current_page_session_storage() {
        let browser_state = json!({
            "storage": [
                {
                    "tabId": 1,
                    "url": "https://app.example.com/home",
                    "localStorage": { "refresh": "refresh-1" },
                    "sessionStorage": { "csrf": "csrf-home" }
                },
                {
                    "tabId": 2,
                    "url": "https://app.example.com/settings",
                    "localStorage": { "feature_flag": "enabled" },
                    "sessionStorage": { "csrf": "csrf-settings" }
                },
                {
                    "tabId": 3,
                    "url": "https://other.example.com/",
                    "localStorage": { "ignored": "value" },
                    "sessionStorage": { "ignored": "value" }
                }
            ]
        });

        let (local_storage, session_storage) = collect_browser_storage_for_origin(
            Some(&browser_state),
            "https://app.example.com",
            Some("https://app.example.com/settings"),
        );

        assert_eq!(
            local_storage.get("refresh").map(String::as_str),
            Some("refresh-1")
        );
        assert_eq!(
            local_storage.get("feature_flag").map(String::as_str),
            Some("enabled")
        );
        assert_eq!(
            session_storage.get("csrf").map(String::as_str),
            Some("csrf-settings")
        );
        assert_eq!(session_storage.len(), 1);
    }

