    #[test]
    fn validation_session_context_for_url_uses_url_scoped_cookies() {
        let (_dir, store) = new_test_secret_store();
        let origin = "https://example.com";

        store
            .store_captured(
                origin,
                HashMap::new(),
                vec![
                    CookieWithMetadata {
                        name: "session".to_string(),
                        value: "api-cookie".to_string(),
                        domain: "example.com".to_string(),
                        path: "/api".to_string(),
                        secure: true,
                        http_only: false,
                        same_site: SameSite::Lax,
                        expires: None,
                    },
                    CookieWithMetadata {
                        name: "session".to_string(),
                        value: "metrics-cookie".to_string(),
                        domain: "example.com".to_string(),
                        path: "/metrics".to_string(),
                        secure: true,
                        http_only: false,
                        same_site: SameSite::Lax,
                        expires: None,
                    },
                ],
                HashMap::new(),
                HashMap::new(),
            )
            .expect("captured auth should store");

        let mut cache = HashMap::new();
        let api_ctx = validation_session_context_for_url(
            Some(&store),
            &mut cache,
            "https://example.com/api/users",
        );
        let metrics_ctx = validation_session_context_for_url(
            Some(&store),
            &mut cache,
            "https://example.com/metrics/ping",
        );

        assert_eq!(
            api_ctx.cookie_header_string().as_deref(),
            Some("session=api-cookie")
        );
        assert_eq!(
            metrics_ctx.cookie_header_string().as_deref(),
            Some("session=metrics-cookie")
        );
    }

    #[test]
    fn store_observed_browser_session_state_fans_out_cookies_to_traced_origins() {
        let (_dir, store) = new_test_secret_store();
        let mining_dir = tempfile::tempdir().expect("mining tempdir should exist");
        let router = Arc::new(std::sync::Mutex::new(
            crate::magician_v2::api_mining::router::ApiRouter::with_base_path(
                &crate::config::ApiMiningConfig::default(),
                mining_dir.path(),
            ),
        ));
        let executors =
            ActionExecutors::new(Arc::new(MockLlmService::new(vec![])), test_prompt_manager())
                .with_secret_store(store.clone())
                .with_api_router(router);
        *executors
            .api_mining_run
            .last_page_url
            .lock()
            .expect("page-url lock should not be poisoned") =
            Some("https://app.example.com/dashboard".to_string());

        let observed = json!({
            "networkTraces": [{
                "request_id": "req-1",
                "method": "GET",
                "url": "https://api.example.com/orders",
                "resource_type": "XHR",
                "frame_id": null,
                "request_headers": {},
                "request_body": null,
                "response_headers": {},
                "response_body": null,
                "status": 200,
                "timing": {
                    "request_time": 0.0,
                    "dns_duration": null,
                    "connect_duration": null,
                    "ssl_duration": null,
                    "ttfb": null,
                    "total_duration": 12.0
                },
                "initiator": {
                    "initiator_type": "script",
                    "stack": null,
                    "url": "https://app.example.com/dashboard"
                },
                "timestamp": 0,
                "request_size": 0,
                "response_size": 0
            }],
            "browserState": {
                "cookies": [{
                    "name": "session",
                    "value": "shared-cookie",
                    "domain": ".example.com",
                    "path": "/",
                    "secure": true,
                    "httpOnly": true,
                    "sameSite": "lax"
                }],
                "storage": [{
                    "tabId": 1,
                    "url": "https://app.example.com/dashboard",
                    "localStorage": { "refresh": "page-refresh" },
                    "sessionStorage": { "csrf": "page-csrf" }
                }]
            }
        });

        store_observed_browser_session_state_for_mining(&observed, &executors);

        let (api_session, _) = store
            .get_session("https://api.example.com", "https://api.example.com/orders")
            .expect("traced API origin should receive captured cookies");
        assert_eq!(
            api_session.cookies.get("session").map(String::as_str),
            Some("shared-cookie")
        );
        assert!(
            api_session.local_storage.is_empty(),
            "page storage must not be copied onto a sibling API origin"
        );
        assert!(
            api_session.session_storage.is_empty(),
            "page storage must not be copied onto a sibling API origin"
        );

        let (page_session, _) = store
            .get_session(
                "https://app.example.com",
                "https://app.example.com/dashboard",
            )
            .expect("page origin should keep its browser storage");
        assert_eq!(
            page_session
                .local_storage
                .get("refresh")
                .map(String::as_str),
            Some("page-refresh")
        );
        assert_eq!(
            page_session.session_storage.get("csrf").map(String::as_str),
            Some("page-csrf")
        );
    }

    #[tokio::test]
